// Prewritten short definitions; ordinary expansion needs no model request.
export const compiledTermNotes={"network":{"concept:发送窗口":{"definition":"发送窗口是发送方当前允许发送的序号范围，限制最多能有多少数据尚未确认。窗口内已发送的数据仍需保留，以便重传。","purpose":"允许连续发送多份数据，同时约束未确认数据量；具体上限由协议规则和对端条件决定。","example":"某协议允许三帧未确认，发送方连发三帧后，需等确认推进窗口才能继续。"},"concept:接收窗口":{"definition":"接收窗口是接收方当前允许接收的序号范围。在传输控制协议（TCP）中，通告的接收窗口反映接收方还能接纳的数据量。","purpose":"帮助发送方控制发送量，避免接收方缓冲区被填满；窗口范围也可用于判断数据能否接收。","example":"接收方通告还可接收两千字节，发送方据此限制尚未确认的数据量。"},"concept:滑动窗口":{"definition":"滑动窗口是用随通信进展移动的序号范围，管理数据发送和接收的机制。发送窗口通常随有效确认推进，接收窗口按接收规则推进。","purpose":"让多份数据可以连续在途，并结合序号、确认和重传兼顾效率与可靠性。","example":"发送窗口原本覆盖第十到第十三帧，前两帧获确认后，可向后移动并发送新帧。"},"concept:超时重传":{"definition":"超时重传是发送方在规定时间内没有获得所需确认时，再次发送有关数据的机制。超时只表示未及时获确认，不能断定数据已经丢失。","purpose":"在数据或确认丢失时恢复传输，使通信不至于一直等待。","example":"接收方已收到一份数据，但确认途中丢失，发送方等待超时后再次发送。"},"concept:超时计时器":{"definition":"超时计时器是发送方用来衡量等待确认时间的计时机制。计时达到设定期限而所需确认仍未到达，就触发协议规定的处理。","purpose":"为重传提供触发依据；期限应考虑往返时延及其波动，兼顾及时恢复与减少误重传。","example":"某帧发送后开始计时，确认在期限内到达，发送方按协议停止或调整计时。"},"concept:独立确认":{"definition":"独立确认是把确认信息放在单独的确认帧或报文中发送，而不是附在反向发送的业务数据中。它描述确认的携带方式。","purpose":"即使接收方暂时没有业务数据要发送，也能及时告知对方接收情况。","example":"设备收到一帧数据后没有内容要回传，于是专门发送一帧确认信息。"},"concept:连续ARQ":{"definition":"连续自动重传请求（ARQ）是一类允许发送方在收到确认前连续发送多帧的可靠传输协议，常见方式有回退N帧和选择重传。","purpose":"减少逐帧等待确认造成的空闲，提高链路利用率，并通过确认与重传处理差错。","example":"发送方先连续发出四帧，再依据陆续到达的确认推进窗口并补发新帧。"},"concept:停等协议":{"definition":"停等协议规定发送方每发送一份数据，就等待相应确认，确认到达后才发送下一份。可靠停等还需结合序号、检错和超时重传。","purpose":"用较简单的控制方式限制在途数据，并在加入重传机制后应对丢失和差错。","example":"终端发出一条记录，收到接收成功的确认后，再发送下一条记录。"},"concept:确认帧":{"definition":"确认帧是链路通信中用于反馈接收情况的控制帧。其确认号可能表示已收到的帧，也可能表示下一帧期望的序号，须看协议约定。","purpose":"让发送方判断哪些数据已获确认，从而释放缓存、推进窗口或管理重传。","example":"某协议约定确认号表示下一帧期望序号，接收方收齐此前各帧后发出相应确认。"},"concept:否定确认":{"definition":"否定确认（NAK，Negative Acknowledgment）是接收方明确反馈某份数据未正确接收或需要重传的信息，并非所有可靠协议都使用它。","purpose":"在协议支持且能识别问题数据时，促使发送方较早重传，减少等待超时的时间。","example":"接收方发现某帧校验失败，且能确定其序号，便发送指明该帧的否定确认。"},"concept:序号空间":{"definition":"序号空间是协议可使用的全部序号值的集合。使用固定比特数编码时，序号用完后通常循环，旧数据与新数据可能出现相同序号。","purpose":"为数据标识和窗口设计提供范围；协议需限制窗口或数据存活时间，避免新旧数据混淆。","example":"采用两位序号时，序号空间包含四个值，循环使用前要防止旧帧被误认成新帧。"},"concept:帧序号":{"definition":"帧序号是按协议规则分配给数据帧的编号，通常位于帧首部。它可能循环使用，因此并不是一帧在整个通信历史中的唯一身份。","purpose":"帮助接收方识别顺序、重复和缺失，并让确认及重传能够关联相应的数据帧。","example":"某帧的确认丢失后被重传，接收方结合序号与当前接收状态识别重复，避免再次交付。"},"concept:码元":{"definition":"数字信号中占据一个符号时段的基本单位，可用不同状态携带信息。","purpose":"把比特映射成可通过信道传送的信号。","example":"四种不同相位各代表一种两位比特组合。"},"concept:波特率":{"definition":"每秒传送的码元数，单位为波特，不一定等于每秒传送的比特数。","purpose":"描述信号发送码元的快慢。","example":"某链路每秒发送一千个码元，波特率就是一千波特。"},"concept:曼彻斯特编码":{"definition":"每个比特中间必有电平跳变，用跳变方向区分零和一的编码。","purpose":"让接收方从信号中提取时钟，保持同步。","example":"双方约定中间由低变高表示一，由高变低表示零。"},"concept:透明传输":{"definition":"允许载荷包含任意数据，并保证其中的特殊内容不会被误当控制信息。","purpose":"使数据内容不受协议定界规则限制。","example":"文件里含有与帧结束标记相同的字节，也能完整传送。"},"concept:字节填充":{"definition":"发送方在数据中的特殊字节前插入转义字节，接收方按规则还原。","purpose":"避免数据字节被误认成边界或控制标记。","example":"数据中出现结束标记时，先加转义字节再发送。"},"concept:比特填充":{"definition":"发送方按约定在特定比特序列后插入额外位，接收方再将其删除。","purpose":"防止数据位串与帧定界标志混淆。","example":"一种规则是在连续五个一后插入零，接收时去掉该零。"},"concept:定界符":{"definition":"协议预先约定的特殊标记，用来指出帧或字段的起点、终点。","purpose":"帮助接收方从连续数据中识别边界。","example":"接收方遇到约定的结束标记，就知道当前帧已经结束。"},"concept:CSMA/CD":{"definition":"载波监听多路访问／碰撞检测，是共享半双工以太网的介质访问方法。","purpose":"协调多站共享介质，并检测发送中的碰撞。","example":"两台接入集线器的电脑同时发送，可能检测到碰撞。"},"concept:CSMA/CA":{"definition":"载波监听多路访问／碰撞避免，通过监听和随机退避等办法减少碰撞。","purpose":"协调无线共享信道，降低同时发送的机会。","example":"无线终端发现信道忙，就推迟发送并按规则竞争接入。"},"concept:二进制指数退避":{"definition":"重试次数增加时，按规则将随机等待范围成倍扩大，并设置增长上限。","purpose":"降低多个站点反复同时重传的概率。","example":"发生多次碰撞后，设备从更大的时隙范围随机选择等待时间。"},"concept:碰撞域":{"definition":"共享同一竞争介质、同时发送可能发生碰撞的一组接口及链路范围。","purpose":"判断哪些设备会争用介质并相互影响。","example":"多台电脑连接同一集线器时，通常处于同一碰撞域。"},"concept:冲突域":{"definition":"与碰撞域同义，指共享介质上同时发送可能产生信号冲突的范围。","purpose":"分析共享以太网中的介质争用范围。","example":"网桥将两个共享网段分开，可阻止一侧碰撞影响另一侧。"},"concept:广播域":{"definition":"一个二层广播帧能够被转发到的网络范围，通常受虚拟局域网边界限制。","purpose":"界定广播传播范围，辅助网络分区。","example":"路由器连接的两个局域网通常属于不同广播域。"},"concept:最小帧长":{"definition":"协议规定的帧长度下限，共享以太网用它保证发送期间能够检测碰撞。","purpose":"避免帧发完后才收到远端碰撞信号。","example":"以太网数据不足时加入填充，使规定范围内的帧长达标。"},"concept:交换表":{"definition":"二层交换机保存的转发表，记录媒体访问控制地址、所属虚拟局域网与端口的对应关系。","purpose":"帮助交换机选择帧应从哪个端口转发。","example":"表中记录某主机位于端口三，发往它的帧便定向转发。"},"concept:自学习":{"definition":"交换机根据收到帧的源地址与入端口，自动建立或更新转发表记录。","purpose":"自动掌握主机位置，减少人工配置。","example":"电脑换到新端口后发出帧，交换机据此更新其位置。"},"concept:泛洪":{"definition":"交换机将帧复制到所属虚拟局域网内除入端口外的其他允许转发端口。","purpose":"传递广播或寻找目的位置未知的主机。","example":"目的地址尚未入表时，交换机向多个可能的出口复制帧。"},"concept:MAC地址":{"definition":"MAC全称媒体访问控制；其地址用于链路层标识接口，以太网中通常为四十八位。","purpose":"帮助同一二层网络中的帧找到目标接口。","example":"一台电脑的有线网卡和无线网卡通常各有自己的地址。"},"concept:广播地址":{"definition":"表示向指定范围内所有节点发送的特殊目的地址，具体格式随协议而异。","purpose":"让发送方一次发送便能通知范围内各节点。","example":"以太网用四十八位全一的目的地址表示链路层广播。"},"concept:全双工":{"definition":"通信双方能够在同一时间分别向对方发送数据，两个方向可同时工作。","purpose":"支持双向并行传输，提高通信效率。","example":"两台设备通过全双工链路连接，可同时互传文件。"},"concept:半双工":{"definition":"通信双方都能发送和接收，但同一时刻只能有一个方向传送数据。","purpose":"在不能同时双向传输的链路上实现交互。","example":"普通对讲机一方按键讲话时，另一方需要等待再回应。"},"concept:VLAN":{"definition":"全称虚拟局域网，将交换网络逻辑划分为多个独立二层广播域。","purpose":"按部门或用途分组，限制广播传播范围。","example":"同一交换机上的访客设备与办公设备可划入不同分组。"},"concept:IEEE 802.11":{"definition":"电气和电子工程师协会制定的无线局域网标准系列，规定物理层和介质访问控制。","purpose":"规范无线设备接入与传输，支持互通。","example":"无线网卡与接入点采用兼容标准，即可建立无线连接。"},"concept:隐藏终端":{"definition":"共享无线信道中，终端彼此无法监听，却能向同一接收方发送的现象。","purpose":"解释监听显示空闲时，接收端仍可能发生碰撞。","example":"隔墙两侧的设备互相听不到，同时上传时可能干扰接入点。"},"concept:重复帧":{"definition":"同一原始帧因重传等原因，再次到达接收方形成的副本。","purpose":"需要识别并丢弃，避免同一数据重复交付。","example":"某帧已被接收，发送方重传后，接收方凭序号识别副本。"},"concept:乱序缓存":{"definition":"接收方暂存先到但次序靠后的数据，等待前面缺失数据的空间。","purpose":"保留已收到的数据，减少后续重复传输。","example":"编号十的数据先到，九尚未到，接收方先把十存起来。"},"concept:按序交付":{"definition":"接收方按发送顺序向上层交数据，缺口后的数据暂不交付。","purpose":"使上层获得顺序正确、连续的数据内容。","example":"文件第二段尚未收到，第三段即使到达也先等待。"},"concept:确认丢失":{"definition":"接收方发出的接收确认在途中丢失，发送方未能收到。","purpose":"分析它可解释数据已收到却仍发生重传的原因。","example":"接收方已收好报文，但返回的确认因链路故障丢失。"},"concept:超时值":{"definition":"从启动或重启计时到允许判超时的时间间隔；TCP的RTO指重传超时间隔，不是一个绝对时刻。","purpose":"先确定等待多长，再结合计时起点判断何时到期。","example":"计时在时刻t开始，允许等待Δ时间，则到期时刻是t加Δ，间隔与时刻分别记录。"},"concept:有效载荷":{"definition":"协议数据单元中承载上层数据的部分，不含本层控制开销。","purpose":"区分实际承载内容与首部等额外开销。","example":"以太网帧携带的网络层数据属于该帧的有效载荷。"},"concept:首部":{"definition":"协议数据单元前部的控制信息，具体字段由对应协议规定。","purpose":"提供寻址、解析和传输控制所需的信息。","example":"收件设备读取报文首部中的长度字段，确定如何解析数据。"},"concept:存储转发":{"definition":"节点先接收完整分组并存储，再向选定的下一跳发送。","purpose":"支持分组检查、缓存以及下一跳转发。","example":"交换机收完整帧并检查后，才从目标端口发出该帧。"},"concept:首比特":{"definition":"某次传输的数据单元中，按发送顺序最先发出的那一位。","purpose":"作为计时参考，区分发送开始和信号到达。","example":"观察一帧首比特到达远端的时刻，可研究链路传播时间。"},"concept:末比特":{"definition":"某次传输的数据单元中，按发送顺序最后发出的那一位。","purpose":"用来判断完整数据何时发完或收齐。","example":"接收端等到一帧末比特到达，才算收齐这一帧。"},"concept:信道利用率":{"definition":"指定统计时间内，信道用于所计数据传输的时间比例。","purpose":"衡量链路忙闲程度，分析等待造成的损失。","example":"观察一秒，其中零点六秒发送数据帧，按此口径利用率为六成。"},"concept:带宽时延积":{"definition":"数据速率与指定时延的乘积。用单程传播时延时，它是连续发送填满链路传播路径的数据量尺度；有限短分组的实际在途量可能更少。","purpose":"先明确采用单程传播还是RTT口径；区分满管道尺度、实际在途量和未确认窗口，不能只见速率与时延就当实际数据量。","example":"管道虽能容纳很多数据，发送端只发了很短的一小包时，里面就没有满额的比特。"},"concept:单程传播时延":{"definition":"信号从链路一端传播到另一端所需的时间，不含发送耗时。","purpose":"衡量距离和传播速度带来的等待时间。","example":"光信号进入光纤后，到达另一端仍需一段传播时间。"},"concept:端到端时延":{"definition":"数据从源端到目的端的总耗时，须明确起止事件和测量范围。","purpose":"评价通信响应速度，定位各环节的耗时。","example":"测量一个分组从开始发送到远端收齐，包含沿途多项时延。"},"concept:排队时延":{"definition":"分组进入节点缓冲区后，等待获得发送服务所花的时间。","purpose":"分析流量拥挤引起的延迟和时延波动。","example":"出口正在发送其他分组，新到分组在缓冲区等待。"},"concept:处理时延":{"definition":"节点检查分组、解析首部并决定转发方式等操作所需的时间。","purpose":"估算节点处理工作对通信总耗时的影响。","example":"路由器查询转发表并确定出口，需要一定处理时间。"},"concept:瓶颈链路":{"definition":"路径中限制端到端吞吐量的链路，取决于可用传输能力。","purpose":"找出吞吐量受限位置，指导扩容和流量调整。","example":"多用户共享的出口拥挤，即使内网很快，下载仍受出口限制。"},"concept:检错能力":{"definition":"一种校验方法能够保证发现哪些差错及多少位差错的能力。","purpose":"判断校验方案能覆盖哪些传输错误。","example":"某编码保证发现任意两位翻转，但未必发现所有三位翻转。"},"concept:突发差错":{"definition":"首个与末个错误位之间的一段差错，中间允许存在正确位。","purpose":"描述集中出现的错误，帮助选择校验方案。","example":"连续七位中只有第一、四、七位出错，突发长度仍为七。"},"concept:奇偶校验":{"definition":"添加校验位，使受保护位串中一的总数满足规定的奇偶性。","purpose":"用较少开销检测部分位翻转差错。","example":"数据为一零一时，采用偶校验可补一个零保持一的总数为偶数。"},"concept:汉明距离":{"definition":"两个等长位串中，对应位置取值不同的位数。","purpose":"用码字间最小距离衡量检错和纠错能力。","example":"位串一零一一与一一零一，在两个位置不同，距离为二。"},"concept:香农定理":{"definition":"给出带限加性白高斯噪声信道在指定信噪比下的容量上限。","purpose":"判断给定带宽和噪声条件下的理论速率极限。","example":"在该模型中，保持带宽不变并提高信噪比，理论容量会增大。"},"concept:奈奎斯特定理":{"definition":"无噪声理想低通信道带宽为B时，无码间干扰码元率上限为2B。","purpose":"联系带宽、码元率与每码元携带的比特数。","example":"理想条件下，每码元由二种状态增为四种，可多携带一比特。"},"concept:信噪比":{"definition":"同一测量位置和带宽内，信号功率与噪声功率的比值。","purpose":"衡量噪声干扰程度，辅助评估接收可靠性。","example":"接收信号功率为噪声的百倍，信噪比就是二十分贝。"},"concept:距离向量":{"definition":"路由器记录到各目的网络的距离和下一跳，并与邻居交换距离信息。","purpose":"根据邻居信息逐步更新本地路由。","example":"某邻居到学校网需两跳，本机可经它再走一跳。"},"concept:洪泛":{"definition":"节点把收到的信息向其他相邻链路复制转发，使其逐步扩散。","purpose":"让网络内多个节点收到同一信息。","example":"路由器传播链路变化时，用序号识别并丢弃重复消息。"},"concept:Dijkstra":{"definition":"迪杰斯特拉算法从源点出发，逐次确定最近节点，要求边权非负。","purpose":"计算源点到各可达节点的最短路径。","example":"导航将路程作为非负边权，逐步确定最近的路口。"},"concept:Bellman-Ford":{"definition":"贝尔曼—福特算法反复用各条边更新距离，求解单源最短路径。","purpose":"支持负边权，并可检测源点可达的负环。","example":"某条直达路线费用较高，算法可改选经中转的便宜路线。"},"concept:OSPF":{"definition":"OSPF全称开放最短路径优先，是自治系统内使用的链路状态路由协议。","purpose":"根据链路状态计算内部转发路径。","example":"校园新增一条骨干链路后，各路由器据此重新选路。"},"concept:RIP":{"definition":"RIP全称路由信息协议，是以跳数衡量路径的距离向量路由协议。","purpose":"通过邻居间交换信息维护内部路由。","example":"小型办公网可比较两条路线的跳数，优先选择较少者。"},"concept:BGP":{"definition":"BGP全称边界网关协议，是依据路径属性和策略交换路由的协议。","purpose":"主要用于自治系统之间交换可达信息。","example":"企业同时接入两家运营商，可按出口策略选择路线。"},"concept:AS":{"definition":"AS全称Autonomous System，即统一管理并采用明确路由策略的一组网络。","purpose":"作为互联网跨域路由的管理单位。","example":"一家运营商管理的多个网络，可以共同组成一个AS。"},"concept:自治系统":{"definition":"自治系统是由同一管理方控制、对外采用明确路由策略的一组网络。","purpose":"划分路由管理范围，协调内外部选路。","example":"大学统一管理多个校区网络，对外实行共同的出口策略。"},"concept:毒性逆转":{"definition":"把经某邻居到达的目的地，向该邻居通告为不可达的路由更新规则。","purpose":"减少两个路由器之间的路由环路。","example":"甲经乙到某网段时，会向乙报告自己不能到该网段。"},"concept:计数到无穷":{"definition":"距离向量路由中，故障后节点误信彼此的旧路由，使距离不断增大。","purpose":"用于解释坏消息传播慢和路由收敛问题。","example":"出口断开后，两台路由器互指对方，通告跳数逐轮上升。"},"concept:链路代价":{"definition":"链路代价是给网络连接设置的权值，可按带宽、时延或管理策略确定。","purpose":"供选路算法比较不同路径的开销。","example":"管理员把拥挤线路设为较高代价，让流量优先走另一条。"},"concept:最短路径树":{"definition":"以一个源点为根，使树上到每个可达节点的路径都是最短路径的树。","purpose":"集中表示该源点到各目的地的最优路线。","example":"以办公楼路由器为根，可画出它到各机房的最短路线。"},"concept:路由通告":{"definition":"路由通告是路由设备向其他设备发布可达网络、距离或路径属性的信息。","purpose":"让其他设备学习和更新转发路线。","example":"分支网络上线后，边界路由器向邻居发布其网段信息。"},"concept:IPv4":{"definition":"IPv4全称互联网协议第四版，使用32位地址，在网络间传送数据报。","purpose":"提供逻辑寻址和跨网络的数据转发。","example":"电脑可配置192.0.2.8这一IPv4地址用于实验。"},"concept:IPv6":{"definition":"IPv6全称互联网协议第六版，使用128位地址，采用基本首部和扩展首部。","purpose":"扩大地址空间，支持互联网持续发展。","example":"实验主机可使用2001:db8::5这样的IPv6地址。"},"concept:分片偏移":{"definition":"分片偏移表示本片数据在原数据报数据部分中的位置，单位为8字节。","purpose":"帮助接收端把各分片放回正确位置。","example":"某片数据从原数据部分第80字节开始，偏移字段记为10。"},"concept:更多分片":{"definition":"更多分片标志MF全称More Fragments，表示本片之后是否还有分片。","purpose":"帮助接收端判断原数据报的分片边界。","example":"一个数据报分成三片，第一片需表明后面仍有分片。"},"concept:首部长度":{"definition":"IPv4首部长度字段表示首部占多少个4字节单位，包含选项部分。","purpose":"帮助接收方确定数据部分的起始位置。","example":"若首部含额外选项，其长度会增加，数据起点随之后移。"},"concept:生存时间":{"definition":"生存时间TTL全称Time To Live，IPv4转发时逐跳递减，耗尽即丢弃。","purpose":"限制数据报在网络中持续循环。","example":"某报文陷入环路后，会因该字段不断减小而最终被丢弃。"},"concept:重组":{"definition":"重组是接收端依据标识、偏移等信息，把同一数据报的分片恢复为整体。","purpose":"恢复完整数据，供后续协议处理。","example":"几个分片先后乱序到达，接收端按位置拼接后再交付。"},"concept:IP地址":{"definition":"IP是互联网协议的缩写；IP地址是分配给网络接口的逻辑地址。","purpose":"标识通信接口，并支持跨网络选路。","example":"一台连接两个子网的路由器，通常为两个接口分别配置地址。"},"concept:TCP":{"definition":"TCP全称传输控制协议，为应用提供面向连接、可靠且有序的字节流。","purpose":"通过确认、重传等机制可靠传输数据。","example":"下载文档时，某段数据丢失可被重传，应用仍按顺序读取。"},"concept:UDP":{"definition":"UDP全称用户数据报协议，提供无连接的报文传输，不保证送达和顺序。","purpose":"以较少协议开销传送独立消息。","example":"语音应用可用它发送音频包，并自行处理丢包造成的缺音。"},"concept:暴露终端":{"definition":"无线站听到邻站发送而推迟发送，但它的发送原本不会干扰对方接收。","purpose":"用于分析无线信道被过度避让、利用不足的问题。","example":"甲向乙发送时，丙本可向远处丁发送，却因听到甲而等待。"},"concept:RTS/CTS":{"definition":"RTS是请求发送，CTS是允许发送，是无线数据发送前可选的短帧握手。","purpose":"帮助预约信道，减少长数据帧碰撞造成的损失。","example":"电脑先发请求，接入点回应许可，听到许可的邻站暂缓发送。"},"concept:BSS":{"definition":"BSS全称基本服务集，是无线局域网的基本单元；基础设施型包含接入点和关联站。","purpose":"组织一组无线设备接入和通信。","example":"宿舍一个接入点及关联它的两台手机，可组成一个基本服务集。"},"concept:ESS":{"definition":"ESS全称扩展服务集，由分布式系统连接的多个基础设施基本服务集组成。","purpose":"扩大无线覆盖范围，支持终端在覆盖区内漫游。","example":"图书馆各楼层的多个接入点联合提供同一无线网络服务。"},"concept:SSID":{"definition":"SSID全称服务集标识，是无线网络的名称，不能唯一标识一个接入点。","purpose":"帮助用户和终端识别、选择要加入的无线网络。","example":"校园多栋楼都显示Campus这一网络名，但连接的接入点不同。"},"concept:切换":{"definition":"切换是把服务或通信从当前设备、链路或路径转移到另一可用对象的过程。","purpose":"用于故障恢复、移动接入或调整服务负载。","example":"主服务器发生故障后，系统让备用服务器开始接收新请求。"},"concept:关联":{"definition":"关联是用标识或映射把请求、设备或状态联系起来，具体含义取决于场景。","purpose":"让系统找到当前交互对应的对象或历史状态。","example":"网站用浏览器携带的会话编号，找到该用户先前保存的购物车。"},"concept:无线衰减":{"definition":"无线衰减是电磁信号传播时，因距离、遮挡等因素导致接收功率降低。","purpose":"用于评估覆盖范围，安排接入点位置和发射功率。","example":"手机离路由器更远且隔了两堵墙，接收到的信号通常更弱。"},"concept:多径传播":{"definition":"多径传播是同一无线信号经不同路径到达接收端，形成延迟不同的副本。","purpose":"用于分析信号衰落、失真及接收机的补偿需求。","example":"地下车库里，信号沿直线路径和车辆反射路径先后到达手机。"},"concept:DHCP":{"definition":"DHCP全称动态主机配置协议，可按租约为主机分配地址及其他网络参数。","purpose":"减少手工配置，集中管理地址和配置的有效期。","example":"笔记本接入办公室网络后，自动取得地址、网关和域名服务器配置。"},"concept:ARP":{"definition":"ARP全称地址解析协议，用于在本地链路查询某个IPv4地址对应的链路层地址。","purpose":"帮助发送方确定本地交付帧所需的目的地址。","example":"电脑发送数据前，先询问同网段打印机的硬件地址并缓存结果。"},"concept:ICMP":{"definition":"ICMP全称互联网控制报文协议，用于传递IP网络的差错报告和诊断信息。","purpose":"帮助发现不可达、转发异常及网络连通性问题。","example":"管理员发送回送请求，观察目标是否回复，以辅助检查网络连通性。"},"concept:NAT":{"definition":"NAT全称网络地址转换，在网络边界改写报文中的IP地址，常同时转换端口。","purpose":"连接不同地址空间，并可让多台内网设备共享公网地址。","example":"家中两台电脑经路由器转换地址和端口，共用一个公网地址上网。"},"concept:子网掩码":{"definition":"子网掩码是区分IPv4地址前缀与主机部分的32位值，通常由连续的1后接0。","purpose":"帮助计算所属子网，并判断目标是否在本地子网。","example":"使用255.255.255.0时，地址前三个字节属于网络前缀。"},"concept:网络前缀":{"definition":"网络前缀是IP地址中由前缀长度指定的高位部分，用来表示一个地址块。","purpose":"用于划分网络、描述路由覆盖的目的地址范围。","example":"172.22.0.0/16表示前16位固定，后面的位用于区分块内地址。"},"concept:主机号":{"definition":"主机号是IP地址去掉网络前缀后剩余的低位部分，其长度取决于前缀长度。","purpose":"区分同一子网内的地址，分配时还须考虑保留规则。","example":"在192.168.6.23/24中，最后8位是主机部分，其数值为23。"},"concept:网络地址":{"definition":"IPv4网络地址是保留网络前缀、将主机部分全部置零后得到的子网标识。","purpose":"用于表示整个子网，供地址规划和路由配置使用。","example":"192.168.12.99/24所属子网的网络地址是192.168.12.0。"},"concept:最长前缀匹配":{"definition":"最长前缀匹配是在多条匹配目的地址的路由中，选择前缀位数最多的一条。","purpose":"让更具体的目的地址范围优先决定转发方向。","example":"某地址同时匹配/12和/20路由时，转发采用更具体的/20路由。"},"concept:路由汇聚":{"definition":"路由汇聚是将具有共同前缀的多个地址块，用一个较短前缀统一表示。","purpose":"减少路由条目和通告量，同时需控制额外覆盖范围。","example":"192.168.8.0/24与192.168.9.0/24可汇成192.168.8.0/23。"},"concept:默认路由":{"definition":"默认路由是前缀长度为零的路由，在没有更具体的匹配路由时使用。","purpose":"为未知目的网络提供统一出口，简化路由配置。","example":"家庭电脑把路由表未具体列出的外网目的流量交给家庭网关。"},"concept:下一跳":{"definition":"下一跳是数据包沿选定路由转发时，接下来交付的相邻路由器或节点。","purpose":"明确本次转发应交给谁，逐跳推进到目的地。","example":"分公司路由器把去总部的数据包，先交给专线另一端的路由器。"},"concept:数据平面":{"definition":"数据平面是网络设备按已有转发表或规则，对实际数据包执行处理的部分。","purpose":"承担查表、转发、丢弃等逐包处理工作。","example":"交换设备查到某帧对应的出口后，直接从指定端口把它发送出去。"},"concept:控制平面":{"definition":"控制平面是计算、学习和维护网络转发规则的部分，可分布运行或集中控制。","purpose":"决定转发路径和策略，并把规则提供给数据平面。","example":"链路断开后，路由协议重新计算路径，并更新设备中的转发表。"},"concept:链路状态":{"definition":"链路状态是链路是否可用、连接哪些节点及代价等信息，也是某类路由算法的依据。","purpose":"帮助建立拓扑图，并据此计算到各目的地的路径。","example":"某条链路断开后，路由器通告变化，各节点更新拓扑并重新选路。"},"concept:资源记录":{"definition":"域名系统（DNS）中保存的一条结构化数据，包含名称、类型、有效期和值。","purpose":"描述域名对应的信息，供解析查询使用。","example":"某条邮件交换记录指出该域由哪台邮件服务器收信。"},"concept:DNS缓存":{"definition":"域名系统（DNS）缓存是暂存查询结果、在有效期内供后续复用的机制。","purpose":"减少重复解析的等待和查询流量。","example":"刚查过某网站域名，再次查询时可使用尚未过期的结果。"},"concept:HTTP":{"definition":"超文本传输协议（HTTP）是规定客户端与服务器如何交换请求和响应的应用层协议。","purpose":"传送网页、图片及接口数据等内容。","example":"天气应用发送查询请求，服务器返回当天的气温数据。"},"concept:持久连接":{"definition":"在超文本传输协议中，持久连接允许同一传输连接承载多次请求和响应。","purpose":"复用已有连接，减少反复建连的开销。","example":"浏览器沿用一条连接，先后获取网站图标和样式文件。"},"concept:非持久连接":{"definition":"在超文本传输协议中，非持久连接完成一次请求响应后关闭，不供后续请求复用。","purpose":"提供一次性交互，结束后释放连接资源。","example":"客户端下载一个文本文件后关闭连接，下次下载重新建连。"},"concept:请求响应":{"definition":"请求响应是一方提出操作或数据需求，另一方处理后返回结果的交互方式。","purpose":"让双方按明确的需求与结果交换信息。","example":"客户端请求商品库存，服务器查询后返回剩余数量。"},"concept:Cookie":{"definition":"Cookie是服务器要求浏览器保存、浏览器随后按域名和路径等规则随请求携带的小段数据。","purpose":"关联登录会话、购物车或用户偏好。","example":"用户选择深色主题后，下次访问时网站据此恢复设置。"},"concept:缓存命中":{"definition":"所需内容已经在缓存中且可以直接采用，无需再次完整取得；没有可用内容则称未命中。","purpose":"分别分析从缓存取得内容与重新取得内容的成本。","example":"第一次取到一张图片并缓存后，下次请求可能直接复用它。"},"concept:条件GET":{"definition":"条件获取请求（条件GET）是在获取资源时附带条件，仅在条件满足时返回资源内容。","purpose":"核验缓存版本，避免重复传送未变内容。","example":"浏览器携带旧版本标识查询公告，未更新时只收到状态响应。"},"concept:SMTP":{"definition":"简单邮件传输协议（SMTP）是用于提交和转发电子邮件的应用层协议。","purpose":"将邮件交给邮件服务器并逐步转送。","example":"邮件客户端通过该协议，把写好的通知提交给发件服务器。"},"concept:POP3":{"definition":"邮局协议第三版（POP3）是客户端从邮件服务器取回邮件的应用层协议。","purpose":"下载邮箱邮件，便于在本地阅读管理。","example":"电脑收取新邮件后离线阅读，并按设置保留服务器副本。"},"concept:IMAP":{"definition":"互联网消息访问协议（IMAP）允许客户端访问服务器邮箱并同步文件夹和消息状态。","purpose":"支持多设备围绕服务器邮箱协同管理。","example":"手机把邮件标为已读，电脑刷新邮箱后也显示已读。"},"concept:FTP":{"definition":"文件传输协议（FTP）使用分开的控制连接和数据连接，在客户端与服务器间传文件。","purpose":"支持文件上传、下载及远程目录操作。","example":"管理员登录文件服务器，把更新包上传到指定目录。"},"concept:对称加密":{"definition":"对称加密通常使用同一把秘密密钥完成加密和解密，通信双方必须妥善保密。","purpose":"高效保护大量数据的内容机密性。","example":"备份程序用秘密密钥加密文件，恢复时用同一密钥解密。"},"concept:非对称加密":{"definition":"非对称加密使用配对的公钥和私钥，以公钥加密的数据由对应私钥解密。","purpose":"让发送方无需先共享秘密便能加密数据。","example":"用户用机构可信公钥加密申请材料，由机构私钥解密。"},"concept:数字签名":{"definition":"数字签名是用私钥对消息生成可验证的签名，再由对应公钥检验的密码机制。","purpose":"核验消息完整性及其与签名者的关联。","example":"软件开发者签署安装包，用户用可信公钥检查其是否被篡改。"},"concept:消息摘要":{"definition":"消息摘要是哈希函数把任意长度消息映射得到的固定长度值，不同消息仍可能碰撞。","purpose":"辅助检查内容变化，也用于构造签名。","example":"下载文件后计算摘要，与可信渠道公布的值进行比对。"},"concept:公钥":{"definition":"公钥是非对称密码中可公开的密钥，与私钥配对，可按算法用于加密或验签。","purpose":"供他人执行加密或验证等公开操作。","example":"软件官网公布签名公钥，供用户核验更新包的签名。"},"concept:私钥":{"definition":"私钥是非对称密码中必须保密的密钥，与公钥配对，可按算法用于解密或签名。","purpose":"执行需要持有者秘密才能完成的操作。","example":"发布者把签名私钥存入安全设备，用它签署新版软件。"},"concept:证书":{"definition":"数字证书是由签发者签名、记载主体身份与公钥等信息的电子凭据，使用时需验证。","purpose":"帮助建立公钥与所声明身份的可信绑定。","example":"浏览器访问网银时，检查服务器证书的域名、有效期和信任链。"},"concept:重放攻击":{"definition":"重放攻击是攻击者截获先前有效的消息，随后再次发送，诱使接收方重复接受。","purpose":"说明为何协议需要随机挑战或序号防重。","example":"攻击者重发旧开门指令，试图让门锁再次执行开锁。"},"concept:中间人攻击":{"definition":"中间人攻击是攻击者介入双方通信，冒充对方转发或篡改信息而不被及时发现。","purpose":"说明通信为何需要认证身份和保护完整性。","example":"伪装热点替换通信公钥，诱使双方经攻击者转交秘密数据。"},"concept:防火墙":{"definition":"防火墙是在主机或网络边界，按预设规则检查并允许或阻止网络通信的安全机制。","purpose":"限制不需要的访问，落实通信访问策略。","example":"公司只允许外部访问网站端口，阻止直接连接内部数据库。"},"concept:密钥交换":{"definition":"密钥交换是通信双方通过协议建立共同秘密密钥的过程，抵御冒充通常还需身份认证。","purpose":"为后续加密通信准备双方共享的密钥。","example":"视频会议开始前，双方协商会话密钥，再加密传送音视频。"},"concept:三次握手":{"definition":"传输控制协议建立连接时，双方交换请求、确认请求和最终确认的过程。","purpose":"同步初始序号，确认双方收发能力。","example":"浏览器连接网站时，双方先完成握手再传网页。"},"concept:四次挥手":{"definition":"传输控制协议通常通过双方分别发送结束标志及确认，关闭两个传输方向。","purpose":"让双方各自完成发送后有序关闭连接。","example":"客户端先停止发送，服务器发完剩余内容再关闭。"},"concept:拥塞窗口":{"definition":"传输控制协议发送端依据网络拥塞情况维护的、限制在途数据量的窗口。","purpose":"约束发送规模，降低网络过载风险。","example":"路径出现拥塞信号后，发送端缩小窗口再传文件。"},"concept:接收窗口通告":{"definition":"传输控制协议接收端在报文中告知对方，当前允许接收的数据范围。","purpose":"让发送速度适应接收端的处理能力。","example":"接收缓存释放后，接收端通告可继续接收更多数据。"},"concept:慢启动":{"definition":"传输控制协议从较小拥塞窗口开始，随新数据获确认而较快扩大发送规模的阶段。","purpose":"逐步探测路径能够承受的发送负荷。","example":"新连接上传照片时，先少量发送，再逐步增加。"},"concept:拥塞避免":{"definition":"经典传输控制协议在窗口达到阈值后，以较缓慢的方式增加拥塞窗口的阶段。","purpose":"谨慎探测剩余容量，减少突发拥塞。","example":"文件传输趋稳后，发送端小步增加在途数据量。"},"concept:快速重传":{"definition":"传输控制协议依据重复确认等丢失迹象，在重传定时器到期前补发疑似丢失数据。","purpose":"缩短等待时间，尽早填补接收缺口。","example":"发送端发现某段迟迟未获确认，提前补发该段。"},"concept:快速恢复":{"definition":"经典Reno传输控制协议在快速重传后，调整窗口并利用后续确认恢复传输的机制。","purpose":"在仍有数据流动时维持适度发送。","example":"长文件传输丢失一段后，连接降低速率并继续传输。"},"concept:慢启动阈值":{"definition":"慢启动阈值，英文缩写ssthresh，是用于决定窗口增长阶段的参考界限。","purpose":"帮助切换增长策略，并反映拥塞后的调整。","example":"发生拥塞后调低阈值，下次更早转入缓慢增长。"},"concept:重复ACK":{"definition":"ACK是确认的英文缩写；重复ACK通常指再次通告相同累计确认号的确认报文。","purpose":"提示连续接收进度未前移，辅助发现缺口。","example":"接收端仍缺前面的数据时，再次报告原有接收进度。"},"concept:流量控制":{"definition":"发送端依据接收端通告的接收能力，限制发送数据量的机制。","purpose":"避免发送过快，使接收端来不及接收。","example":"手机处理下载数据较慢时，要求对方少发一些。"},"concept:拥塞控制":{"definition":"端系统根据丢包、时延或显式标记等信号，调整发送负荷的机制。","purpose":"缓解网络过载，帮助共享路径资源。","example":"多台电脑同时下载导致排队，发送端降低发送速率。"},"concept:选择确认":{"definition":"按具体分组或已收区间给出有针对性的确认；SR可确认单个分组，TCP的SACK则额外报告已收字节区间。","purpose":"帮助发送方辨认已收与缺失内容，先按协议分清分组编号和字节区间。","example":"某分组协议确认了后面一份已收分组，并不自动说明前面的分组也已收齐。"},"concept:SYN":{"definition":"SYN全称Synchronize，是传输控制协议首部中用于同步初始序号的控制标志。","purpose":"发起连接，并参与连接建立过程。","example":"客户端开始连接邮件服务器时，发送带此标志的报文。"},"concept:FIN":{"definition":"FIN全称Finish，是传输控制协议首部中表示本方向不再发送数据的控制标志。","purpose":"有序结束一个发送方向，支持半关闭。","example":"客户端发完请求后发送此标志，仍可继续接收回复。"},"concept:字节流":{"definition":"传输控制协议向应用提供的有序字节序列，不保留应用每次写入的消息边界。","purpose":"让应用连续传输数据，自行规定消息格式。","example":"程序连续写入两段文字，接收方可能一次读到全部。"},"concept:端口号":{"definition":"传输层首部中的十六位编号，结合地址和协议区分主机上的通信端点。","purpose":"把收到的数据交给相应应用或服务。","example":"同一服务器用不同端口分别提供网站和邮件服务。"},"concept:伪首部":{"definition":"计算传输层校验和时，临时加入地址、协议及长度等信息形成的辅助结构。","purpose":"将部分网络层信息纳入差错检测。","example":"发送端计算数据报校验和时，也计入源和目的地址。"},"concept:校验和":{"definition":"按规定算法对受保护内容计算出的数值，接收方通过复算检查传输差错。","purpose":"发现部分内容损坏，但不能保证检出全部错误。","example":"传输途中某些位翻转，接收方复算后发现结果不符。"},"concept:DNS":{"definition":"DNS全称Domain Name System，中文为域名系统，是分布式的域名信息查询体系。","purpose":"查询域名对应地址、邮件服务器等记录。","example":"输入学校网站域名后，系统先查询对应服务器地址。"},"concept:递归查询":{"definition":"域名查询方要求被查询服务器负责继续解析，并返回最终结果或失败信息的方式。","purpose":"把后续查询工作交给提供递归服务的一方。","example":"电脑向本地解析器请求地址，由解析器继续寻找结果。"},"concept:迭代查询":{"definition":"域名服务器返回已有答案或下一步查询线索，由查询方继续询问的方式。","purpose":"沿域名层级逐步找到掌握记录的服务器。","example":"解析器收到上级服务器给出的线索后，再询问下一级。"},"concept:权威服务器":{"definition":"域名系统中负责特定区域、掌握该区域正式记录并能给出权威应答的服务器。","purpose":"提供所负责区域的正式域名解析信息。","example":"学校区域的权威服务器保存校内网站的地址记录。"},"concept:根服务器":{"definition":"域名系统中负责根区域的权威服务器，保存顶级域的委派等信息。","purpose":"为解析器寻找顶级域服务器提供入口。","example":"解析器寻找某个域名时，先向根服务器获取查询线索。"},"concept:单表代换":{"definition":"整个加密过程中使用同一张对应表，将每个明文符号替换成固定密文符号。","purpose":"隐藏直接可读内容，但仍会保留符号频率特征。","example":"若表中规定甲换成丁，连续两个甲就变成两个丁。"},"concept:逆映射":{"definition":"根据输出找回对应输入的反向规则；在目标范围内，每个输出须有唯一原像。","purpose":"撤销可逆变换，将编码或替换结果还原。","example":"某替换表把乙变成戊，逆映射便把戊还原成乙。"},"concept:密码学哈希":{"definition":"将任意长度数据变成固定长度摘要，并要求难以反推原文或找到碰撞。","purpose":"辅助检查数据变化，也用于签名等安全机制。","example":"发布软件时附上摘要，下载者可计算并核对文件。"},"concept:十六进制":{"definition":"逢十六进一的计数法，用0至9和A至F表示数位，每位可表示四个二进制位。","purpose":"简洁书写二进制数据，便于查看地址和摘要。","example":"十六进制的2A表示十进制42，可写成字节内容。"},"concept:消息认证码":{"definition":"消息认证码（Message Authentication Code，MAC）是用共享密钥和消息生成的校验标签。","purpose":"检查完整性并认证持钥来源，不能证明唯一发送者。","example":"两台设备共享密钥，为控制指令附标签后再传送。"},"concept:初始化向量":{"definition":"初始化向量（Initialization Vector，IV）是加密起始参数，其要求取决于具体算法模式。","purpose":"使同一密钥下的加密满足所用模式的安全条件。","example":"某模式要求向量不可预测，发送端每次随机生成。"},"concept:盐值":{"definition":"盐值是处理口令时加入的每用户不同的值，通常公开保存，不作为秘密密钥。","purpose":"减少预计算复用，避免相同口令直接得到相同摘要。","example":"两名用户口令相同，采用不同盐值后存储结果不同。"},"concept:离线枚举":{"definition":"拿到可验证的数据后，在本机逐一尝试候选秘密，无须向服务器提交每次猜测。","purpose":"用于口令破解或评估口令抵抗猜测的能力。","example":"攻击者获得口令校验数据后，逐项测试常见词组。"},"concept:TLS":{"definition":"传输层安全协议（Transport Layer Security，TLS）为应用通信建立受保护的通道。","purpose":"提供机密性、完整性及按配置进行的身份认证。","example":"浏览器验证服务器证书，再经安全通道提交表单。"},"concept:CBC":{"definition":"密码分组链接模式（Cipher Block Chaining，CBC）先将明文块与前一密文块异或，再加密。","purpose":"连接各块的加密过程，首块使用初始化向量。","example":"一份文件分块加密，第二块的结果会受第一块影响。"},"concept:IPsec":{"definition":"互联网协议安全体系（Internet Protocol Security，IPsec）是一组在网络层保护报文的机制。","purpose":"按协商配置提供认证、完整性或机密性等服务。","example":"两处分支机构的网关建立隧道，保护跨公网通信。"},"concept:ESP":{"definition":"封装安全载荷（Encapsulating Security Payload，ESP）是IPsec中保护报文载荷的协议。","purpose":"按关联配置提供加密、完整性和抗重放等服务。","example":"两个网关协商启用加密后，用该协议承载内网报文。"},"concept:安全关联":{"definition":"安全关联（Security Association，SA）是IPsec单向通信使用的一组算法、密钥等安全参数。","purpose":"明确某一方向报文应怎样执行安全处理。","example":"两个网关双向传输时，分别建立各方向的安全关联。"},"concept:安全关联数据库":{"definition":"安全关联数据库（Security Association Database，SAD）保存有效关联的密钥、算法和状态。","purpose":"为具体报文的加解密、认证等处理提供参数。","example":"网关收到受保护报文，查找对应关联的算法和密钥。"},"concept:安全策略数据库":{"definition":"安全策略数据库（Security Policy Database，SPD）按地址、协议等条件保存流量处理规则。","purpose":"决定匹配流量应丢弃、直接放行还是进行保护。","example":"管理员规定访问某业务网段的流量必须经过保护。"},"concept:入侵检测系统":{"definition":"入侵检测系统（Intrusion Detection System，IDS）分析流量或主机活动，识别可疑行为。","purpose":"记录异常并发出告警，帮助人员调查安全事件。","example":"某主机短时尝试大量登录失败，系统生成告警记录。"},"concept:查准率":{"definition":"在全部被判为异常的结果中，真正异常所占的比例，计算为真告警数除以总告警数。","purpose":"衡量告警有多可信，辅助评估排查工作量。","example":"十条告警中九条属实，则查准率为百分之九十。"},"concept:查全率":{"definition":"在全部实际异常中，被系统成功检出的比例，计算为检出异常数除以实际异常总数。","purpose":"衡量异常覆盖程度，观察有多少问题被漏掉。","example":"实际有五十次攻击，检出四十次，查全率为八成。"},"concept:误报":{"definition":"本来正常的行为或流量，被检测系统错误判成异常或攻击，属于一次错误告警。","purpose":"用于分析告警噪声，指导规则调整和人工核实。","example":"管理员正常批量登录设备，却被识别成恶意扫描。"},"concept:漏报":{"definition":"实际存在的异常或攻击，没有被检测系统识别出来，被当作正常或未产生告警。","purpose":"用于评估检测盲区，帮助改进规则和监测范围。","example":"攻击者窃取文件时未触发任何告警，形成漏报。"},"concept:首匹配":{"definition":"按顺序检查规则，一旦遇到首条满足条件的规则，就执行其动作并停止后续匹配。","purpose":"确定有序访问控制规则的执行结果和优先关系。","example":"先放行办公网，再拒绝全部来源，办公网按首条放行。"},"concept:随机挑战":{"definition":"验证者为当前认证新生成的随机值；nonce意为仅用一次的数，重点是避免重复。","purpose":"让响应体现本次认证的新鲜性，抵抗旧响应重放。","example":"门禁临时发出随机数，卡片用密钥计算对应响应。"},"concept:单位换算":{"definition":"在保持实际数量不变时转换表示单位，网络计算要区分比特、字节及十进制前缀。","purpose":"统一长度、速率和时间单位，避免数量级错误。","example":"三字节含二十四比特；五微秒等于零点零零五毫秒。"},"concept:链路串行化":{"definition":"将分组各比特依次送上链路的过程；发送时延等于分组比特数除以链路发送速率。","purpose":"计算把整个分组送入链路所需的时间。","example":"八百比特以每秒八千比特发送，需要零点一秒。"},"concept:完整性":{"definition":"指数据未经授权不被修改，或发生修改后能够被发现的安全属性。","purpose":"帮助识别传输或存储中的数据改动。","example":"核验带密钥的认证码，发现订单金额被改。"},"concept:机密性":{"definition":"指信息只向获准的对象开放，未经授权者不能获知其内容。","purpose":"保护通信内容和存储数据中的秘密。","example":"对病历文件加密，限制无权限人员查看。"},"concept:身份认证":{"definition":"通过口令、密钥等证据，核验通信对象或用户所声称的身份。","purpose":"减少冒名登录或连接假冒对象的风险。","example":"用户登录邮箱时，提交密码和动态验证码。"},"concept:分组交换":{"definition":"将数据拆成分组，通过共享链路逐段转发，不为每次通信独占资源。","purpose":"让多路通信灵活共享网络传输能力。","example":"两台电脑下载文件，分组交错经过同一路由器。"},"concept:电路交换":{"definition":"通信前建立连接并预留沿途资源，在连接期间供该通信使用。","purpose":"为持续通信提供较稳定的传输资源。","example":"传统电话接通后，通话沿已建立的电路进行。"},"concept:统计复用":{"definition":"按各路数据实际到达情况分配共享资源，不固定给每路保留份额。","purpose":"提高用户间歇发送时的资源利用率。","example":"多名用户共用出口，谁有分组谁参与排队。"},"concept:时分复用":{"definition":"将共享信道的时间划成时隙，让不同信号在各自时隙传输。","purpose":"使多路信号轮流使用同一条信道。","example":"三路语音每轮各占一个时隙，循环传送。"},"concept:频分复用":{"definition":"把信道可用频带划成多个子频带，分别承载不同信号同时传输。","purpose":"让多路信号在不同频带并行通信。","example":"一根有线电视电缆用不同频段传送多个频道。"},"concept:分层体系":{"definition":"按职责把网络通信划成多层，各层借助下层服务支持上一层。","purpose":"分解通信复杂性，方便设计和维护。","example":"应用提交消息后，由传输层负责端到端传送。"},"concept:封装":{"definition":"数据向下层传递时，各层按协议添加本层控制信息的过程。","purpose":"提供寻址、识别和传输处理所需信息。","example":"网卡发送数据时，在网络层分组外添加帧头。"},"concept:解封装":{"definition":"接收数据向上层传递时，各层解析并去除本层控制信息的过程。","purpose":"逐层识别数据，并交给相应上层处理。","example":"接收方解析以太网帧，取出其中的网络层分组。"},"concept:服务与协议":{"definition":"服务是下层向上层提供的能力；协议是对等实体通信遵守的规则。","purpose":"区分层间提供的能力与对等通信规则。","example":"传输层提供可靠交付，对等实体按规则发送确认。"},"concept:复用与分用":{"definition":"复用把多路数据汇入共享通道；分用按标识将收到的数据分别交付。","purpose":"让多个通信对象共享资源且正确收取数据。","example":"两款应用共用网络，接收端按端口分送数据。"},"concept:RSA":{"definition":"RSA是里维斯特、沙米尔、阿德尔曼三人姓氏缩写，指一种公钥密码算法。","purpose":"配合安全编码用于加密和数字签名。","example":"发送方用接收方公钥保护一个随机会话密钥。"},"concept:模运算":{"definition":"对正整数模数，求整数除以它所得的余数，结果取零到模数减一。","purpose":"把整数运算结果限制在有限范围内。","example":"计算二十九模七，所得余数为一。"},"concept:模幂":{"definition":"对非负整数指数，计算整数的幂除以正整数模数所得的余数。","purpose":"完成公钥密码中的核心数值计算。","example":"二的五次方模七，结果为四。"},"concept:模逆元":{"definition":"若两个整数相乘模某正整数得一，就称它们互为该模下的乘法逆元。","purpose":"在逆元存在时，实现模意义下的除法。","example":"三乘五模七得一，因此五是三模七的逆元。"},"concept:欧拉函数":{"definition":"欧拉函数φ(n)统计一到正整数n之间，与n互素的整数有多少个。","purpose":"用于数论推导及部分公钥密钥计算。","example":"一到八中，一、三、五、七与八互素，故φ(8)=4。"},"concept:互素":{"definition":"两个整数的最大公因数为一时，称它们互素；不要求各自都是质数。","purpose":"判断模逆元是否存在等数论条件。","example":"八和十五都不是质数，但它们彼此互素。"},"concept:最大公因数":{"definition":"不全为零的两个整数，共有的正因数中最大的一个，简称最大公约数。","purpose":"用于约分、判断互素和计算模逆元。","example":"十八和三十共有的最大正因数是六。"},"concept:同余":{"definition":"两个整数的差能被给定正整数整除，就称它们在该模数下同余。","purpose":"表达不同整数在模运算下的等价关系。","example":"二十二与四之差为十八，因此二者模九同余。"},"concept:平方乘法":{"definition":"按指数的二进制位，通过反复平方和选择相乘来快速计算幂的方法。","purpose":"减少大指数幂及模幂所需的乘法次数。","example":"算五的十次方，可先平方得二、四、八次幂再组合。"},"concept:明文":{"definition":"加密操作的原始输入数据，可以是文字、图像，也可以是二进制内容。","purpose":"承载需要通过加密来保护的原始信息。","example":"照片文件送入加密程序前，其文件字节就是明文。"},"concept:密文":{"definition":"明文经过加密算法和密钥变换后得到的数据，通常需相应密钥恢复。","purpose":"使未获授权者难以获取原始信息。","example":"备份文件加密后，磁盘中保存的是密文字节。"},"concept:数据传输量":{"definition":"一次通信实际发送或接收的数据总大小，通常用比特或字节计量。","purpose":"结合发送速率，估算把数据送上链路所需的时间。","example":"发送一份两千字节的文件，就是传送一万六千比特。"},"concept:传播距离":{"definition":"信号沿传输介质实际经过的路径长度，不一定等于两地直线距离。","purpose":"结合信号传播速度，估算信号在途中耗费的时间。","example":"两栋楼相距百米，绕行铺设的光纤可能长达两百米。"},"concept:连续发送":{"definition":"发送方在协议允许范围内，不必每发一份数据就停下等待确认。","purpose":"让多份数据同时在途，减少等待造成的链路空闲。","example":"窗口允许四帧在途时，可先连续发出四帧再等确认。"},"concept:发送端状态":{"definition":"发送方维护的通信记录，包括待发数据、未确认数据和计时情况。","purpose":"决定下一步能否发送、需要等待还是进行重传。","example":"某帧尚未收到确认，发送方保留副本并继续计时。"},"concept:接收端状态":{"definition":"接收方保存的处理进度，包括已收数据、缓存内容和下一期待位置。","purpose":"帮助判断数据是否重复、缺失，以及能否交付。","example":"在允许乱序缓存的协议中，后面的数据先到时，接收方可记录缺口并暂存数据。"},"concept:反馈控制":{"definition":"发送方根据接收方或网络返回的信息，调整后续发送行为的机制。","purpose":"使发送行为适应接收能力、数据到达和网络状况。","example":"接收方通告缓存空间变小，发送方减少在途数据。"},"concept:丢包恢复":{"definition":"发现数据未能到达后，通过重传等机制补足缺失内容的过程。","purpose":"在网络可能丢包的条件下，提高数据传递可靠性。","example":"文件的一块数据迟迟未获确认，发送方超时后重发。"},"concept:重复数据识别":{"definition":"接收方依据序号等信息，判断到达数据是否已经接收过的过程。","purpose":"避免重传产生的副本被重复交付给上层应用。","example":"确认报文丢失引发重传，接收方识别旧数据并丢弃副本。"},"concept:数据交付顺序":{"definition":"接收方向上层提交数据的先后次序，可能与网络实际到达次序不同。","purpose":"让要求有序的应用获得符合发送顺序的数据。","example":"文件末尾先到时暂存，等前面缺失部分补齐后再交付。"},"concept:有限序号复用":{"definition":"序号字段取值有限，编号到达上限后回绕，再次使用已有编号。","purpose":"用有限字段持续编号，同时配合窗口等规则防止混淆。","example":"三位序号从零编到七后回到零，须防旧帧被误认成新帧。"},"concept:链路共享":{"definition":"多个通信参与者通过时间、频率或竞争等安排，使用同一传输资源。","purpose":"让多路通信利用共同介质，并协调资源占用。","example":"多台无线终端通过竞争获得发送机会，共享一个信道。"},"concept:邻居可达性":{"definition":"判断同一链路上的邻居当前能否接收并处理本机发出的通信。","purpose":"帮助确认下一跳是否可用，及时发现邻居失效。","example":"设备曾解析出邻居地址，但邻居断电后仍可能不可达。"},"concept:分组转发":{"definition":"网络设备检查到达分组的目的信息，选择出口并送往下一跳的操作。","purpose":"让数据经过中间设备，逐步向目标网络前进。","example":"路由器收到发往外网的分组，查表后从上联接口送出。"},"concept:地址匹配":{"definition":"将目的地址与表项中的地址或前缀按指定规则进行比较的过程。","purpose":"找出适用的转发表项，确定出口或下一跳。","example":"两个网络前缀都匹配目的地址时，路由器选更长的前缀。"},"concept:路径代价比较":{"definition":"依据路由协议规定的度量，比较到达同一目的地的候选路径。","purpose":"按统一评价规则选择路由，不能只凭物理远近。","example":"某协议以跳数衡量代价，会优先选择跳数较少的路径。"},"concept:路由收敛":{"definition":"网络发生变化后，各路由器更新信息并逐步形成稳定路由的过程。","purpose":"让转发适应新的拓扑，减少过渡期间的异常。","example":"一条链路断开后，路由器交换更新，最终改走备用路径。"},"concept:端点标识":{"definition":"用于区分通信两端的信息；传输层通常结合网络地址和端口号。","purpose":"把到达的数据交给正确的通信端点或连接。","example":"同一主机上的两个服务使用不同端口，分别接收请求。"},"concept:连接状态":{"definition":"面向连接协议保存的当前阶段及相关记录，如建立、传输和关闭。","purpose":"约束报文处理及发送行为，协调连接的整个过程。","example":"连接进入关闭等待阶段后，程序仍需按协议完成关闭。"},"concept:网络性能":{"definition":"网络传递数据的实际表现，常用吞吐量、时延、丢包率等衡量。","purpose":"判断网络能否满足应用需求，并定位性能瓶颈。","example":"视频通话即使带宽充足，也可能因时延波动而不流畅。"},"concept:差错检测":{"definition":"利用附加校验信息，判断数据在传输或存储中是否可能发生改变。","purpose":"发现部分数据错误，为丢弃或重传提供依据。","example":"接收方重新计算校验值，若与收到的值不符便报告错误。"},"concept:二进制多项式":{"definition":"把比特串视为系数仅为零或一的多项式，运算通常采用模二规则。","purpose":"将循环冗余校验中的编码与检验表示为代数运算。","example":"比特串1101表示三次项、二次项和常数项系数为一。"},"concept:多项式阶数":{"definition":"非零多项式中，系数不为零的项所具有的最高次数，也称次数。","purpose":"描述多项式规模，并帮助确定编码运算参数。","example":"多项式含五次项、二次项和常数项，其阶数就是五。"},"concept:码字":{"definition":"按指定编码规则表示一个符号或一组数据的符号序列，常写成比特串；不一定原样保留信息位，也不必附带校验位。","purpose":"区分编码前的数据与实际发送的序列；是否支持检错、同步等功能，要看具体编码规则。","example":"某编码把A记为101、B记为011；这两个序列就是该规则下的码字。"},"concept:交换方式":{"definition":"通信网络组织数据传送和分配中间资源的方法，如电路交换和分组交换。","purpose":"决定资源如何占用，以及数据如何经过中间节点。","example":"电话可先建立专用电路，文件传输则可拆成分组逐段转送。"},"concept:信道争用":{"definition":"多个设备需要使用同一共享信道，发送机会发生竞争的现象。","purpose":"协调发送机会，减少冲突和无序等待。","example":"几台无线电脑同时上传文件，需要竞争无线信道。"},"concept:逻辑网络隔离":{"definition":"通过子网、虚拟局域网或访问规则，在逻辑上划分网络通信范围。","purpose":"限制广播和访问范围，方便管理网络。","example":"同一套交换设备上，访客网络不能直接访问财务网络。"},"concept:介质访问控制":{"definition":"数据链路层中规定设备如何获得共享介质发送机会的一组规则。","purpose":"协调多设备发送，避免或处理介质冲突。","example":"无线设备发送前先监听，发现信道忙就暂缓发送。"},"concept:首部开销":{"definition":"协议为寻址、控制等功能添加的首部所占字节及传输资源。","purpose":"衡量协议控制信息占用的传输成本。","example":"发送十字节数据却附加较长首部，小包的开销占比较高。"},"concept:分片边界":{"definition":"一个分组拆分后各片数据的起止位置，需符合相应协议的对齐规则。","purpose":"保证各片能正确定位并重新组装。","example":"第四版网际协议中，非末片的数据长度须为八字节的整数倍。"},"concept:应用消息":{"definition":"应用程序按业务含义组织的一次信息单元，其边界由应用协议规定。","purpose":"表达业务请求、结果或需要传递的事件。","example":"聊天软件的一条文字消息可能分多次传输才接收完整。"},"concept:请求处理时序":{"definition":"一次请求从发起到响应期间，各项通信和处理步骤的先后及耗时关系。","purpose":"定位等待环节，判断哪些步骤可以优化。","example":"网页先查询名称，再建立连接，服务器处理后返回内容。"},"concept:名称解析":{"definition":"按命名规则查询名称对应的地址或其他记录，通常由解析服务完成。","purpose":"让应用使用易记名称定位所需资源。","example":"浏览器访问网站前，查询网站名称对应的网络地址。"},"concept:缓存有效性":{"definition":"缓存内容是否仍满足期限、一致性或校验规则，能够继续被使用。","purpose":"避免使用过期数据，同时减少重复获取。","example":"名称解析记录超过缓存期限后，需要重新查询才能继续采用。"},"concept:信任关系":{"definition":"通信主体依据证书、凭据或配置，接受另一主体身份或声明的关系。","purpose":"为身份验证和授权判断提供依据。","example":"浏览器依据受信任机构的签名，核验网站提供的证书。"},"concept:攻击面":{"definition":"系统中可能被攻击者接触并利用的接口、服务、协议及入口的集合。","purpose":"帮助确定防护范围，减少可利用入口。","example":"路由器开启远程管理服务，会增加一个需要保护的入口。"},"concept:传输介质":{"definition":"承载通信信号的物理材料或传播空间，包括有线介质和无线空间。","purpose":"为设备间的信号传播提供物理通道。","example":"楼宇间可以铺设光缆，也可以通过无线电链路通信。"},"concept:电磁干扰":{"definition":"外部电磁能量耦合进通信系统，使信号产生失真或接收错误的现象。","purpose":"分析误码来源，指导布线和屏蔽措施。","example":"网络铜缆紧贴大功率电机布置，可能出现通信不稳定。"},"concept:光纤":{"definition":"利用玻璃或塑料纤维导引光信号，传送信息的一种有线介质。","purpose":"支持高速远距离通信，并抵抗电磁耦合干扰。","example":"校园两栋楼之间通过地下光缆连接各自的网络设备。"},"concept:双绞线":{"definition":"将两根绝缘铜导线成对绞合的传输介质，可分为屏蔽和非屏蔽类型。","purpose":"通过绞合减轻串扰及外部干扰影响。","example":"办公室网线通常包含四对双绞线，用于连接电脑和交换机。"},"concept:同轴电缆":{"definition":"由中心导体、绝缘层、同轴外导体及护套构成的有线传输介质。","purpose":"传输电信号，利用外导体提供一定屏蔽。","example":"有线电视接入可使用同轴电缆承载多个频段的信号。"},"concept:单工与双工":{"definition":"单工只允许单向传输；半双工可交替双向传输；全双工可同时双向传输。","purpose":"说明链路允许的传输方向和同时性。","example":"对讲机通话时通常一方说另一方听，属于半双工。"},"concept:码元信息量":{"definition":"实际使用的M种可区分状态等概率出现时，每次状态选择的信息量为log₂M bit。这不表示任意M都能逐码元放入固定的log₂M位二进制组。","purpose":"联系状态选择与信息量，并分清理论信息量和固定整数位组映射的限制。","example":"四种状态等概率使用、分别对应00、01、10、11时，每次状态选择携带两比特信息。"},"concept:二进制编码":{"definition":"按照约定规则，用零和一组成的比特序列表示数据或控制信息。","purpose":"让设备能够统一存储、传输和解释信息。","example":"某协议约定用零零表示空闲，用零一表示启动。"},"concept:保护带":{"definition":"相邻频率信道之间预留的不承载业务的频率间隔，用来减轻相互干扰。","purpose":"容纳滤波过渡范围，降低邻道干扰。","example":"两个广播频道之间留出一段频率，避免边缘信号互相影响。"},"concept:突发流量":{"definition":"数据在短时间内集中到达，使瞬时到达速率明显高于平常水平的流量。","purpose":"帮助解释短时拥塞，规划缓冲和调度。","example":"下课时大量学生同时打开课程网站，接入流量骤增。"},"concept:带宽共享":{"definition":"多个用户或数据流共同使用一份有限传输能力，按接入和调度规则分配。","purpose":"提高资源使用效率，支持多用户通信。","example":"宿舍几台设备共用一条宽带，大量下载会影响其他设备。"},"concept:吞吐率":{"definition":"在指定测量位置和时间内，实际成功传送的数据量与所用时间之比。","purpose":"衡量实际传输表现，比较网络运行效果。","example":"十秒成功传送五十兆比特数据，平均吞吐率为每秒五兆比特。"},"concept:链路容量":{"definition":"链路在给定条件下能够支持的最大传输速率，通常以每秒比特数表示。","purpose":"作为评估传输上限和规划网络的依据。","example":"两段链路串联时，容量较小的一段会限制整条路径的速率。"},"concept:协议开销":{"definition":"通信协议额外加入的首部、尾部或控制信息，不属于应用有效数据。","purpose":"帮助寻址、确认和检错，也会占用传输资源。","example":"寄送照片时，分组附带的地址和校验字段都属于协议开销。"},"concept:误码":{"definition":"传输过程中，接收比特与发送比特不一致，如零被误判为一。","purpose":"分析误码有助于评价链路质量和选择纠错方法。","example":"发送的比特串为1010，接收成1000，其中一个比特发生误码。"},"concept:相邻层服务":{"definition":"分层网络中，下层通过规定接口向紧邻的上层提供通信能力。","purpose":"让各层分工协作，减少上层对底层细节的依赖。","example":"应用把数据交给传输层，由传输层提供进程间的数据传送。"},"concept:网络拓扑":{"definition":"网络中节点与链路的连接布局，可描述物理连接或逻辑关系。","purpose":"帮助规划布线、分析流量路径和故障影响范围。","example":"多台电脑分别连接同一交换机，形成常见的星形连接布局。"},"concept:图的连通性":{"definition":"把网络抽象为图后，描述节点之间是否存在路径可达的性质。","purpose":"用于判断通信能否到达及断链后的网络影响。","example":"无向网络中，若每对节点都有路径相通，这个图就是连通图。"},"concept:点到点链路":{"definition":"只连接两个通信节点的直接链路，中间不经过其他转发节点。","purpose":"为两个相邻节点提供直接的数据传输通道。","example":"两台路由器之间用一条专用光纤相连，可构成点到点链路。"},"concept:网络边缘":{"definition":"互联网中靠近用户、运行应用的端系统及其所在的外围部分。","purpose":"承载应用的数据产生、处理和最终接收。","example":"用户手机运行视频应用，云端服务器提供视频，二者都处于网络边缘。"},"concept:互联网服务提供商":{"definition":"为用户或其他网络提供互联网接入、互联等服务的组织，简称ISP。","purpose":"把用户网络接入互联网，并提供跨网络连接。","example":"家庭向一家互联网服务提供商办理宽带，通过其网络访问网站。"},"concept:接入网":{"definition":"把端系统连接到互联网首台路由器的网络部分，支持多种接入方式。","purpose":"完成用户终端进入互联网的第一段连接。","example":"家庭光纤宽带把家中设备连向运营商网络，属于接入网的一种。"},"concept:核心网":{"definition":"由互联路由器和高速链路组成、承担大量跨网转发的网络骨干部分。","purpose":"汇聚各接入网流量，并把数据送向目的网络。","example":"跨城市通信时，数据常经过运营商骨干路由器组成的核心网。"},"concept:端系统":{"definition":"运行网络应用、作为通信源头或终点的设备，也常称为主机。","purpose":"产生和接收应用数据，执行端到端通信协议。","example":"笔记本向远程服务器提交表单，两台设备都是这次通信的端系统。"},"concept:协议兼容性":{"definition":"通信双方在格式、含义和交互规则上能够配合，正确交换信息的能力。","purpose":"保证不同设备或软件能按共同规则通信。","example":"两款聊天程序采用一致的消息格式和交互规则，才能正确解析消息。"},"concept:故障定位":{"definition":"依据现象和检测结果，逐步确定网络故障所在设备、链路或协议环节。","purpose":"缩小排查范围，指导修复真正出问题的位置。","example":"电脑能访问路由器却打不开网站，可继续检查外网连接和域名解析。"},"concept:可用率":{"definition":"在规定观察时间内，网络或服务能够正常提供约定功能的时间比例。","purpose":"衡量服务持续可用的程度，辅助评价可靠性。","example":"某服务观察十小时，其中停机一小时，则这一时段可用率为九成。"},"concept:冗余路径":{"definition":"源与目的之间额外保留的可替代通信路径，其保护效果取决于独立程度。","purpose":"主路径故障时提供替代通道，降低中断风险。","example":"园区通过不同线路连接两家运营商，一条线路断开时可切换另一条。"},"concept:性能测量条件":{"definition":"测量网络性能时约定的负载、路径、样本、时间范围和统计口径等条件。","purpose":"让结果可解释、可复现，并支持公平比较。","example":"比较两次测速，应说明是否使用有线连接、后台有无下载及服务器位置。"},"concept:尾部时延":{"definition":"时延分布中较慢一端的表现，通常用第九十五或第九十九百分位描述。","purpose":"揭示少数请求的长等待，补充平均时延信息。","example":"多数网页很快打开，但少数等待数秒，这些慢请求会影响尾部时延。"},"concept:丢包率":{"definition":"按指定范围和判定规则，未成功到达的分组数占发送分组总数的比例。","purpose":"评价传输质量，帮助分析拥塞或链路异常。","example":"一次测试发送五百个探测包，十个未到达，测得丢包率为百分之二。"},"concept:数学期望":{"definition":"随机变量各可能取值按其概率加权得到的平均值，不保证单次出现。","purpose":"估计重复随机事件的平均结果和资源需求。","example":"传送一个包耗时一毫秒或三毫秒，各占一半，其期望耗时为两毫秒。"},"concept:任务依赖":{"definition":"任务之间必须遵守的先后关系，后续任务需等待前置任务达到指定状态。","purpose":"确定哪些工作能并行，避免违反执行顺序。","example":"浏览器通常先完成域名解析，取得目标地址后才能向该地址建立连接。"},"concept:串并行耗时":{"definition":"串行任务依次执行，耗时相加；独立任务同时启动时，并行耗时取最慢者。","purpose":"估算完成时间，判断任务拆分是否能加速。","example":"两个独立下载各需四秒和七秒，无资源竞争时同时开始约七秒完成。"},"concept:客户服务器结构":{"definition":"由客户进程发起请求、服务器进程提供相应服务的网络应用组织方式。","purpose":"集中提供数据或功能，供多个客户访问。","example":"天气应用请求某城市预报，服务器查询后返回结果，双方承担不同角色。"},"concept:对等网络":{"definition":"对等网络简称P2P，来自英文Peer-to-Peer，节点可兼有请求和提供资源的角色。","purpose":"利用多个参与节点的资源，分担数据分发负担。","example":"甲向乙下载文件片段时，也能把自己已有的片段上传给丙。"},"concept:上传瓶颈":{"definition":"发送端或参与节点的上传能力不足，成为限制数据分发速度的主要因素。","purpose":"帮助确定分发限制，指导增加上传资源。","example":"教师电脑上行较慢，即使学生下载很快，集中发文件仍可能耗时很长。"},"concept:分发时间下界":{"definition":"在给定文件大小、节点数量及传输能力下，完成分发至少需要的时间。","purpose":"判断方案的理论极限，评估优化空间。","example":"服务器上传一份文件至少需十秒，全体分发不可能少于十秒。"},"concept:分块传输":{"definition":"把完整数据拆成较小的数据块，分别发送，并在接收端按规则重组。","purpose":"便于流水传输、分段重传和并行下载。","example":"一份安装包拆成多个片段，丢失其中一段时只补传该段。"},"concept:媒体码率":{"definition":"音频或视频每单位播放时间对应的数据量，通常以比特每秒表示。","purpose":"估算传输带宽需求和播放流量。","example":"某视频码率为每秒两兆比特，播放十秒约需二十兆比特数据。"},"concept:内容分发网络":{"definition":"内容分发网络，缩写CDN，是利用分布式节点缓存并交付内容的系统。","purpose":"缩短访问等待，分担源服务器负载。","example":"不同城市的用户从附近缓存节点下载同一款游戏的更新包。"},"concept:客户端服务器交互":{"definition":"客户端与提供服务的服务器，依照应用协议交换请求、响应等消息。","purpose":"让远程程序协作，获取数据或执行操作。","example":"天气应用向服务器提交城市名称，服务器返回对应天气数据。"},"concept:幂等性":{"definition":"同一操作执行一次或重复执行多次，对服务器产生的预期效果相同。","purpose":"帮助判断失败重试是否会重复改变状态。","example":"把某设备名称设为“书房”，重复提交仍得到同样的名称设置。"},"concept:消息语法":{"definition":"协议对消息结构、字段排列、编码方式和边界标记作出的格式规定。","purpose":"让通信双方能够正确拆解收到的消息。","example":"某协议规定前两字节表示正文长度，后续字节才是正文内容。"},"concept:分用":{"definition":"接收端依据协议规定的地址、端口等标识，把数据交给对应接收对象。","purpose":"让多个应用共享网络并分别接收数据。","example":"同一电脑同时运行聊天和游戏，收到的数据被交给各自程序。"},"concept:内容许可":{"definition":"权利人对内容使用作出的授权，规定复制、修改、传播等允许范围。","purpose":"明确使用条件，判断哪些操作获得授权。","example":"一张配图允许署名转载，但许可条款禁止将其用于商业广告。"},"concept:访问授权与再分发权":{"definition":"访问授权允许查看或获取内容，再分发权允许向其他人提供其副本。","purpose":"区分获取内容与传播内容所需的权限。","example":"会员可在线阅读电子书，但向公众提供书籍副本须另有授权依据。"},"concept:加权平均":{"definition":"先将各数值乘以对应权重，再求和并除以权重总和的计算方法。","purpose":"按重要程度融合数据，平滑测量波动。","example":"旧时延为四十毫秒、新值为六十毫秒，权重各半得五十毫秒。"},"concept:重传超时":{"definition":"发送方等待确认达到设定时限仍未获确认，从而触发重传的机制。","purpose":"在数据或确认丢失时推动传输继续。","example":"发送方发出一段数据，等待超过定时器期限后再次发送该段。"},"concept:临时端口":{"definition":"操作系统通常为应用动态分配、在一段通信期间使用的本地端口。","purpose":"区分通信端点，便于将返回数据交给应用。","example":"浏览器连接远程服务时，系统为连接分配本地端口五万二千。"},"concept:闭区间计数":{"definition":"统计整数闭区间内的整数个数，包含两端，数量为上界减下界加一。","purpose":"计算连续地址、端口或序号的数量。","example":"端口四千至四千零九都可使用时，合计有十个端口号。"},"concept:公平性":{"definition":"多个通信流共享网络资源时，按选定标准合理分配资源的性质。","purpose":"限制长期独占资源，协调竞争流量。","example":"两个条件相近的下载流共享瓶颈链路，可把带宽大致均分。"},"concept:主机地址范围":{"definition":"子网内可分配给主机接口的地址集合，其边界取决于前缀和地址规则。","purpose":"规划接口地址，检查地址分配是否有效。","example":"普通的192.168.8.0/24子网，主机地址通常为末段一至二百五十四。"},"concept:私有地址":{"definition":"为内部网络保留、可由不同网络重复使用的地址，不在公网直接路由。","purpose":"支持内部编址，减少公网地址需求。","example":"家庭打印机使用192.168.2.30，另一家庭也可使用这个地址。"},"concept:地址作用域":{"definition":"地址能够有效标识接口、用于通信的网络范围，如链路内或全球范围。","purpose":"帮助选择地址，限制其适用的通信范围。","example":"链路本地地址可供同一链路设备通信，路由器不将其转发到远端。"},"concept:软件定义网络":{"definition":"软件定义网络，缩写SDN，将控制逻辑与数据转发分离，由软件编程控制。","purpose":"便于统一配置策略，灵活调整转发行为。","example":"管理员修改控制器策略，使一类业务统一经过指定的安全设备。"},"concept:南向接口":{"definition":"网络控制器与受控转发设备之间，用于下发规则、获取状态的通信接口。","purpose":"把控制策略落实到设备并收集运行信息。","example":"控制器经南向接口更新交换机规则，让指定流量改走备用出口。"},"concept:网络管理":{"definition":"对网络设备与服务进行监测、配置、故障处理和性能维护的活动。","purpose":"维持网络可用性，及时发现运行异常。","example":"运维人员发现某出口流量持续升高，检查原因并调整带宽配置。"},"concept:SNMP":{"definition":"SNMP全称简单网络管理协议，用于管理站与设备代理交换管理信息。","purpose":"支持远程监测、配置及接收设备通知。","example":"监控平台定期采集打印机状态，在发现缺纸后向运维人员告警。"},"concept:管理站与代理":{"definition":"管理站负责组织监控和管理，代理在被管设备侧提供管理数据与操作。","purpose":"明确管理通信中双方承担的角色。","example":"监控服务器作为管理站，交换机上的代理提供设备温度信息。"},"concept:最短路径":{"definition":"在给定网络图中，连接起点与终点且链路权重之和最小的路径。","purpose":"按时延、费用等指定指标选择路由。","example":"直达链路代价为九，经中间节点的两段代价各为三，则绕行更短。"},"concept:松弛操作":{"definition":"路径算法中，用经过邻接节点的候选路径更新当前最优路径估计。","purpose":"逐步改进路径估计，帮助计算最短路。","example":"原先到某节点需九步，新发现经另一节点只需六步，便更新记录。"},"concept:路径方向性":{"definition":"网络路径有发送方向，正向与反向可以经过不同节点和链路。","purpose":"分别检查两个方向，判断双向通信是否可行。","example":"请求经甲路由器到服务器，回复可能经乙路由器返回。"},"concept:OSPF区域":{"definition":"开放最短路径优先协议（OSPF）中，限制详细链路状态传播的逻辑分区。","purpose":"缩小拓扑维护范围，降低计算和通告开销。","example":"企业把多个园区划入不同区域，由区域边界路由器连接。"},"concept:协议标准":{"definition":"对通信消息格式、含义和处理规则作出的共同规范。","purpose":"让不同厂商、不同程序实现相互通信。","example":"两家公司开发的邮件程序遵守同一邮件协议，便能交换邮件。"},"concept:分块计数":{"definition":"将数据划成片段后，按统一口径统计片段数量及完成状态。","purpose":"跟踪传输进度，确定还需获取哪些片段。","example":"视频分成十二段，播放器记录各段是否完整，优先补齐缺段。"},"concept:业务状态":{"definition":"应用保存的订单、余额或处理进度等信息，反映业务当前情况。","purpose":"判断请求能否执行，保持业务结果一致。","example":"订单已标记为退款完成，再次收到同一申请时返回原处理结果。"},"concept:状态机":{"definition":"用有限状态及事件触发的转换规则，描述系统如何随交互变化。","purpose":"明确各阶段允许的消息和处理动作。","example":"文件传输程序收到确认后，从等待确认转为发送下一块。"},"concept:码分多址":{"definition":"码分多址（CDMA）让多个用户以不同扩频码共享同一频段和时间。","purpose":"利用码序列区分同时传输的用户信号。","example":"两部终端同时发送，基站用各自的码序列提取对应数据。"},"concept:码片":{"definition":"扩频码序列中的基本信号单元，持续时间通常短于一个数据比特。","purpose":"组成扩频序列，把数据展开为更快的信号变化。","example":"某系统用八个码片表示一个数据比特，接收端按整组处理。"},"concept:正交码":{"definition":"按规定对齐时，任意两条不同码序列的内积为零的一组码。","purpose":"在理想同步条件下分离不同用户的信号。","example":"两个用户选用同组中的不同正交码，接收端分别相关检测。"},"concept:相关解码":{"definition":"将收到的信号与目标码序列逐项相乘并累加，据结果恢复数据。","purpose":"提取目标用户信号，抑制相关性较低的干扰。","example":"接收机用某终端的本地码处理混合信号，再根据结果判决比特。"},"concept:分贝":{"definition":"分贝（dB）是比值的对数表示，功率比换算为其常用对数的十倍。","purpose":"方便表示大范围功率变化和级联增益。","example":"某放大器让输出功率变为输入的两倍，功率增益约为三分贝。"},"concept:移动绑定":{"definition":"移动网络中，将终端的归属地址映射到当前转交地址的有效记录。","purpose":"让发往固定归属地址的数据找到移动终端。","example":"终端到访新网络后登记转交地址，归属代理据此转送数据。"},"concept:租约有效期":{"definition":"资源或登记记录获准使用的有限时段，到期后的处理由协议规定。","purpose":"回收失效资源，避免长期保留过时状态。","example":"终端获得一小时的地址租约，继续使用时需按协议申请续租。"},"concept:归属位置寄存器":{"definition":"归属位置寄存器（HLR）是传统蜂窝网保存用户资料和位置线索的数据库。","purpose":"支持用户鉴权、业务授权及来话定位。","example":"有人拨打某用户电话时，网络查询其登记信息以确定寻呼方向。"},"concept:访问位置寄存器":{"definition":"访问位置寄存器（VLR）是传统蜂窝网临时保存本区用户资料的数据库。","purpose":"支持到访用户接入，减少向归属网反复查询。","example":"用户进入外地服务区后，当地寄存器保存其临时身份和业务权限。"},"concept:漫游":{"definition":"移动用户离开归属网络后，在具有相应服务协议的其他网络获得服务。","purpose":"扩大用户可使用移动通信服务的地域范围。","example":"用户出国后接入合作运营商网络，仍使用原号码接听电话。"},"concept:码片同步":{"definition":"接收端使本地码片的时序与收到信号的码片边界正确对齐。","purpose":"保证相关检测有效，维持预期的码间区分能力。","example":"接收机发现本地码提前半个码片，便调整时序后重新检测。"},"concept:RTP":{"definition":"RTP全称实时传输协议，携带音视频及序号、时间戳，本身不保证准时可靠送达。","purpose":"帮助接收端排序媒体包并安排播放。","example":"语音通话把每二十毫秒的声音装入一个媒体包。"},"concept:RTCP":{"definition":"RTCP全称实时传输控制协议，为RTP会话交换接收质量及媒体同步信息。","purpose":"反馈丢包和抖动，辅助同步与调整。","example":"接收端定期报告近期丢包比例，供发送端参考。"},"concept:SSRC":{"definition":"SSRC全称同步源标识符，是RTP包中标识同步源的三十二位编号。","purpose":"区分媒体来源，并维护各自的接收状态。","example":"会议中两人的音频流通常使用不同的同步源编号。"},"concept:CSRC":{"definition":"CSRC全称贡献源标识符，列在混音器输出的RTP包中，指出参与混合的源。","purpose":"说明混合媒体由哪些原始来源贡献。","example":"两人的语音混为一路后，包头可列出双方编号。"},"concept:SIP":{"definition":"SIP全称会话初始协议，是用于建立、修改和结束多媒体会话的信令协议。","purpose":"协调呼叫过程，媒体通常另用协议传送。","example":"网络电话先发送邀请，对方接受后开始通话。"},"concept:SDP":{"definition":"SDP全称会话描述协议，以文本描述媒体类型、地址、端口和编码等会话参数。","purpose":"让通信双方了解并协商媒体传输参数。","example":"会话描述中写明接收音频的端口和支持的编码。"},"concept:动态载荷类型":{"definition":"动态载荷类型是RTP中需经会话协商确定含义的载荷编号，通常取九十六至一百二十七。","purpose":"灵活标记编码格式，避免依赖固定编号。","example":"双方约定编号一百零一表示某种音频编码。"},"concept:媒体采样时钟":{"definition":"媒体采样时钟是表示媒体时间进度的计时基准，其频率由媒体格式或规范确定。","purpose":"为时间戳提供刻度，帮助恢复播放节奏。","example":"八千赫兹的音频时钟每毫秒前进八个刻度。"},"concept:RTP时间戳":{"definition":"RTP时间戳表示包内首个媒体数据的采样时刻，按媒体时钟计数，初值通常随机。","purpose":"恢复媒体时间间隔，安排同步播放。","example":"八千赫兹音频相隔二十毫秒，时间戳相差一百六十。"},"concept:播放延迟":{"definition":"播放延迟是接收端为安排媒体播放设置的等待量，具体起算点须依题目约定。","purpose":"缓冲到达时间波动，减少播放中断。","example":"播放器收到首包后先等六十毫秒，再连续播放。"},"concept:时延丢失":{"definition":"时延丢失指媒体包虽然最终到达，却晚于播放期限，无法用于本次正常播放。","purpose":"衡量迟到数据对实时播放造成的损失。","example":"某语音包在对应声音已经播完后到达，被丢弃。"},"concept:播放期限":{"definition":"播放期限是媒体包仍可赶上既定播放安排的最晚到达时刻，由接收端策略确定。","purpose":"判断数据是否迟到，决定播放或补偿。","example":"某段声音定在下一秒播放，过了期限才到便无法使用。"},"concept:时延估计":{"definition":"时延估计是依据观测样本推测传输耗时；估计单向时延需处理两端时钟偏差。","purpose":"帮助设置播放缓冲，并跟踪网络变化。","example":"接收端平滑近期耗时样本，发现网络传输正在变慢。"},"concept:算术平均":{"definition":"算术平均是把所有样本相加再除以样本个数，各个样本具有相同权重。","purpose":"概括一组观测值的平均水平。","example":"三次时延为十、二十、三十毫秒，平均为二十毫秒。"},"concept:指数加权移动平均":{"definition":"指数加权移动平均，英文缩写EWMA，将新样本与旧估计加权，越旧的样本权重越小。","purpose":"平滑随机波动，同时跟踪近期变化。","example":"每次用两成新时延与八成旧估计更新预测值。"},"concept:递推式":{"definition":"递推式是利用前一步或前几步的结果计算当前结果的公式，通常需要初始值。","purpose":"逐次更新状态，避免反复处理全部历史。","example":"保存累计时延，新样本到来时把它加到原总和中。"},"concept:交织":{"definition":"交织是发送前重排媒体单元，使原本相邻的内容分散到不同数据包中的方法。","purpose":"把连续丢包影响分散，便于播放端补偿。","example":"连续语音片段交错装包，一个包丢失后留下多个短缺口。"},"concept:前向纠错":{"definition":"前向纠错，英文缩写FEC，是发送额外冗余数据，使接收端在能力范围内恢复丢失内容的方法。","purpose":"减少对重传的依赖，适合时限较紧的媒体。","example":"每四个数据块附一个校验块，可设计为恢复一个丢块。"},"concept:异或校验":{"definition":"异或校验是将多个等长数据块逐位异或生成校验块；校验块和其余块齐全时可恢复一个丢块。","purpose":"用较少冗余补回单个丢失数据块。","example":"三个数据块附一个异或块，其中一个丢失仍可还原。"},"concept:低码率备份":{"definition":"低码率备份是为原媒体另附数据量较小、质量较低的编码副本，常放入后续包。","purpose":"原包丢失时提供替代内容，减轻听感损伤。","example":"当前语音包附带上一段的压缩副本，供丢包时补播。"},"concept:音频分块":{"definition":"音频分块是按一定时长或样本数，把连续声音划成便于独立处理的数据单元。","purpose":"方便编码、装包、缓冲和安排播放。","example":"把一秒声音划为五十块，每块对应二十毫秒。"},"concept:DSCP":{"definition":"DSCP全称区分服务代码点，是IP首部中的六位字段，用于标记分组的服务类别。","purpose":"供路由器按配置选择排队与转发方式。","example":"语音包被标为某类业务，路由器依配置优先调度。"},"concept:ECN":{"definition":"ECN全称显式拥塞通知，支持它的网络可对分组作拥塞标记，由端系统反馈并响应。","purpose":"在部分拥塞情况下用标记代替丢包通知。","example":"路由器标记拥塞后，接收端反馈，发送端降低速率。"},"concept:DiffServ":{"definition":"DiffServ全称区分服务，是按分组标记划分类别、在网络中实施不同转发待遇的体系。","purpose":"按业务类别分配资源，提供差异化服务。","example":"企业网络把语音和文件下载分入不同队列调度。"},"concept:AF":{"definition":"AF全称Assured Forwarding，中文为确保转发，是区分服务中的一类转发行为。","purpose":"按类别和丢弃等级提供差异化待遇，但不保证绝不丢包。","example":"企业把会议视频归入某个AF类，并将超额包标为更易丢弃。"},"concept:丢弃优先级":{"definition":"丢弃优先级表示同类分组在拥塞时被优先丢弃的程度。","purpose":"让拥塞设备优先舍弃较不重要或超额的流量。","example":"同一视频流中，超出约定速率的包可设置为更容易丢弃。"},"concept:流量整形":{"definition":"流量整形把暂时超额的分组放入队列，延后发送以符合约定。","purpose":"平滑突发流量，减少下游拥塞，代价是增加等待。","example":"文件上传突然加速时，路由器先缓存部分包，再逐步发出。"},"concept:流量监管":{"definition":"流量监管检查分组是否符合流量约定，对超额部分丢弃或重新标记。","purpose":"约束用户实际流量，防止超额发送挤占网络资源。","example":"接入设备发现某用户超过限额，把超额包改为低保障等级。"},"concept:令牌桶":{"definition":"令牌桶按固定速率积累令牌，发包消耗对应令牌，桶容量限制突发量。","purpose":"同时约束长期平均速率，并允许一定程度的短时突发。","example":"空闲时攒下的令牌，可让下一小批数据短时间连续通过。"},"concept:资源预留":{"definition":"资源预留是在通信路径上为特定数据流安排带宽、缓冲等资源。","purpose":"配合调度和准入控制，为约定的服务质量提供支持。","example":"视频会议开始前，沿途设备为该会议流预留一定带宽。"},"concept:准入控制":{"definition":"准入控制在接受新业务前，判断剩余资源能否满足其服务要求。","purpose":"避免接入过多业务，损害已经承诺的服务质量。","example":"链路无法再满足一路高清会议时，系统拒绝新的预留请求。"},"concept:现场直播":{"definition":"现场直播将现场持续产生的音视频边采集边传送，观众稍后接收播放。","purpose":"让远端观众及时观看正在发生的活动，通常存在延迟。","example":"校园运动会现场拍摄的画面，经网络传给校外观看的同学。"},"concept:视频点播":{"definition":"视频点播由用户选择已存储的视频，服务器按请求传送供其观看。","purpose":"支持用户自行决定观看内容、开始时间和播放进度。","example":"学生晚上打开课程录像，从上次暂停的位置继续学习。"},"concept:重新标记":{"definition":"重新标记是按网络策略修改分组的服务类别或丢弃优先级等标记。","purpose":"使分组待遇符合流量约定或进入新网络后的分类规则。","example":"运营商入口将超额分组的标记改为拥塞时更容易丢弃。"},"concept:跨域服务":{"definition":"跨域服务指业务跨越多个独立管理的网络域，由各域协作提供服务。","purpose":"衔接不同网络的策略和资源，支持端到端服务要求。","example":"一场跨运营商视频会议，需要双方网络协调各自的服务待遇。"},"concept:媒体同步":{"definition":"媒体同步是依据时间关系安排音视频等媒体的播放，使其内容对应。","purpose":"保持口型与声音等一致，避免不同媒体播放错位。","example":"播放器调整缓冲，让人物张嘴的画面与对应语音同时呈现。"},"concept:编解码器":{"definition":"编解码器是把媒体编码成便于传输的数据，并将其解码还原的组件。","purpose":"压缩媒体数据，减少传输和存储开销，并支持播放。","example":"通话终端压缩麦克风声音，接收端再解码成可播放的音频。"},"concept:转码":{"definition":"转码是将已编码的媒体转换成另一种编码格式、码率或分辨率。","purpose":"适配接收设备能力和网络条件，便于媒体传输播放。","example":"服务器把高码率录像转换成低码率版本，供移动用户观看。"},"concept:空间冗余":{"definition":"空间冗余指同一幅图像内相邻像素或区域之间存在的重复、相似信息。","purpose":"利用图像内部关联压缩数据，减少编码所需比特。","example":"一幅大片蓝天的画面，可用区域预测减少逐个像素的记录。"},"concept:时间冗余":{"definition":"时间冗余指视频前后各帧之间存在的大量相同或可预测的信息。","purpose":"利用帧间预测，只重点编码变化，减少视频数据量。","example":"固定机位拍教室时，背景变化很小，可参考前帧进行编码。"},"concept:固定比特率":{"definition":"固定比特率即CBR，全称Constant Bit Rate，指码率按固定目标维持。","purpose":"便于估算带宽和安排传输，但不同场景的画质可能变化。","example":"视频编码器维持每秒约两兆比特，运动场景可能更模糊。"},"concept:自适应播放":{"definition":"自适应播放根据网络或缓冲状态调整播放策略，以适应传输变化。","purpose":"减少卡顿、溢出或过大延迟，改善连续观看体验。","example":"语音接收端发现到达抖动增大，适当增加后续播放缓冲。"},"concept:RTCP带宽预算":{"definition":"RTCP全称实时传输控制协议，其带宽预算是会话中留给控制报文的份额。","purpose":"据此安排报告发送间隔，避免控制流量过度占用带宽。","example":"会议参与者增多后，各端拉长报告间隔，使总控制流量受限。"},"concept:流量合规性":{"definition":"流量合规性表示数据流是否满足事先约定的速率、突发量等条件。","purpose":"为监管、整形和服务待遇判定提供依据。","example":"某批分组到达时令牌充足，就可按令牌桶规则判为合规。"},"concept:会话上下文":{"definition":"会话上下文是处理某次通信所需的参与者、媒体参数和运行状态等信息。","purpose":"帮助端点正确识别、解码和管理同一会话的数据。","example":"接收端保存会议使用的编码参数和源标识，以处理后续媒体包。"},"concept:同步源":{"definition":"同步源是在实时传输协议中，用同一时序和序号空间发送媒体包的来源。","purpose":"通过同步源标识区分来源，支持排序、播放和接收统计。","example":"会议混音器把混合声音作为一个同步源发出，使用自己的源标识。"},"concept:贡献源":{"definition":"贡献源是在实时传输协议中，为混合媒体包提供原始媒体内容的来源。","purpose":"让接收方了解混合内容来自哪些原始参与者。","example":"混音器合并两位发言者的声音，可在包头列出两人的贡献源标识。"},"concept:固定比特映射":{"definition":"把长度固定的一组二进制位一一对应到一个码元状态。k位共有2^k种取值，码元必须有足够多的可区分状态来容纳它们。","purpose":"判断逐码元编码能装下多长的整数位组，并区分它与允许跨码元联合编码的信息量问题。","example":"可把00、01、10、11分别对应四种不同波形，每次取两位，按同一张映射表发送。"},"concept:脉冲前沿":{"definition":"一次脉冲开始偏离约定基线的那个边沿。正脉冲的前沿通常是上升沿，负脉冲的前沿通常是下降沿，应结合波形极性识别。","purpose":"为脉冲的开始和传播计时选定事件，避免把前沿一律当作上升沿，或与脉冲宽度混淆。","example":"一根线平时为高电平，短暂拉低再恢复；开始拉低的下降沿就是这次负脉冲的前沿。"},"concept:链路在途量":{"definition":"在指定时刻，已经进入某条链路、但尚未到达该链路另一端的比特量；只统计题目指定的数据。","purpose":"按发送与到达的实际进度数比特，不能直接套满链路容量；也不等同于TCP发送端尚未获确认的数据量。","example":"一小包已全部发出而包头尚未到达对端时，它仍在链路途中；等包头开始到达，链路中的剩余部分才逐渐减少。"},"concept:时隙等待":{"definition":"数据准备好后，等到自己获分配的发送时段开始才能发送的时间；它取决于到达时刻在周期中的位置。","purpose":"区分等待下一时隙与真正发送数据的耗时。","example":"轮到甲的时段刚结束，甲的新数据可能要等下一轮。"},"concept:排队缓存":{"definition":"暂存等待链路发送的分组的空间；是否把正在发送的分组计入容量，须按题目约定。","purpose":"分清正在服务、正在等待和因容量不足被丢弃的分组。","example":"窗口正办理一人，旁边两把椅子只能供另外两人等待。"},"concept:尾丢弃":{"definition":"缓存已满时，拒绝新到而放不下的分组，通常保留已在队列中的分组。","purpose":"给有限缓存的溢出处理规定明确行为。","example":"等待区满了，新来的分组不能挤进队列，就被丢弃。"},"concept:超限概率":{"definition":"某个随机数量严格超过给定门槛的概率，也是一类尾概率；它与这个数量的平均值不同。","purpose":"估计随机总需求超过资源容量的可能性。","example":"求一天订单超过100份的概率，不能只算平均有多少订单。"},"concept:独立事件":{"definition":"一个事件是否发生不改变另一个的发生概率；相互独立时，指定联合状态的概率可相乘。","purpose":"把多个独立用户的活跃状态组合起来分析。","example":"两次独立抛硬币中，前一次结果不会改变后一次正面的概率。"},"concept:连接建立时延":{"definition":"传送业务数据前，为建立连接或预留电路而花费的时间。","purpose":"比较含固定准备时间的方案与立即发送的方案。","example":"先拨号接通再讲话，接通前的等待属于建立过程。"},"concept:协议语义":{"definition":"协议中消息各字段代表什么，以及收到消息或发生事件后应采取什么动作。","purpose":"使双方对消息的含义和处理方式达成一致。","example":"收到确认表示哪份数据已被接收，应由双方事先约定。"},"concept:协议时序":{"definition":"协议规定的交互先后、允许的状态顺序及必要的时间关系。","purpose":"避免双方虽然看懂消息，却在不合适的阶段发送或处理。","example":"一方发出请求后等待回应，而不是把回应当成新的请求。"},"concept:应用进程":{"definition":"在端系统上运行、处理应用业务并通过通信接口交换数据的程序执行实例。","purpose":"区分应用中的客户/服务器角色与路由器转发等网络功能。","example":"聊天程序运行后，可通过操作系统提供的通信服务发送消息。"},"concept:消息定界":{"definition":"规定一条应用消息从哪里开始、到哪里结束的规则，可用长度、分隔符等方式。","purpose":"让接收方从收到的数据中恢复完整消息；双方必须采用一致规则。","example":"可约定用特殊结束符标出一条命令的末尾。"},"concept:长度前缀":{"definition":"把后续内容的长度放在内容之前的消息表示方法，需明确长度单位及是否包含前缀自身。","purpose":"让接收方先读长度，再按约定取出相应数据。","example":"某格式先给正文长度，再给正文；长度字段本身也需要固定的解释规则。"},"concept:MX记录":{"definition":"DNS的邮件交换记录，为一个域给出邮件接收服务器的名称，通常还带优先级。","purpose":"帮助发送邮件的一方找到目标域的收信服务器，再查询其地址。","example":"某域的MX可以指向另一台专门收信的主机，未必指向该域的网站。"},"concept:URL":{"definition":"统一资源定位符，描述访问协议、目标主机和资源位置，还可显式指定端口等信息。","purpose":"把浏览器看到的资源地址分解成建立通信和请求资源所需的部分。","example":"https://example.org/help表示用HTTPS访问该主机上的/help资源。"},"concept:最稀缺优先":{"definition":"在可选择的缺失片段中，优先请求当前持有来源较少的片段。","purpose":"尽早扩散稀缺内容，降低少数来源离线后无法补齐文件的风险。","example":"一个片段只有少数在线参与者持有时，可优先把它复制到更多参与者。"},"concept:片段可用性":{"definition":"当前允许访问的来源中，是否有人能够提供所需片段；它与链路带宽是否充足不同。","purpose":"判断现有参与者能否补齐全部内容，以及缺哪一部分。","example":"下载速度再快，也无法从只持有前半部的来源取得后半部。"},"concept:缓存命中率":{"definition":"被缓存直接满足的请求数占请求总数的比例，每个请求通常各计一次。","purpose":"衡量按请求数量统计的复用程度，和按字节量统计的比例区分。","example":"一次小文件请求与一次大文件请求，对请求总数都只贡献一次。"},"concept:字节命中率":{"definition":"由缓存提供的内容字节数占请求内容总字节数的比例，统计时须统一有效内容和计量口径。","purpose":"衡量缓存分担了多少内容流量，避免把不同大小对象等权处理。","example":"命中一个大对象与命中一个小对象，对命中字节量的贡献可以很不同。"},"concept:Base64":{"definition":"把二进制数据表示成一组可打印字符的编码方式；编码不等于加密。","purpose":"让二进制内容能通过以文本表示为主的环境传送。","example":"一段任意字节可以先编码成文本字符，再由接收方解码恢复。"},"concept:编码填充":{"definition":"编码规则为补齐长度或表示末组不足而加入的符号，具体规则由编码格式规定。","purpose":"分清编码后的字符数量与原始有效数据量，不把填充算作新正文。","example":"Base64末尾可能出现等号填充符，它不是原文件中新增的内容。"},"concept:监听套接字":{"definition":"服务器用来等待新的连接请求的套接字，通常持续保留，接入客户后还能继续等待其他客户。","purpose":"承担接入连接的角色，与已建立连接后的收发通道区分。","example":"接单窗口继续接待新客，每个已接入客户另有对应会话。"},"concept:已连接套接字":{"definition":"对应一条已建立连接的通信端点；服务器通常在接受连接后取得它来与该客户收发数据。","purpose":"把不同客户连接的会话状态和数据收发分别管理。","example":"两个客户同时在线时，服务器可分别用各自的通信端点回复。"},"concept:控制连接":{"definition":"FTP中承载登录、命令和状态回复的连接，通常可跨越多次文件传输继续存在。","purpose":"把会话控制与实际文件内容的传输分开分析。","example":"同一会话中先请求列目录，再请求下载，控制信息走控制通道。"},"concept:数据连接":{"definition":"FTP中用于传送文件内容或目录列表等数据的连接，按约定可为各次传输分别建立。","purpose":"区分文件数据通道与长期保持的会话控制通道。","example":"一次文件传输结束后，其数据通道可以关闭，而控制会话仍继续。"},"concept:AS_PATH":{"definition":"BGP记录路由所经过自治系统信息的路径属性；题目采用普通序列时，按序列次序解释这些AS号。","purpose":"记录跨自治系统的传播路径，并可用于识别经过自身的路由；它不是网内接口地址。","example":"某路径属性列出64501、64502，表示其中包含这两个自治系统的路径记录。"},"concept:外部邻居":{"definition":"在BGP语境中，属于另一个自治系统、与本方建立BGP会话的对等体；不等于必须物理直连。","purpose":"区分自治系统内部和跨系统的路由交换，按对应规则处理通告。","example":"AS甲的路由器与AS乙的路由器建立BGP会话，双方互为外部邻居。"},"concept:路径总代价":{"definition":"在采用加性权重的模型中，将给定路径上各段的代价相加，得到该路径的总成本。","purpose":"先求给定路径的成本；是否比较其他路径，要看题目另有无要求。","example":"路径A到X再到B，两段代价分别为3和5，则这条路径的总代价为8。"},"concept:路由跳数":{"definition":"以一次次路由跳跃计量的距离；起点、本地网络等如何计数，要按协议和题目的约定。","purpose":"用统一的计数度量描述路由距离，并与不可达等特殊标记区分。","example":"若约定每跨一条链路计一跳，A到B再到C就是两跳。"},"concept:双极性码片":{"definition":"把码片写成+1或−1的表示方式，分别代表约定的两个相反信号状态。","purpose":"用带符号的短序列描述扩频波形，便于逐项相乘或叠加计算。","example":"码片序列(+1,−1,+1)有三个位置，第二个位置采用与第一个相反的符号。"},"concept:连接四元组":{"definition":"同一传输协议中，用源IP、源端口、目的IP、目的端口这四项描述一对通信端点。","purpose":"区分共用服务器端口的不同连接；只有一个端口号不足以标识整条连接。","example":"两位客户都连服务器的同一个服务端口，只要客户地址不同，四元组就不同。"},"concept:字节序号":{"definition":"按字节在数据流中的位置进行编号；TCP段的SEQ字段用于定位该段对应的序号位置。","purpose":"区分字节位置、报文段个数和应用调用次数，确定数据的先后边界。","example":"一段数据从序号700开始，含20个数据字节，则其数据覆盖700至719。"},"concept:发送基序号":{"definition":"发送窗口中最早尚未得到确认的位置，课件常用SendBase表示；它与下一待发送位置不同。","purpose":"记录累计确认已经推进到哪里，判断哪些已发送数据仍须保留。","example":"某发送方最早未确认的是序号80的数据，即使已经发到更后面，发送基序号仍是80。"},"concept:未确认数据量":{"definition":"发送方已发送、但尚未获得有效确认的数据量；其中有些数据可能已经到达接收方。","purpose":"与窗口额度一起约束还能发送多少，不能直接当作此刻链路里仍在传播的数据量。","example":"已发6KB、确认覆盖其中4KB，则还有2KB未获确认；这不说明这2KB都仍在链路中。"},"concept:确认号约定":{"definition":"确认号的单位和边界由协议约定：可以确认某个分组，也可以表示下一个期待字节。","purpose":"更新发送或接收边界前，先分清是在确认哪种数据，以及编号指已收还是待收。","example":"若协议明定ACK(k)确认分组k，就按分组编号解释，不能把k直接当成字节位置。"},"concept:rdt协议模型":{"definition":"课程中逐步加入差错、丢失和反馈处理的可靠传输抽象模型，各版本的信道假设与状态不同。","purpose":"按题设分组号、反馈含义和当前状态推下一动作，不直接套用完整TCP规则。","example":"题目若采用某个rdt版本，就先核对该版本允许哪些故障，再判断收到反馈后怎么做。"},"concept:等待确认状态":{"definition":"发送方已发出规定数据，正在等待能确认它的有效反馈，此时仍须保存相关发送状态。","purpose":"根据正确确认、损坏反馈或超时等不同事件，决定继续等待、重传还是推进。","example":"发送方等待某编号的确认时，收到无法辨读的反馈，不等于已经拿到了有效确认。"},"concept:零窗口探测":{"definition":"TCP接收方通告窗口为零后，发送方按协议探查窗口是否重新开放的机制。","purpose":"防止窗口重新开放的通知丢失后，双方永久互等；不等于可不限量发送新数据。","example":"接收方腾出了缓存，但开放窗口的通知丢失，后续探测可让发送方重新获知状态。"},"concept:半关闭":{"definition":"TCP两个传输方向中，一个方向已正常结束发送，另一个方向仍可以继续传数据。","purpose":"把结束本方向与立即中止整条双向连接分开。","example":"客户发完请求后结束自己的发送方向，仍可等待服务器把结果发送完。"},"concept:RST":{"definition":"TCP的复位控制标志，用于拒绝或中止连接；其处理不同于FIN所表示的正常方向结束。","purpose":"识别异常终止，不能把它当成有序发送完毕的保证。","example":"应用收到连接复位错误后，需要按异常处理，不能仅凭这次结束就认定业务已成功。"},"concept:TIME_WAIT":{"definition":"TCP正常关闭中的等待状态，用于处理末次确认相关的重传，并减少旧段影响后续连接。","purpose":"在连接结束后继续处理必要的旧报文，而不是立刻丢弃全部相关状态。","example":"末次确认丢失使对端重发FIN时，仍保留状态的一方可以再次确认。"},"concept:CLOSE_WAIT":{"definition":"本端已经接收对端FIN、等待本地应用执行关闭的TCP状态；不是等待对端再发一次FIN。","purpose":"定位关闭流程停在哪一方，并区分协议收到结束信号与应用真正关闭。","example":"服务端收到客户结束发送的通知后，本地程序仍未关闭连接，就可能保持这个状态。"},"concept:重传测量歧义":{"definition":"同一份数据发送多次后，若无法辨别ACK对应哪次发送，就无法直接确定一次准确RTT样本。","purpose":"防止把原发和重发混配成错误时延；题目另给可消歧信息时应按其条件判断。","example":"一份确认到达时，原发和重发都有可能产生它，单凭确认号不足以确定配对的发送时刻。"},"concept:反码加法":{"definition":"按规定字长相加，将最高位产生的进位回加到最低位，而不是直接丢弃这份进位。","purpose":"完成Internet校验和中的求和步骤，并与普通截断加法区分。","example":"四位算例中1111加0001，产生的高位进位回加后，结果写成0001。"},"concept:控制标志位":{"definition":"报文首部中表示控制含义的单个比特；某些字段是否有效或报文如何处理，与标志有关。","purpose":"区分控制状态和数据内容，按协议解释首部字段。","example":"某协议规定一个有效位为0时忽略对应字段，字段里有数值也不能直接采用。"},"concept:事务提交":{"definition":"数据库把一个事务的修改确认为整体成功的操作；这属于应用与数据库的处理阶段。","purpose":"区分网络已经接收数据、应用已处理请求和数据库已完成提交。","example":"请求已送到服务器，数据库更新仍可能等待或失败，需要相应业务结果来确认。"},"concept:流结束通知":{"definition":"接收接口报告该方向的数据流已正常结束的状态，具体返回形式由接口约定。","purpose":"与暂时无数据、接收超时和异常断开分开判断。","example":"非阻塞接收暂时不可读时，仍可能稍后有数据；流结束则表示这一方向不再有新数据。"}},"structures":{"concept:抽象数据类型":{"definition":"抽象数据类型，英文缩写ADT，规定数据及其操作，不限定具体实现。","purpose":"把使用规则与实现细节分开，方便替换实现。","example":"集合支持加入、删除和判定成员，可用不同结构实现。"},"concept:时间复杂度":{"definition":"用输入规模的函数描述基本操作次数的增长趋势，不是实际耗时。","purpose":"比较算法在数据量增大时的计算开销。","example":"逐项求数组最大值，比较次数随元素个数线性增长。"},"concept:空间复杂度":{"definition":"描述算法所需存储空间随输入规模的增长，须说明是否包含输入空间。","purpose":"估计内存需求，比较算法的空间开销。","example":"复制整个数组需要与数组长度成正比的额外空间。"},"concept:最坏情况":{"definition":"在规模相同的所有允许输入中，使算法操作次数最多的情况。","purpose":"给出计算开销的保证，评估性能底线。","example":"插入排序处理逆序的不同元素时，移动次数达到最多。"},"concept:平均情况":{"definition":"在指定输入概率分布下，对同规模输入的操作次数求期望。","purpose":"在概率假设明确时，估计通常的计算开销。","example":"若数组各位置等概率命中，可平均各位置的查找次数。"},"concept:渐近上界":{"definition":"规模足够大时，函数值不超过另一函数的固定常数倍，记作大O。","purpose":"描述增长速度的上限，但不保证界限最紧。","example":"操作次数为三倍规模加二时，可用大O的线性函数表示。"},"concept:基本操作":{"definition":"算法中选来计数的代表性操作，通常假定每次执行耗时为常数量级。","purpose":"通过统计执行次数，分析算法时间复杂度。","example":"分析选择排序时，可把两个元素的大小比较作为基本操作。"},"concept:线性结构":{"definition":"元素按先后形成一条序列，每个元素至多有一个直接前驱和后继。","purpose":"表达具有单一先后次序的数据关系。","example":"按提交时间排列的申请记录，可以组成一个线性表。"},"concept:非线性结构":{"definition":"元素间关系不能仅用一条先后序列表达，可具有分支或交叉联系。","purpose":"表示层级、连接等较复杂的数据关系。","example":"课程之间的先修关系可以用有向图表示。"},"concept:存储结构":{"definition":"数据及其逻辑关系在计算机存储空间中的具体表示方式。","purpose":"决定数据如何存放，并影响操作的实现效率。","example":"同一份名单可存入连续数组，也可存成链接的结点。"},"concept:顺序存储":{"definition":"把逻辑相邻的元素依次放在连续存储单元中，以位置体现关系。","purpose":"便于按序号定位元素，减少链接信息的开销。","example":"用整型数组依次存放一周每天的销售数量。"},"concept:链式存储":{"definition":"用结点存放元素，以指针等链接信息表示关系，结点地址不必连续。","purpose":"便于通过修改链接插入或删除已定位的结点。","example":"空闲内存块可各存一个结点，用指针依次串起来。"},"concept:随机存取":{"definition":"能直接定位任意合法序号的元素，存取时间不随序号远近增长。","purpose":"支持高效的按位置读取，避免逐项经过前面元素。","example":"在合法下标范围内，可直接读取数组a的第八个元素。"},"concept:顺序存取":{"definition":"按结构规定的顺序逐个访问元素，通常不能直接跳到任意位置。","purpose":"适合依次遍历数据，访问后项需经过前项。","example":"仅有头指针时，读取单链表第五项需沿链接向后走。"},"concept:直接前驱":{"definition":"在指定逻辑关系中紧接某元素之前的元素，中间没有其他元素。","purpose":"明确相邻的前向关系，辅助查找及修改链接。","example":"在线性表甲、乙、丙中，乙是丙的直接前驱。"},"concept:直接后继":{"definition":"在指定逻辑关系中紧接某元素之后的元素，中间没有其他元素。","purpose":"明确相邻的后向关系，支持遍历及链接维护。","example":"在线性表春、夏、秋中，夏是春的直接后继。"},"concept:空表":{"definition":"不含任何数据元素的线性表；即使保留辅助头结点，也仍是空表。","purpose":"表示没有数据的状态，作为操作边界条件。","example":"删除待办清单中的全部事项后，清单就成为空表。"},"concept:表长":{"definition":"线性表当前实际包含的数据元素个数，不是容量，也不计辅助头结点。","purpose":"确定有效元素范围，检查插入和删除的位置。","example":"数组容量为二十，只存六条记录时，表长为六。"},"concept:逻辑序号":{"definition":"元素在逻辑次序中的位置编号，起始编号依约定，与内存地址不同。","purpose":"按次序指明目标元素，统一位置参数的含义。","example":"若从一编号，表中第三项对应C数组下标二。"},"concept:元素移动":{"definition":"为调整存放位置，将已有元素搬到其他位置，通常涉及复制其内容。","purpose":"为顺序表插入腾位，或填补删除留下的空位。","example":"删除数组表首项后，将后面各项依次向前搬一格。"},"concept:头结点":{"definition":"链表首个数据结点前可选设的辅助结点，通常不存放有效数据元素。","purpose":"统一首项和其他位置的插入、删除处理。","example":"空链表仍可保留一个哨兵结点，其本身不计入表长。"},"concept:头指针":{"definition":"指向链表起始结点的指针；有头结点时指向它，否则指向首个数据结点。","purpose":"保存链表访问入口，便于从起始位置遍历。","example":"不带头结点的链表插入新首项后，头指针改指新结点。"},"concept:尾指针":{"definition":"记录链表尾部位置的指针，通常指向最后一个数据结点，空表约定另定。","purpose":"快速定位尾部，减少尾插时寻找末端的开销。","example":"保存最后一条日志的结点地址，可直接在其后追加日志。"},"concept:单链表":{"definition":"每个结点含数据和一个后继链接的链表，可分为循环与非循环形式。","purpose":"用链接组织线性数据，支持灵活增删结点。","example":"用非循环单链表保存书目，末结点的后继指针为空。"},"concept:双向链表":{"definition":"每个结点除数据外，还保存前驱和后继链接的链式结构。","purpose":"便于双向遍历，以及在已知结点附近插入或删除。","example":"浏览相册时，可从当前照片转到上一张或下一张。"},"concept:循环链表":{"definition":"末结点的后继链接回到首结点或头结点，形成环的链表。","purpose":"适合反复轮转访问，遍历时须约定停止位置。","example":"三个玩家轮流行动，访问最后一人后再回第一人。"},"concept:空指针":{"definition":"不指向任何对象或函数的指针值，与对象释放后的悬空指针不同。","purpose":"表示没有目标，解引用空指针属于未定义行为。","example":"查找联系人失败时，函数可返回NULL表示未找到。"},"concept:结点删除":{"definition":"从数据结构中移除指定结点，并维护剩余结点的组织关系。","purpose":"移除不再需要的数据，必要时释放其动态存储。","example":"删除通讯录中的某位联系人后，其余联系人仍可访问。"},"concept:链表逆置":{"definition":"调整链表结点之间的链接，使结点顺序与原先完全相反。","purpose":"在保留结点数据的同时，改变整条链的访问顺序。","example":"原链表依次存甲、乙、丙，逆置后依次为丙、乙、甲。"},"concept:有序合并":{"definition":"把按同一规则有序的多个序列，合成仍符合该规则的序列。","purpose":"整合已有排序结果，避免把全部元素重新排序。","example":"合并升序序列[1,6]和[2,5]，得到[1,2,5,6]。"},"concept:集合交集":{"definition":"由同时属于两个集合的所有元素组成的集合，元素不重复。","purpose":"找出两组数据共同拥有的成员或共同满足的条件。","example":"集合{2,5,8}与{1,5,8}的交集是{5,8}。"},"concept:稳定性":{"definition":"排序后，关键字相等的记录仍保持排序前的相对先后顺序。","purpose":"保留同键记录的原有次序，支持多关键字排序。","example":"先按姓名排好，再稳定地按班级排序，同班仍按姓名排列。"},"concept:原地算法":{"definition":"主要在原存储区域处理数据，通常只需常数大小的辅助空间。","purpose":"减少额外内存占用，适合存储空间受限的处理。","example":"用一个临时变量交换数组两端元素，可逐步反转数组。"},"concept:栈顶指针":{"definition":"标记栈顶位置的变量，依实现可指向栈顶元素或下一空位。","purpose":"定位入栈与出栈的位置，避免遍历整个栈。","example":"数组栈也可约定top为栈顶下标，初值为负一。"},"concept:栈底":{"definition":"栈中与栈顶相对的一端；非空时，最早入栈且未弹出的元素位于此端。","purpose":"作为理解栈内顺序和存储布局的基准。","example":"依次压入书甲、书乙后，书甲位于栈底。"},"concept:栈溢出":{"definition":"入栈所需空间超出栈的容量限制，或无法获得所需存储的情况。","purpose":"用于识别入栈失败，防止越界访问或数据损坏。","example":"容量为五的栈已有五项，再压入一项时需要报告失败。"},"concept:栈空":{"definition":"栈内没有任何元素的状态，具体判定方式取决于存储约定。","purpose":"作为出栈或读取栈顶前的检查条件。","example":"开始时为空栈，压入一本书再弹出后，又恢复为空栈。"},"concept:入栈":{"definition":"把一个新元素添加到栈顶，使其成为下一次优先弹出的元素。","purpose":"保存待处理数据，建立后进先出的处理次序。","example":"撤销功能把刚执行的编辑操作压入栈中保存。"},"concept:出栈":{"definition":"移除并通常取得当前栈顶元素，使它下面的元素成为新栈顶。","purpose":"按后进先出的顺序取出并处理已保存的数据。","example":"连续保存两次编辑后，撤销时先取出最近一次操作。"},"concept:合法出栈序列":{"definition":"在给定入栈顺序下，通过允许交错的入栈与出栈操作得到的输出顺序。","purpose":"判断某种输出次序能否由单个栈实现。","example":"依次输入甲、乙，先全部入栈再弹出，可得到乙、甲。"},"concept:后缀表达式":{"definition":"运算符写在其操作数之后的表达式，运算顺序由排列及运算符元数确定。","purpose":"便于利用栈逐项求值，减少括号处理。","example":"表达式“7 2 - 4 *”表示先计算七减二，再乘四。"},"concept:中缀表达式":{"definition":"二元运算符位于两个操作数之间，结合优先级、结合规则及括号解释。","purpose":"以接近日常书写的形式表示计算关系。","example":"“(6+2)*3”用括号表示先求和，再把结果乘三。"},"concept:括号匹配":{"definition":"左右括号类型对应、次序正确，并且嵌套关系完整的性质。","purpose":"检查表达式或程序片段中的括号结构是否正确。","example":"“{[()]}”逐层闭合，能够形成完整的嵌套结构。"},"concept:递归工作栈":{"definition":"保存各层递归调用的参数、局部状态和返回位置的栈式机制。","purpose":"使内层递归返回后，外层能恢复并继续执行。","example":"递归遍历树时，处理完左子树后恢复父结点的待办步骤。"},"concept:函数调用栈":{"definition":"常见实现中按调用层次保存函数活动记录的结构，C17不强制其物理形式。","purpose":"保存调用状态，支持函数返回和嵌套调用。","example":"函数甲调用乙时保存甲的状态，乙返回后甲继续执行。"},"concept:队头指针":{"definition":"标记队列取出端位置的变量，具体可指向首元素或头结点。","purpose":"定位下一次出队的位置，维护先进先出的顺序。","example":"排号队列的队头指向当前最早到达且尚未办理的人。"},"concept:队尾指针":{"definition":"标记队列加入端位置的变量，具体可指向末元素或下一空位。","purpose":"定位入队位置，便于把新元素接到队尾。","example":"链式任务队列增加任务后，队尾指针转向新加入的结点。"},"concept:循环队列":{"definition":"把有限存储位置按环状使用，队头与队尾到末端后可回绕的队列。","purpose":"复用出队后留下的空间，避免频繁搬移元素。","example":"六个数组位置编号零到五，索引越过五后回到零。"},"concept:队空":{"definition":"队列中没有任何有效元素的状态，具体判据取决于存储方式。","purpose":"出队或读取队头前检查，避免取到无效数据。","example":"打印任务全部处理完后，等待队列处于队空状态。"},"concept:队满":{"definition":"有容量上限的队列已用完可用位置，不能继续加入元素的状态。","purpose":"入队前检查，决定拒绝加入还是扩充容量。","example":"某队列最多容纳五项，已有五项时再入队需先处理容量。"},"concept:双端队列":{"definition":"允许在队头和队尾两端插入、删除元素的线性结构。","purpose":"灵活处理两端数据，也可模拟栈和普通队列。","example":"保存浏览记录时，可从尾端追加，也可从头端删除旧记录。"},"concept:链队列":{"definition":"用链表存放元素的队列，通常设置队头、队尾指针实现先进先出。","purpose":"按需申请结点，减少固定数组容量的限制。","example":"新顾客到来时在链尾接入结点，服务完成后移除队头顾客。"},"concept:串长":{"definition":"串所含字符的个数；C语言字符串的结尾空字符不计入长度。","purpose":"确定处理范围，辅助比较、截取和分配存储。","example":"字符串\"cat!\"含三个字母和一个标点，串长为四。"},"concept:空串":{"definition":"不含任何字符、长度为零的串，与含有空格字符的串不同。","purpose":"表示没有文本，也可作为构造串的初始值。","example":"C语言中char s[]=\"\"构造空字符串，仍需空间存放结尾空字符。"},"concept:子串":{"definition":"从一个串中取出的连续字符序列，通常也允许取长度为零的空串。","purpose":"描述文本局部，支持查找、截取和替换操作。","example":"在\"planet\"中，连续的\"lan\"构成子串，跳取的\"pa\"不构成。"},"concept:主串":{"definition":"串匹配操作中接受查找的那个串，其中可能包含要找的模式。","purpose":"提供被搜索的文本范围，确定匹配出现位置。","example":"在\"red blue\"里查找\"blue\"时，整段\"red blue\"是主串。"},"concept:模式串":{"definition":"串匹配操作中希望在主串内找到的字符序列，也称查找模式。","purpose":"规定搜索目标，逐个字符检验是否匹配。","example":"在日志文本中搜索\"ERROR\"时，\"ERROR\"就是模式串。"},"concept:朴素匹配":{"definition":"逐一尝试主串候选起点，每次从模式开头依次比较字符的方法。","purpose":"用简单流程完成子串查找，便于理解和实现。","example":"在\"cab\"中找\"ab\"，先试首字符处，失败后再试第二处。"},"concept:KMP":{"definition":"克努特—莫里斯—普拉特算法，利用模式内部重复关系进行串匹配。","purpose":"复用已比较的信息，减少重复字符比较。","example":"查找\"ababx\"时，已匹配的\"abab\"可用于确定失配后的对齐位置。"},"concept:next数组":{"definition":"KMP即克努特—莫里斯—普拉特算法中记录失配后模式跳转位置的表。","purpose":"依据已匹配部分移动模式，数值依下标约定确定。","example":"若已匹配\"abcab\"，其末尾\"ab\"可与模式开头对齐继续比较。"},"concept:nextval":{"definition":"KMP即克努特—莫里斯—普拉特算法中，对失配跳转表进一步优化的表。","purpose":"跳过必然再次失败的同字符比较，提高匹配效率。","example":"模式\"aaca\"的第2项若与当前字符失配，回退到第1项仍要比较a，可以跳过这次重复比较。"},"concept:部分匹配":{"definition":"模式已有一段前缀与主串对应字符相同，但尚未确认整个模式匹配。","purpose":"记录已有匹配进展，供失配后的继续搜索使用。","example":"查找\"abcd\"时已对上\"abc\"，还未比较最后的d，属于部分匹配。"},"concept:前缀后缀":{"definition":"前缀从串头连续截取，后缀到串尾结束；真前缀、真后缀排除整串。","purpose":"刻画串首尾的重复结构，帮助确定匹配跳转。","example":"对\"mouse\"，\"mo\"是前缀，\"use\"是后缀，两者都是真片段。"},"concept:失配":{"definition":"串匹配过程中，当前对齐的主串字符与模式字符不相等的情况。","purpose":"触发调整比较位置，继续寻找可能的完整匹配。","example":"模式\"dog\"与主串片段\"dot\"比较时，第三个字符发生失配。"},"concept:最长公共前后缀":{"definition":"同一串中内容相等的真前缀与真后缀里最长的一对，可为空串。这里的“真”表示不包含整个原串本身。","purpose":"确定失配时能保留多少已有匹配信息。","example":"串\"abcab\"的最长相等真前缀、真后缀都是\"ab\"，长度为二。"},"concept:行优先":{"definition":"二维数据按行依次排列，每行内部各元素连续存放的存储顺序。","purpose":"将行列位置换成线性偏移，便于顺序访问。","example":"C语言数组int a[2][3]中，第一行三项存完后接着存第二行。"},"concept:列优先":{"definition":"二维数据按列依次排列，每列内部各元素连续存放的存储顺序。","purpose":"适合逐列访问，也用于按列编码二维数据。","example":"将两行三列矩阵手工存入一维数组，可先存第一列的两个元素。"},"concept:地址计算":{"definition":"依据起始地址、元素大小和下标，确定元素在存储区中位置的过程。","purpose":"直接定位数组元素，避免从头逐项查找。","example":"在有效数组int a[6]内，a+3指向第四项，偏移为3*sizeof(int)字节。"},"concept:对称矩阵":{"definition":"满足每个元素都等于其行列下标互换位置元素的方阵。","purpose":"利用镜像关系压缩存储，减少重复计算。","example":"矩阵[[2,5],[5,8]]中两个非对角元素相等，因此是对称矩阵。"},"concept:三角矩阵":{"definition":"主对角线一侧全为零的方阵；压缩存储教材也常将该侧同为常数者纳入。","purpose":"集中存储有效三角区，简化访问与相关运算。","example":"矩阵[[2,4],[0,3]]的主对角线下方为零，是上三角矩阵。"},"concept:带状矩阵":{"definition":"非零元素集中在主对角线附近若干条对角带内，带外元素全为零的矩阵。","purpose":"只存有效带区，节省空间并加快相关计算。","example":"三对角矩阵仅在主对角线及其上下相邻对角线上允许出现非零值。"},"concept:稀疏矩阵":{"definition":"零元素占绝大多数、非零元素相对很少的矩阵，没有统一固定比例门槛。","purpose":"只记录非零值及位置，节省存储和运算量。","example":"一千行一千列的矩阵仅有二十个非零值，可用三元组记录。"},"concept:三元组":{"definition":"稀疏矩阵中，用行号、列号和元素值三个数据记录一个非零元素。","purpose":"只保存非零元素，减少稀疏矩阵的存储量。","example":"三元组（2，4，9）表示第2行第4列的元素为9。"},"concept:十字链表":{"definition":"稀疏矩阵的链式存储结构，每个非零结点有同行、同列的链接。","purpose":"方便沿行或沿列查找，并插入、删除非零元素。","example":"第3行第2列的结点，可沿行链接找到该行下一项。"},"concept:广义表表头":{"definition":"非空广义表的第一个元素，可以是一个原子，也可以是子表。","purpose":"取出首项，便于递归分析广义表的结构。","example":"广义表（（x，y），z）的表头是子表（x，y）。"},"concept:广义表表尾":{"definition":"非空广义表去掉第一个元素后，剩余元素组成的广义表，可以为空。","purpose":"逐步处理剩余部分，配合表头进行递归操作。","example":"广义表（p，q，r）的表尾是（q，r）。"},"concept:原子":{"definition":"广义表中不再作为子表分解的基本元素，与表这种元素相区别。","purpose":"作为嵌套结构的基本数据和递归处理的终点。","example":"在广义表（m，（n））中，m和n都是原子。"},"concept:深度":{"definition":"嵌套结构或搜索过程一层层深入的层次，可指当前层或最大层；起点和计数方式须按具体问题约定。","purpose":"区分一条深入链的层数与累计处理的总数量。","example":"甲调用乙、乙再调用丙时有三层活动调用；丙返回后活动层数减少。"},"concept:树的度":{"definition":"一棵非空树中，所有结点的孩子个数所能达到的最大值。","purpose":"描述树最大的分叉数量，帮助选择存储结构。","example":"某树各结点最多有4个孩子，这棵树的度就是4。"},"concept:结点的度":{"definition":"树中某个结点直接拥有的孩子个数，不包括孙辈，也不计双亲。","purpose":"描述局部分叉情况，区分叶子与分支结点。","example":"结点P直接连接三个孩子，则P的度为3。"},"concept:叶子结点":{"definition":"树中没有孩子的结点，也就是度为零的结点，又称终端结点。","purpose":"表示层次结构的末端，常用于保存最终结果。","example":"只有根结点的一棵树中，根结点本身也是叶子。"},"concept:分支结点":{"definition":"树中至少有一个孩子的结点，即度大于零的结点，也称非终端结点。","purpose":"连接下一级结点，表达分类或分解关系。","example":"目录结点下若还有文件结点，它就是分支结点。"},"concept:孩子兄弟":{"definition":"树的一种链式表示，每个结点分别指向第一个孩子和下一个兄弟。","purpose":"用两个链接表示孩子数量不固定的普通树。","example":"P有孩子Q、R，可由P指向Q，再由Q的兄弟链接指向R。"},"concept:树高":{"definition":"从根到最深叶子的路径所含层数；这里约定根为第1层，空树高为0。","purpose":"衡量树的纵向规模，分析递归所需的空间。","example":"根、孩子、孙辈依次形成三层，则这棵树高为3。"},"concept:结点层次":{"definition":"结点在树中所处的层数；约定根为第1层，孩子比双亲多一层。","purpose":"定位结点的纵向位置，支持按层统计和处理。","example":"从根沿两条边到达的结点，位于第3层。"},"concept:满二叉树":{"definition":"按本课程约定，每一层的结点都达到该层最大数量的二叉树。","purpose":"作为规则结构，推导二叉树的结点数量上限。","example":"根为第1层时，高为3的满二叉树共有7个结点。"},"concept:完全二叉树":{"definition":"除最后一层外各层全满，最后一层的结点从左向右连续排列的二叉树。","purpose":"便于按层存入数组，是二叉堆的结构基础。","example":"根有两个孩子，左孩子还有一个左孩子，可构成完全二叉树。"},"concept:先序遍历":{"definition":"二叉树的一种遍历顺序：先访问根，再依次先序遍历左、右子树。","purpose":"优先处理上层结点，可用于输出表达式前缀形式。","example":"根为M，左孩子为N，右孩子为P，先序为M、N、P。"},"concept:中序遍历":{"definition":"二叉树的一种遍历顺序：先中序遍历左子树，再访问根，最后遍历右子树。","purpose":"按左右之间的位置访问根，可用于有序输出。","example":"根为8，左孩子为4，右孩子为10，中序为4、8、10。"},"concept:后序遍历":{"definition":"二叉树的一种遍历顺序：先后序遍历左、右子树，最后访问根。","purpose":"先处理孩子再处理双亲，适合释放整棵树。","example":"根为T，左孩子为U，右孩子为V，后序为U、V、T。"},"concept:层序遍历":{"definition":"从根开始逐层访问树结点，二叉树中同一层按从左到右的顺序访问。","purpose":"按层统计或查找结点，通常用队列安排访问。","example":"根为K，下一层从左到右是L、M，先访问K再访问L、M。"},"concept:线索二叉树":{"definition":"将二叉链表中的空指针改作某种遍历次序下的前驱、后继链接，并加标记。","purpose":"方便寻找相邻结点，减少遍历对栈的依赖。","example":"中序线索树中，无右孩子的结点可用右线索指向中序后继。"},"concept:二叉排序树":{"definition":"键互异时，每个结点的左子树键都小于它，右子树键都大于它。","purpose":"支持按关键字查找、插入和删除，简称BST。","example":"BST全称Binary Search Tree；根为6时，2可放左侧，9可放右侧。"},"concept:平衡二叉树":{"definition":"这里指AVL树：每个结点的左右子树高度差的绝对值都不超过1的二叉排序树。","purpose":"控制树高，使查找、插入和删除保持高效。","example":"AVL得名于Adelson-Velsky和Landis；根的两子树高为2和1可满足局部平衡。"},"concept:旋转":{"definition":"调整局部双亲、孩子及子树的连接位置，同时保持中序关键字次序的操作。","purpose":"修复平衡二叉树失衡，避免树高持续增长。","example":"右旋时让左孩子升为局部根，原根接到它的右侧。"},"concept:哈夫曼树":{"definition":"给定叶子权值时，使各叶子权值乘路径长度之和最小的二叉树，又称最优二叉树。","purpose":"构造不等长前缀编码，减少平均编码长度。","example":"权值为1、4、8时，先合并1和4，再将所得权值5与8合并。"},"concept:带权路径长度":{"definition":"树中各叶子权值乘以根到该叶子的边数，再将乘积求和，简称WPL。","purpose":"衡量带权树的总代价，用于评价哈夫曼树。","example":"两片叶子权值为4和6，深度均为1，总值为10。"},"concept:前缀编码":{"definition":"一种变长编码，其中任何码字都不是另一个码字的开头部分。","purpose":"使连续码串能直接解码，无须另加分隔符。","example":"码字取0、10、11时，串011可拆为0和11。"},"concept:森林":{"definition":"由零棵或多棵互不相交的树组成的集合，各棵树没有公共结点。","purpose":"表示多组独立的层次关系，也便于研究树的转换。","example":"三家公司各有一棵部门树，合起来构成森林。"},"concept:邻接多重表":{"definition":"无向图的一种链式存储结构，每条边仅存一份，并链接两个端点的关联边。","purpose":"方便遍历顶点的关联边，以及统一修改或删除边。","example":"边甲乙只有一个边结点，甲、乙都能沿各自链找到它。"},"concept:入度":{"definition":"有向图中，以某顶点为终点的弧数；自环对该顶点的入度贡献为1。","purpose":"衡量指向顶点的连接数量，辅助处理依赖关系。","example":"若有甲→丙、乙→丙两条弧，则丙的入度为2。"},"concept:出度":{"definition":"有向图中，以某顶点为起点的弧数；自环对该顶点的出度贡献为1。","purpose":"衡量从顶点发出的连接数量，辅助遍历后继。","example":"若有丁→戊、丁→己两条弧，则丁的出度为2。"},"concept:连通分量":{"definition":"无向图中极大的连通子图，内部任意两顶点之间都有路径相通。","purpose":"把无向图划分成彼此不能到达的独立部分。","example":"甲乙相连，丙单独存在，该图有两个连通分量。"},"concept:强连通分量":{"definition":"有向图中极大的强连通子图，内部任意两顶点都能沿方向互相到达。","purpose":"识别相互可达的顶点组，便于缩点分析图结构。","example":"甲→乙→丙→甲构成环，这三个顶点属于同一分量。"},"concept:深度优先":{"definition":"深度优先搜索，简称DFS；沿未访问的邻接顶点深入，无路可走时回退。","purpose":"遍历树和图，可用于寻找路径及分析连通性。","example":"甲有孩子乙、丙，乙有孩子丁，可依次访问甲乙丁丙。"},"concept:广度优先":{"definition":"广度优先搜索，简称BFS；从起点开始，按与起点的边数逐层访问。","purpose":"遍历树和图，并求无权图中起点到各点的最短距离。","example":"根有两个孩子，先访问完两个孩子，再访问孙辈。"},"concept:Prim":{"definition":"普里姆算法，从一个顶点开始，反复选最小权跨边，将树扩展到新顶点。","purpose":"求连通无向带权图的最小生成树。","example":"铺设村庄线路时，每次把一个未接入村庄接到现有网络。"},"concept:Kruskal":{"definition":"克鲁斯卡尔算法，按边权从小到大考察各边，只接纳不会形成环的边。","purpose":"求无向带权图的最小生成树或最小生成森林。","example":"修路时先考察便宜道路，若两端已有路径相通就跳过。"},"concept:Dijkstra":{"definition":"迪杰斯特拉算法，在非负边权图中逐步确定离源点最近的未确定顶点。","purpose":"求一个源点到其余各顶点的最短路径。","example":"道路耗时均非负时，可计算车站到各景点的最短用时。"},"concept:Floyd":{"definition":"弗洛伊德算法，逐步允许更多顶点作为中转点，更新任意两点的最短距离。","purpose":"求所有顶点对的最短路；允许负边，但不能有负环。","example":"比较甲到丁的直达路线与经乙中转的路线，保留较短者。"},"concept:拓扑排序":{"definition":"将有向无环图的顶点排成线性序列，使每条弧的起点都排在终点之前。","purpose":"安排有先后依赖的任务，并辅助判断有向环。","example":"烤蛋糕要先备料再搅拌，排序时备料必须在搅拌之前。"},"concept:关键路径":{"definition":"活动在边上的工程网络中，从起点到终点总持续时间最长的路径。","purpose":"确定最短工期，并找出不能随意延误的活动。","example":"两条并行施工路线分别耗时6天和9天，后者决定工期。"},"concept:AOE":{"definition":"Activity On Edge，即边表示活动的网络；顶点表示事件，带权弧表示活动及其耗时。","purpose":"描述工程活动的依赖和工期，用于关键路径分析。","example":"从基础完成事件到主体完成事件的弧，表示主体施工活动。"},"concept:AOV":{"definition":"Activity On Vertex，即顶点表示活动的网络；有向边表示活动之间的先后依赖。","purpose":"描述任务执行顺序，常用拓扑排序安排任务。","example":"用顶点表示选题和写稿，以选题指向写稿表示先后要求。"},"concept:最早发生时间":{"definition":"工程网络中，事件在所有前置活动尽早完成的条件下，能够发生的最早时刻。","purpose":"确定事件最早进度，辅助计算活动的开始时间。","example":"某事件须等两项工作完成，分别在第3天和第5天结束，则最早在第5天发生。"},"concept:最迟发生时间":{"definition":"在不推迟工程总工期的前提下，工程网络中某事件允许发生的最晚时刻。","purpose":"确定事件的延误界限，辅助识别关键活动。","example":"终点须在第12天发生，某事件后尚需4天，则该事件最迟在第8天发生。"},"concept:回收标志":{"definition":"动态存储管理中，记录存储块是否空闲、能否参与回收合并的状态标记。","purpose":"帮助管理程序识别可用空间，避免错误合并占用块。","example":"释放一块缓冲区后，将其状态改为空闲，供后续分配使用。"},"concept:空闲块":{"definition":"动态存储区中当前未被占用、可供分配的一段连续空间，通常附带管理信息。","purpose":"为后续存储请求提供空间，并支持分割与合并。","example":"有一块100字节的可用空间，请求40字节后可留下余块。"},"concept:边界标识":{"definition":"在存储块首尾设置大小、占用状态等管理信息，以识别块边界的存储管理方法。","purpose":"快速定位相邻块，在释放时合并连续空闲空间。","example":"释放中间块时，读取相邻块的标识，判断能否合成更大空闲块。"},"concept:伙伴系统":{"definition":"按2的幂次管理存储块，通过对半分裂分配，并仅合并同一次分裂产生的空闲伙伴。","purpose":"加快空间分配和回收合并，但可能浪费块内空间。","example":"申请20字节时可分配32字节块，剩余容量形成块内浪费。"},"concept:垃圾回收":{"definition":"自动识别并释放程序已不再需要的对象所占空间的机制，C17本身不提供。","purpose":"回收无用对象占用的内存，减少手动释放负担。","example":"某对象从所有程序入口都无法到达，回收器将其空间收回。"},"concept:引用计数":{"definition":"为对象记录当前持有它的引用数量，数量归零时回收对象的内存管理方法。","purpose":"及时释放无人引用的对象，但通常难处理循环引用。","example":"两个对象互相引用，外部引用消失后，计数仍可能不为零。"},"concept:归并回收":{"definition":"释放内存块时，将地址相邻的空闲块合并为更大空闲块的空间管理方法。","purpose":"减少外部碎片，提高较大连续空间的分配机会。","example":"相邻的两个空闲块各有32字节，合并后形成64字节空闲块。"},"concept:碎片":{"definition":"内存中难以有效利用的零散空间，包括分配块内的浪费和空闲块间的分散。","purpose":"区分内部与外部碎片，帮助选择空间管理策略。","example":"请求13字节却分配16字节，多出的3字节属于内部碎片。"},"concept:首次适应":{"definition":"按空闲表的既定顺序扫描，选择遇到的第一个足够大的空闲块进行分配。","purpose":"较快找到可用空间，避免每次遍历全部空闲块。","example":"空闲块依次为12、30、20字节，请求18字节时选30字节块。"},"concept:最佳适应":{"definition":"在全部足够大的空闲块中，选择容量最小的一块满足当前内存分配请求。","purpose":"减少本次分配的剩余空间，但可能产生细小碎片。","example":"空闲块为24、40、28字节，请求25字节时选28字节块。"},"concept:边界对齐":{"definition":"让对象起始地址满足其类型要求的对齐条件，布局时可能需要填充字节。","purpose":"满足合法访问要求，并适应处理器的访存方式。","example":"若某类型要求8字节对齐，分配器就为它选择符合条件的地址。"},"concept:顺序查找":{"definition":"从表的一端逐个比较关键字，直到找到目标或检查完所有候选元素。","purpose":"适用于无序表，也适用于不支持随机访问的链表。","example":"在姓名表中依次查看陈、林、周，遇到目标姓名便停止。"},"concept:折半查找":{"definition":"在有序序列中比较中间元素，每次排除一半候选区间的查找方法。","purpose":"配合数组随机访问，可用对数级比较定位目标。","example":"在升序数组中查找35，比较中项后只保留可能含35的半区。"},"concept:查找长度":{"definition":"一次查找进行的关键字比较次数；平均查找长度为ASL，英文全称Average Search Length。","purpose":"结合成功或失败概率，衡量查找所需比较成本。","example":"两种查询等概率出现，分别比较2次和4次，平均查找长度为3。"},"concept:索引顺序表":{"definition":"将数据划分为若干块，块间关键字有序，并另建索引记录各块的查找信息。","purpose":"先借索引定位数据块，再缩小到块内查找。","example":"学生记录按学号范围分块，索引保存各块最大学号及起始位置。"},"concept:分块查找":{"definition":"先查索引确定目标可能所在的块，再在块内顺序查找；块间有序，块内可无序。","purpose":"兼顾索引定位效率和块内记录排列的灵活性。","example":"按编号范围定位到第二块后，逐条比较该块中的记录。"},"concept:散列函数":{"definition":"按确定规则把关键字映射为散列表地址的函数，不同关键字可以映射到同一地址。","purpose":"快速确定记录的候选位置，减少逐项比较。","example":"取编号除以11的余数作地址，编号26映射到地址4。"},"concept:散列冲突":{"definition":"两个不同关键字经过同一个散列函数计算，得到相同散列地址的现象。","purpose":"识别冲突并配合处理策略，保证记录能够存取。","example":"按除以10的余数定位时，编号12和32都映射到地址2。"},"concept:开放定址":{"definition":"冲突后按规定探测序列寻找表内其他槽位，所有记录都直接保存在散列表中。","purpose":"用表内空槽处理冲突，无须另建结点链。","example":"某槽位已占用，继续探测后续候选槽；删除时可保留删除标记。"},"concept:链地址法":{"definition":"将散列到同一地址的记录组织成链表，由该地址对应的表项保存链的入口。","purpose":"通过各地址关联的链表容纳发生冲突的记录。","example":"多个编号都映射到地址5，就把这些记录连接在第5个桶下。"},"concept:线性探测":{"definition":"开放定址的一种方法，冲突后依次检查相邻槽位，到表尾后循环回表头。","purpose":"以简单连续的探测规则寻找记录或可用位置。","example":"容量为11的表从槽9起探测，候选槽依次为9、10、0、1，越过表尾便回到表头。"},"concept:二次探测":{"definition":"开放定址的一种方法，以探测次数的二次式生成相对初始地址的偏移并取模。","purpose":"缓解线性探测的连续聚集，但不保证遍历全表。","example":"采用平方偏移时，可依次尝试初始地址加1、4、9后取模的位置。"},"concept:B树":{"definition":"一种平衡多路查找树，结点可含多个关键字和孩子，所有叶子处于同一层。","purpose":"降低树高，减少外存查找时读取结点的次数。","example":"按最大孩子数定义阶数时，五阶B树每个结点最多含4个关键字。"},"concept:B+树":{"definition":"一种平衡多路索引树，内部结点负责导航，全部数据记录或其指针集中在叶子。","purpose":"兼顾单键定位和有序范围扫描，常用于数据库索引。","example":"查询某月的订单时，先定位起始叶子，再沿叶子链接依次读取。"},"concept:平衡多路树":{"definition":"每个结点允许有多个孩子，并通过平衡约束控制各分支高度的树结构。","purpose":"通过增加分支、控制高度，减少查找经过的层数。","example":"B树让所有叶子位于同一层，插入后必要时分裂结点维持约束。"},"concept:关键字比较":{"definition":"对记录中用于查找或排序的字段进行相等或大小判断，是常用的基本操作。","purpose":"决定查找方向或排序位置，并用于分析算法成本。","example":"按成绩升序排列时，比较两名学生的成绩以确定先后位置。"},"concept:稳定排序":{"definition":"排序后，关键字相等的记录仍保持它们在排序前的相对先后顺序。","purpose":"保留同键记录的原有次序，方便实现多条件排序。","example":"先按姓名排序，再稳定地按班级排序，同班学生仍按姓名排列。"},"concept:插入排序":{"definition":"逐个取出尚未处理的元素，插入前面已有序部分的适当位置，逐步扩大有序段。","purpose":"适合小规模或基本有序的数据，直接插入可原地完成。","example":"有序段为2、6、9，将新元素5插入2与6之间，得到2、5、6、9。"},"concept:希尔排序":{"definition":"把序列按一定间隔分组做插入排序，再逐步缩小间隔的排序方法。","purpose":"让元素先大步移动，减少后续插入时的搬移。","example":"给一组商品价格排序，先比较相隔较远的价格，再逐渐细排。"},"concept:冒泡排序":{"definition":"反复比较相邻元素，遇到逆序就交换，使较大或较小元素逐步移到一端。","purpose":"实现简单，适合小规模数据和学习比较排序。","example":"将三个身高按升序排列，相邻两人站反了就交换位置。"},"concept:快速排序":{"definition":"选取一个枢轴划分序列，再递归处理划分出的较小子序列的排序方法。","purpose":"平均效率较高，常用于内存中的数组排序。","example":"给学生成绩排序，先按某个分数分组，再分别整理各组。"},"concept:枢轴":{"definition":"快速排序划分时选用的比较基准，用来决定其他元素应分到哪一侧。","purpose":"帮助把排序问题拆成规模更小的子问题。","example":"整理价格列表时选价格50作基准，将其他价格按大小分组。"},"concept:划分":{"definition":"把一个集合分成若干非空子集，各子集互不重叠，合起来恰好是原集合。","purpose":"将对象按关系分组，便于分别研究和处理。","example":"将整数集合按奇偶分为两组，每个整数恰好属于其中一组。"},"concept:归并排序":{"definition":"先取得有序子序列，再反复将它们合并成更长的有序序列。","purpose":"常见数组实现最坏用O(n log n)时间；相等时先取原靠前项可保持稳定。","example":"两份已按学号排好的名单，逐项比较合成一份；同学号按原先后保留。"},"concept:堆排序":{"definition":"先建立堆，再反复取出堆顶并调整剩余元素，逐步完成排序的方法。","purpose":"以较少辅助空间完成最坏时间复杂度有保证的排序。","example":"整理一批重量数据，每次利用堆选出当前最大重量并安放。"},"concept:大根堆":{"definition":"一种完全二叉树，每个非根结点的值都不大于其父结点，根保存最大值。","purpose":"支持快速查看最大值，并高效插入和删除。","example":"用大根堆管理任务优先级，堆顶始终是优先级最高的任务。"},"concept:小根堆":{"definition":"一种完全二叉树，每个非根结点的值都不小于其父结点，根保存最小值。","purpose":"支持快速查看最小值，适合反复选取最小项。","example":"管理待处理事件时，以发生时间建小根堆，优先处理最早事件。"},"concept:建堆":{"definition":"调整已有元素的位置，使它们满足指定堆序关系，形成合法堆的过程。","purpose":"为堆排序或优先队列建立可用的初始结构。","example":"将一批订单金额存入数组，再调整为堆顶金额最大的堆。"},"concept:堆调整":{"definition":"堆的局部关系被改变后，通过上滤或下滤移动元素，恢复堆序的操作。","purpose":"维护插入、删除或修改元素后的堆结构。","example":"小根堆中某项数值减小，可让它沿父结点方向上移至合适位置。"},"concept:选择排序":{"definition":"每趟从未排序部分选出最小或最大元素，放入本趟确定位置的排序方法。","purpose":"通过反复选极值，逐步扩大已排序部分。","example":"整理书本高度时，每轮从剩余书本中挑出最矮的一本放好。"},"concept:基数排序":{"definition":"按关键字各位的取值反复分配和收集记录，逐步形成整体次序的排序方法。","purpose":"利用关键字的位结构排序，减少直接比较。","example":"给三位编号排序，可依次按个位、十位、百位进行稳定分组。"},"concept:趟数":{"definition":"排序按算法规则完成若干轮处理时，这些完整处理轮次的数量。","purpose":"描述排序进程，辅助分析算法的工作量。","example":"对六个编号执行一轮完整的相邻比较后，可记为完成一趟。"},"concept:有序段":{"definition":"序列中一段连续元素，其关键字已经按规定的升序或降序排列。","purpose":"作为插入、归并等排序继续处理的基础。","example":"序列中连续出现的2、5、8构成升序段，后面仍可接未排序元素。"},"concept:归并路数":{"definition":"一次归并操作同时参与合并的有序段数量，通常记为k，称为k路归并。","purpose":"影响归并层数、缓冲区分配和选择开销。","example":"同时从五份有序日志中挑选最早记录合并，就是五路归并。"},"concept:置换选择":{"definition":"外部排序生成初始段的方法，在有限内存中不断输出当前可接续的最小记录。","purpose":"利用输入次序生成可能超过内存容量的有序段。","example":"内存容纳三条记录，输出一条后补入新记录，符合当前次序就继续输出。"},"concept:败者树":{"definition":"用于多路选择的树形结构，内部结点记录比较败者，并另存最终胜者。","purpose":"减少多路归并中反复选择下一条记录的开销。","example":"合并多份按时间排序的日志时，用败者树选出当前最早的一条。"},"concept:初始归并段":{"definition":"外部排序开始归并前已经生成的有序记录段，是后续归并处理的基本单位。","purpose":"把大文件变成可逐段合并的有序输入。","example":"大文件分批装入内存排序，每批写回磁盘后形成一个初始段。"},"concept:归并树":{"definition":"描述各有序段逐层合并关系的树，叶子表示初始段，内部结点表示归并结果。","purpose":"分析归并次序、层数和记录的累计处理量。","example":"先合并两份短文件，再把结果与长文件合并，可画成一棵归并树。"},"concept:磁盘读写":{"definition":"在磁盘与内存之间传输数据的操作，通常以块为单位完成实际的数据交换。","purpose":"支持外部数据存取，是外部排序的重要成本。","example":"排序程序读入一块订单记录，处理后再将结果块写回磁盘。"},"concept:顺序文件":{"definition":"记录按关键字次序依次组织的文件，逻辑顺序与存储排列顺序相对应。","purpose":"便于顺序扫描、批量处理和按范围读取记录。","example":"将职工记录按工号递增保存，可从某个工号开始连续读取。"},"concept:索引文件":{"definition":"为数据文件另建索引，记录关键字与存储位置的对应关系，借此定位记录。","purpose":"加快按关键字查找，减少无关记录的读取。","example":"通过学号索引查到学生记录的位置，再到数据文件读取详情。"},"concept:散列文件":{"definition":"通过散列函数把关键字映射到存储桶，并用冲突处理机制存放记录的文件。","purpose":"支持按完整关键字进行较快的直接查找。","example":"将订单号映射到对应桶，查找时计算桶号，再核对桶内订单。"},"concept:倒排文件":{"definition":"以关键词为入口，记录各关键词出现在哪些文档或记录中的文件组织方式。","purpose":"快速找出含指定关键词的记录，减少逐条扫描。","example":"查“树”对应的表项，得到含它的文档编号集合。"},"concept:记录长度":{"definition":"一条记录占用的存储单位数，通常按字节计，可固定，也可随内容变化。","purpose":"确定记录边界，计算空间需求及存放位置。","example":"一条记录含六字节编号和十字节正文，长度为十六字节。"},"concept:逻辑记录":{"definition":"从应用角度作为一个整体处理的一组相关数据，不必对应一个物理块。","purpose":"按业务含义组织数据，便于查询和更新。","example":"一名学生的学号、姓名和成绩合起来构成一条逻辑记录。"},"concept:物理块":{"definition":"外存中按块组织和传输数据的存储单位，一个块可以容纳多条记录。","purpose":"作为读写单位，分析外存访问次数与空间占用。","example":"系统一次读入一个数据块，再从块内查找所需记录。"},"concept:块因子":{"definition":"一个物理块容纳的逻辑记录数；定长且记录不跨块时，常指最大容纳数。","purpose":"估算文件块数及一次读块可取得的记录量。","example":"块可用空间为八百字节，每条记录一百字节，可放八条。"},"concept:操作计数":{"definition":"先约定统计哪些基本操作，再计算算法执行中这些操作发生的次数。","purpose":"比较算法代价，避免把不同操作混在一起计数。","example":"统计数组查找时的元素比较次数，不计循环变量更新。"},"concept:渐近增长":{"definition":"研究输入规模足够大时，时间或空间代价随规模变化的增长规律。","purpose":"忽略常数和低阶影响，比较算法的规模适应能力。","example":"代价为三倍规模加七时，通常归为线性增长。"},"concept:对数阶":{"definition":"代价随输入规模的对数增长，常见于每轮将问题规模缩小固定比例。","purpose":"描述折半等算法处理大规模数据时的增长速度。","example":"在有序数组中折半查找，每轮把候选范围缩小约一半。"},"concept:空间开销":{"definition":"算法运行占用的存储空间；额外空间专指输入存储之外新增的部分。","purpose":"判断内存需求，并比较不同实现的空间代价。","example":"用一个临时数组保存全部元素，会增加随元素数增长的空间。"},"concept:逻辑位置":{"definition":"元素在数据结构规定次序中的位置，编号起点由约定决定，并非内存地址。","purpose":"描述查找、插入和删除针对哪个次序位置。","example":"队列中最早等待的人位于队头，无须知道其数据地址。"},"concept:元素保持顺序":{"definition":"排序时，关键字相等的元素仍保持排序前的相对次序，称为稳定。","purpose":"保留同值记录已有顺序，支持多关键字排序。","example":"成绩相同的两名学生，排序后仍按原来的报名先后排列。"},"concept:连续存储寻址":{"definition":"等长元素连续存放时，可由首地址、元素下标和元素大小计算其位置。","purpose":"直接定位指定元素，支持常数时间的下标访问。","example":"在有效下标范围内，用数组名加下标访问对应元素。"},"concept:链接关系":{"definition":"用指针或位置编号表示结点之间的连接，连接对象和方向决定结构。","purpose":"表达前后、父子等关系，支持结点间导航。","example":"树结点的左孩子指针指向其左子树根，空指针表示没有。"},"concept:边界处理":{"definition":"针对空结构、首尾位置及容量极限等特殊情况规定正确处理方式。","purpose":"防止越界、非法访问、遗漏元素或无法终止。","example":"从空队列取元素时，先报告失败，不读取不存在的数据。"},"concept:数据抽象":{"definition":"只描述数据的含义、关系和允许的操作，将具体存储与实现细节隐藏。","purpose":"让使用者依赖行为约定，便于替换底层实现。","example":"使用栈只关心压入和弹出，不必知道内部采用数组还是链表。"},"concept:操作接口":{"definition":"对外规定操作名称、参数、返回结果及适用条件，形成统一调用约定。","purpose":"明确如何使用结构，以及成功或失败的含义。","example":"取队头接口返回是否成功，并通过输出参数交付元素值。"},"concept:结构不变式":{"definition":"数据结构在有效状态下始终需要满足的约束，操作完成后应继续成立。","purpose":"作为检查和推理依据，帮助保证操作正确。","example":"顺序表长度始终非负，且不超过已分配的元素容量。"},"concept:双指针遍历":{"definition":"用两个指针协调移动或维护不同位置，共同完成数据结构的扫描操作。","purpose":"跟踪位置关系，减少重复查找或辅助存储。","example":"快指针每次走两步，慢指针走一步，可用于寻找链表中点。"},"concept:缓冲区容量":{"definition":"缓冲区已分配空间能够容纳的数据上限，须注明按字节还是元素计。","purpose":"判断还能写入多少数据，避免超出分配范围。","example":"容量十字节的字符数组存放字符串时，结束空字符也占一字节。"},"concept:递归展开":{"definition":"把一次递归调用逐层分解为子问题调用，直到满足终止条件，再逐层返回。","purpose":"看清调用过程、结果依赖和调用栈空间需求。","example":"计算阶乘时先求较小数的阶乘，返回后再逐层乘回。"},"concept:访问顺序":{"definition":"遍历结构时，按既定规则依次处理各个元素或结点形成的先后次序。","purpose":"保证遍历符合任务要求，确定结果输出的次序。","example":"广度优先遍历从起点出发，先访问距离较近的结点。"},"concept:模式匹配进度":{"definition":"字符串匹配过程中，当前检查到的文本位置及模式串已匹配的前缀长度。","purpose":"决定下一步比较哪里，以及失配后如何继续。","example":"模式串前三个字符已匹配，下一步比较文本后续字符与第四字符。"},"concept:字符位置":{"definition":"字符在序列中的次序编号，须约定编号起点；多字节编码中不等于字节偏移。","purpose":"定位查找结果，确定插入、删除或截取位置。","example":"从零编号时，字符串“code”中的字母d位于位置二。"},"concept:多维下标映射":{"definition":"按各维长度和存放次序，将多维下标换算为线性存储中的元素偏移。","purpose":"定位多维元素，并区分逻辑坐标与存储位置。","example":"C语言三列二维数组中，合法元素a[1][2]距首元素五个元素位置。"},"concept:压缩存储映射":{"definition":"压缩存储映射是按规则把需保留的数据对应到紧凑存储位置，省去可恢复的冗余。","purpose":"减少存储占用，并能查回原来的逻辑位置。","example":"对称矩阵只存下三角，上三角元素通过交换行列下标查找。"},"concept:父子关系":{"definition":"树中一个结点直接连接的下一层结点是它的孩子，它则是这些结点的父结点。","purpose":"描述树的层次，支持查找亲属和组织遍历。","example":"目录“照片”下直接包含“旅行”，前者就是后者的父结点。"},"concept:完全二叉树编号":{"definition":"完全二叉树从根开始，按层从上到下、同层从左到右连续编号，通常从1开始。","purpose":"用编号计算亲属位置，便于数组存储。","example":"从1编号时，编号4的结点若有左孩子，其编号就是8。"},"concept:有序性维护":{"definition":"有序性维护是在插入、删除或修改数据后，仍使结构满足约定的大小排列规则。","purpose":"保证查找、范围查询和后续归并能够正确进行。","example":"递增数组中加入数值7时，将它放在5与9之间并后移尾段。"},"concept:图的存储表示":{"definition":"图的存储表示是用数组、链表等结构记录顶点，以及顶点间的边和相关信息。","purpose":"支持查询邻接关系，并影响遍历的开销。","example":"邻接表给每个城市保存一份列表，列出有直达道路的城市。"},"concept:可达性":{"definition":"图中若存在从顶点甲到顶点乙的路径，就称乙从甲可达；有向图须遵守边方向。","purpose":"判断节点之间能否连通或沿关系到达。","example":"存在甲到乙、乙到丙的单向道路时，可以从甲到达丙。"},"concept:顶点访问标记":{"definition":"顶点访问标记是遍历时为各顶点记录的状态，用来区分未发现、已发现或已处理。","purpose":"避免重复处理顶点，使含环图的遍历可控。","example":"深度优先搜索进入一个城市时作标记，遇到回边便跳过它。"},"concept:候选路径比较":{"definition":"候选路径比较是按边数、权值和等指定标准，比较多条可行路径的优劣。","purpose":"更新当前最佳路线，支持求解最短路径。","example":"两条路线总费用分别为12和17，按费用最少标准选择前者。"},"concept:贪心选择":{"definition":"贪心选择是在当前可行选项中选局部最优项；能否得到全局最优需要证明。","purpose":"在满足条件的问题中简化决策、减少搜索。","example":"选择互不重叠的活动时，每次优先选结束时间最早的可选活动。"},"concept:部分有序":{"definition":"部分有序表示数据只满足某些位置间的大小约束，整体并未形成完整的排序序列。","purpose":"用较少维护代价支持极值查询等操作。","example":"小根堆中父结点不大于孩子，但左右子树之间不必整体有序。"},"concept:数据分布":{"definition":"数据分布指输入中各类取值的多少、排列及集中情况，不仅是数据总量。","purpose":"帮助选择算法，分析不同输入下的实际性能。","example":"同为一千个整数，几乎递增和随机排列会使插入排序耗时不同。"},"concept:内外存访问":{"definition":"内外存访问指读写内存与磁盘等外部存储；外存通常按块传输，延迟更大。","purpose":"识别存储瓶颈，减少代价较高的数据传输。","example":"处理大文件时一次读入一批记录，通常比逐条发起磁盘读取高效。"},"concept:块访问次数":{"definition":"块访问次数是算法执行期间读写存储块的次数，常用于衡量外存算法的开销。","purpose":"估计磁盘传输成本，比较外存处理方案。","example":"文件占十个块且缓存为空，顺序完整读取一遍需要读入十个块。"},"concept:记录定位":{"definition":"记录定位是依据下标、键值或地址，确定目标记录所在位置的过程。","purpose":"为读取、更新和删除指定记录找到入口。","example":"数组中的学生记录等长连续存放，可由起始地址和下标计算位置。"},"concept:合并有序序列":{"definition":"合并有序序列是把多个按同一规则排好的序列，组合成仍按该规则排列的序列。","purpose":"汇总已排序数据，是归并排序的基本操作。","example":"把递增序列(2,8)与(3,6)合成递增序列(2,3,6,8)。"},"concept:比较与移动":{"definition":"比较是判断元素大小等关系，移动是改变元素存放位置，两者通常分别计数。","purpose":"细分算法成本，区分判断开销与数据搬运。","example":"扫描数组求最大值会反复比较元素，却不必改变任何元素的位置。"},"concept:空闲空间组织":{"definition":"空闲空间组织是记录和管理尚未分配的存储区域，以便后续分配、回收和复用。","purpose":"提高存储利用率，支持动态申请与释放。","example":"固定大小的结点池可把闲置结点串成空闲链，每次取出链首使用。"},"concept:对象生命周期":{"definition":"对象生命周期是对象存在且存储被保留的期间；动态分配对象可在释放时结束生命。","purpose":"判断对象何时可用，避免访问失效的存储。","example":"动态数组释放后，继续通过原指针读取其中元素属于未定义行为。"},"concept:算法":{"definition":"算法是针对一类问题给出的有限、明确、可执行的步骤，并在有限步骤后结束。","purpose":"把求解方法变成可实现、可分析的过程。","example":"求一组数的最大值，可先取首项，再逐项比较并更新当前最大值。"},"concept:输入规模":{"definition":"输入规模是衡量待处理问题大小的量，需按问题明确，可用一个或多个参数表示。","purpose":"把运行开销与问题大小联系起来进行分析。","example":"分析图算法时，常同时用顶点数和边数表示输入规模。"},"concept:语句频度":{"definition":"语句频度是一条语句在某次执行中被执行的次数，可能随输入规模和内容变化。","purpose":"统计基本操作次数，推导算法的时间开销。","example":"循环变量从0到n减1，每轮执行一次累加，则累加语句执行n次。"},"concept:渐近分析":{"definition":"渐近分析研究输入规模增大时资源开销的增长趋势，通常忽略常数因子和低阶项。","purpose":"比较大规模输入下的效率，减少机器差异影响。","example":"操作次数为3n²加5n时，其渐近增长阶为平方阶。"},"concept:常数因子":{"definition":"常数因子是开销表达式中不随输入规模变化的乘数，渐近阶相同也可存在差别。","purpose":"解释同阶算法的实际速度差异，指导实现优化。","example":"两种方法分别执行2n与8n次基本操作，都为线性阶但成本不同。"},"concept:算法终止性":{"definition":"算法终止性指对每个合法输入，执行过程都能在有限步骤内结束并给出结果。","purpose":"保证求解不会无限进行，并帮助检查循环条件。","example":"处理有限集合时，每轮删除一个待处理元素，集合清空后即可结束。"},"concept:规格说明":{"definition":"规格说明写清输入条件、输出要求及操作约束，是判断程序行为的依据。","purpose":"统一实现与验收标准，减少需求理解偏差。","example":"查找函数约定接收有序数组，未找到时返回指定状态。"},"concept:健壮性":{"definition":"健壮性指程序遇到非法输入或异常情况时，仍能按约定妥善处理的能力。","purpose":"避免异常扩散，并给调用者明确反馈。","example":"读取人数时遇到负数，报告输入无效并允许重新输入。"},"concept:模块接口":{"definition":"模块接口是模块对外提供的调用约定，包括参数、返回值及使用条件。","purpose":"让模块独立实现，又能正确配合工作。","example":"队列提供入队函数，调用者无需知道内部使用数组还是链表。"},"concept:错误状态编码":{"definition":"错误状态编码是用约定的数值或枚举值，区分操作失败原因的表示方式。","purpose":"帮助调用者识别故障并采取相应措施。","example":"读取记录时，分别用不同状态表示文件结束和读取失败。"},"concept:算法正确性":{"definition":"算法正确性指对满足约定条件的输入，算法都能按要求结束并给出结果。","purpose":"保证求解结果符合问题规定的含义。","example":"求最大值的算法，应能正确处理所有元素均为负数的数组。"},"concept:共享状态":{"definition":"共享状态指多个调用或执行单元能够访问的同一份可变数据。","purpose":"方便交换信息，但必须协调访问和修改。","example":"递归函数共用一个全局计数器，内层修改会影响外层结果。"},"concept:数据关系":{"definition":"数据关系指数据元素之间在逻辑上的联系，如前后顺序或父子关系。","purpose":"描述数据组织方式，指导结构与操作设计。","example":"家谱中父母与子女的联系可用树形关系表达。"},"concept:操作数":{"definition":"操作数是运算符作用的对象，可以是常量、变量或其他表达式的结果。","purpose":"指出一次运算具体处理哪些数据。","example":"表达式x乘以5中，变量x和常量5都是乘法的操作数。"},"concept:运算符":{"definition":"运算符是表示特定运算的符号，其含义还受到操作数类型等条件影响。","purpose":"表达计算、比较、赋值等数据处理动作。","example":"C语言中，两个整数之间的%运算符用于求整除余数。"},"concept:表达式优先级":{"definition":"表达式优先级规定不同运算符的结合层次，本身不规定操作数求值先后。","purpose":"确定表达式结构，避免误解计算含义。","example":"表达式a+b*c结合为a+(b*c)，括号可改变这种结合方式。"},"concept:栈顶位置":{"definition":"栈顶位置用于定位栈的操作端，可约定指向当前元素或下一空位。","purpose":"支持入栈出栈，并据约定判断栈的状态。","example":"链栈可用头指针指向栈顶结点，空指针表示当前没有元素。"},"concept:顺序栈容量":{"definition":"顺序栈容量是当前分配的连续存储空间最多能够容纳的元素个数。","purpose":"判断剩余空间，防止入栈时访问越界。","example":"某栈容量为8，已有6个元素，还能再存入2个元素。"},"concept:逆序对":{"definition":"逆序对指序列中位置在前的元素值严格大于位置在后的元素所组成的对。","purpose":"衡量序列偏离升序的程度，辅助分析排序。","example":"序列[2,5,3]中，5在3之前且更大，两者构成逆序对。"},"concept:排列数":{"definition":"排列数是从不同元素中选出指定个数并排成一列时，不同次序的数量。","purpose":"统计有次序区别的安排，分析可能情况数。","example":"从甲乙丙中选两人排先后，共有6种不同安排。"},"concept:比较排序下界":{"definition":"比较排序下界指仅靠关键字比较排序时，最坏比较次数至少为Ω(n log n)。","purpose":"判断比较排序的渐近效率还能否提高。","example":"对互异关键字，比较决策树必须能区分n!种可能的输入次序。"},"concept:归并选择":{"definition":"归并选择是在多个有序段中，反复比较各段当前候选元素并选出下一个。","purpose":"逐项生成整体有序的归并结果。","example":"升序段[2,7]与[4,6]归并，先选2，再比较7与4。"},"concept:输入输出缓冲":{"definition":"输入输出缓冲是在程序与外部设备之间暂存数据的空间，用于分批传送。","purpose":"减少零散传输，协调处理与设备速度。","example":"写文件时先把多条短记录存入缓冲区，再集中写入磁盘。"},"concept:双缓冲":{"definition":"双缓冲使用两块缓冲区轮换工作，在条件允许时让传输与处理重叠。","purpose":"减少等待设备的时间，提高整体处理效率。","example":"程序处理甲缓冲区数据时，设备同时向乙缓冲区读取下一批。"},"concept:异步输入输出":{"definition":"异步输入输出允许程序提交传输请求后继续执行，再通过通知等方式获知完成。","purpose":"让计算与设备传输有机会同时推进。","example":"发起磁盘读取后先处理另一批数据，收到完成通知再使用新数据。"},"concept:归并段":{"definition":"归并段是归并过程中作为一个整体参与合并的有序数据序列。","purpose":"作为归并的基本单位，逐步扩大有序范围。","example":"数组前半段与后半段分别排好序后，可作为两个段进行归并。"},"concept:平均与最坏情况":{"definition":"平均情况按指定输入分布求代价期望，最坏情况取同规模输入中的最大代价。","purpose":"分别评估通常开销和最大资源需求。","example":"顺序查找的平均比较次数依赖目标出现的位置及其概率。"},"concept:索引":{"definition":"索引是记录查找键与数据位置对应关系的辅助结构，需要额外空间维护。","purpose":"减少查找范围，加快定位目标数据。","example":"为学生记录建立学号到存储位置的表，可按学号快速定位记录。"},"concept:索引规范化":{"definition":"索引规范化是把不同起点或表示方式的位置索引，转换成统一约定的过程。","purpose":"避免位置换算混乱，统一访问和边界判断。","example":"用户输入从1开始的编号，访问数组前先减1，转为从0计数。"},"concept:事务":{"definition":"文件批量更新中的事务，是一条待执行的插入、删除或修改记录。","purpose":"集中描述数据变更，便于批量更新主文件。","example":"事务文件记录删除某学号对应的学生记录，合并更新时执行该操作。"},"concept:顺序更新":{"definition":"按关键字顺序扫描主文件，集中处理一批插入、删除或修改操作。","purpose":"减少反复查找和随机读写，适合批量维护。","example":"学籍表和变更表按学号排序后，扫描生成新版学籍表。"},"concept:稠密索引":{"definition":"覆盖每个查找键值的索引；重复键可附记录列表，也可逐记录建项。","purpose":"通过索引直接定位匹配记录，减少文件扫描。","example":"商品索引为每种条码保存入口，指向对应商品记录。"},"concept:倒排索引":{"definition":"以属性值为入口，保存具有该值的记录标识集合的一种索引。","purpose":"快速查找匹配记录，并组合多个检索条件。","example":"以“篮球”为入口，保存所有包含该词的文章编号。"},"concept:集合并集":{"definition":"由属于集合A或属于集合B的全部元素组成的集合，重复元素只计一次。","purpose":"合并不同来源的成员，得到完整且不重复的结果。","example":"甲组选课名单与乙组选课名单合并，得到总选课名单。"},"concept:集合差集":{"definition":"集合A减去集合B，所得集合只保留属于A但不属于B的元素。","purpose":"从已有结果中排除指定成员，找出剩余部分。","example":"从已报名学生集合中减去已缴费集合，找出待缴费者。"},"concept:集合去重":{"definition":"按指定的相等规则识别重复元素，让每种不同元素只保留一个。","purpose":"消除重复数据，便于统计、检索和集合运算。","example":"编号序列7、7、9去重后保留7、9，各出现一次。"},"concept:索引重建":{"definition":"根据现有数据记录重新生成索引项，并恢复索引的组织结构。","purpose":"修复失效索引，或在大量更新后恢复检索效率。","example":"图书记录批量导入后，重新建立按书号查询的索引。"},"concept:分块存储":{"definition":"把数据分成若干块，每块容纳多个元素，块间按约定方式组织。","purpose":"兼顾成批存取效率与存储空间管理的灵活性。","example":"长文本每块保存若干字符，再用链接连接各个字符块。"},"concept:块内寻址":{"definition":"确定目标所在块后，根据块内偏移找到具体元素的存储位置。","purpose":"把整体位置转换成块内位置，完成元素访问。","example":"每块容纳八项时，下标十对应第二块内的下标二。"},"concept:广义表层次":{"definition":"广义表通过子表嵌套形成层次；有限非递归表通常以最大嵌套数计深度。","purpose":"描述嵌套关系，帮助设计递归遍历与处理方法。","example":"表(a,(b,(c)))中，原子c位于比a更深的层次。"},"concept:广义表长度":{"definition":"广义表最外层直接包含的元素个数；一个子表整体只算一个元素。","purpose":"衡量当前层规模，区分外层元素与内部内容。","example":"表(x,(y,z),())的长度为三，空子表也占一项。"},"concept:矩阵对角线":{"definition":"主对角线由行列下标相同的元素组成；方阵副对角线连接右上与左下。","purpose":"划分矩阵区域，辅助判断结构与安排压缩存储。","example":"三阶方阵主对角线包含a[0][0]、a[1][1]和a[2][2]。"},"concept:矩阵压缩":{"definition":"利用矩阵的对称、重复或大量零元素等特点，只保存必要数据。","purpose":"减少存储空间，并按映射关系访问原矩阵元素。","example":"一个大多为零的矩阵，用行号、列号和值保存非零项。"},"concept:幂集":{"definition":"一个集合的所有子集构成的集合，包括空集和原集合本身。","purpose":"表示全部可能的成员选择，用于枚举与组合搜索。","example":"集合{p,q}的幂集包含空集、{p}、{q}和{p,q}。"},"concept:子集计数":{"definition":"含n个不同元素的有限集合共有2的n次方个子集，因为各元素可选或不选。","purpose":"估计枚举规模，判断穷举算法的时间开销。","example":"五个不同开关各选开或关，对应三十二种选择集合。"},"concept:码长":{"definition":"一个码字包含的编码符号数量；二进制码的码长就是所含比特数。","purpose":"衡量编码开销，并结合出现频率计算平均码长。","example":"符号甲编码为10110，该二进制码字的码长是五。"},"concept:唯一译码":{"definition":"任意合法码字串连接后，所得编码串都只能还原成一种源符号序列。","purpose":"保证解码结果确定，避免同一编码产生多种解释。","example":"甲编码为0、乙编码为10时，010只能解为甲乙。"},"concept:树的层次":{"definition":"结点层次表示它离根的层级；根计第一层时，孩子比双亲高一层。","purpose":"描述结点位置，用于层序遍历和树高分析。","example":"约定根为第一层，则根的孩子在第二层，孙结点在第三层。"},"concept:有向无环图":{"definition":"不含任何有向环的有向图，英文全称Directed Acyclic Graph，简称DAG。","purpose":"表示先后依赖关系，支持拓扑排序和任务调度。","example":"任务甲必须先于乙，乙必须先于丙，且没有返回依赖。"},"concept:活动时差":{"definition":"在活动用边表示的工程网络中，活动最迟开始时间减去最早开始时间。","purpose":"衡量活动在不延误总工期时可推迟的时间。","example":"某活动最早第二天、最迟第五天开始，其时差为三天。"},"concept:内存分配":{"definition":"为对象取得所需存储空间；C语言动态分配可能失败，需检查返回指针。","purpose":"按运行时需求创建结点、数组等可变规模数据。","example":"用malloc申请一个链表结点，成功后初始化，弃用时free释放。"},"concept:向上取整":{"definition":"取大于或等于某个数的最小整数，常用于计算容纳全部数据所需单元数。","purpose":"保证容量足够，避免剩余不足一份的数据被漏算。","example":"十九件物品每盒最多装六件，需要向上取整得到四盒。"},"concept:内存对齐":{"definition":"对象地址须满足其类型的对齐要求，结构体可能因此含有填充字节。","purpose":"满足平台访问要求，影响对象布局及实际占用空间。","example":"含char和int的结构体，sizeof结果可能大于两成员大小之和。"},"concept:内存碎片":{"definition":"分配块内部未利用的空间称内部碎片，分散空闲块造成的是外部碎片。","purpose":"评估空间浪费，辅助选择分配策略与整理办法。","example":"空闲区虽共十兆，却没有连续六兆区域，体现外部碎片。"},"concept:伙伴块寻址":{"definition":"伙伴系统按块大小和池内偏移定位配对块，等大相邻不一定互为伙伴。","purpose":"用于判断空闲块能否合并，减少内存碎片。","example":"以字节计，大小为8、偏移为16的块，其伙伴偏移为24。"},"concept:标记清除":{"definition":"垃圾回收先标记从根可达的对象，再回收未标记对象，通常不移动对象。","purpose":"自动释放不再可达的内存，允许回收无用环。","example":"两个结点互相引用，但从所有根均不可达，可一起回收。"},"concept:可达对象":{"definition":"从程序指定的根出发，沿有效引用经过有限步能够访问到的对象。","purpose":"帮助垃圾回收器区分需保留与可回收的对象。","example":"根指针指向甲，甲再引用乙，则甲和乙都可达。"},"concept:内存池边界":{"definition":"内存池管理区域的起止位置，分配块及其元数据必须位于允许范围内。","purpose":"防止分配越界，以及错误合并池外的内存块。","example":"池有512字节，从偏移500分配20字节会超出边界。"},"concept:存储开销":{"definition":"为保存数据及管理结构占用的存储空间，包括指针、标志和对齐填充。","purpose":"比较数据结构的空间成本，辅助选择实现。","example":"链表结点除整数数据外，还需空间保存后继指针。"},"concept:代码可读性":{"definition":"代码让读者容易理解其意图、数据含义和控制流程的程度。","purpose":"降低维护和排错成本，便于检查算法逻辑。","example":"把变量命名为count，并注明它记录当前有效元素数。"},"concept:序关系":{"definition":"描述元素先后次序的关系；全序要求任意两元素可比较，偏序不要求。","purpose":"为排序和有序查找提供一致的比较依据。","example":"集合按包含关系形成偏序，集合{1}与{2}无法比较先后。"},"concept:线索标志":{"definition":"线索二叉树中用于区分指针指向孩子还是遍历前驱、后继的标记。","purpose":"避免把线索当孩子访问，支持按线索遍历。","example":"约定左标志为1时，左指针保存中序遍历的前驱。"},"concept:UTF-8":{"definition":"全称Unicode转换格式8位，是用一至四个八位字节编码一个Unicode标量值的方案。","purpose":"统一保存多语言文本，并兼容ASCII基本字符。","example":"字符“山”的UTF-8编码占三个字节，字符B占一个字节。"},"concept:字节偏移":{"definition":"某位置相对基准地址相隔的字节数，区别于按元素计数的下标。","purpose":"定位缓冲区内容，计算字段或元素的存储位置。","example":"若数组元素各占4字节，下标3的元素距首元素12字节。"},"concept:字符编码":{"definition":"将字符对应到数值并规定存储表示的规则，不同编码的表示可能不同。","purpose":"使文本能够存储、传输，并被正确解释。","example":"按ASCII编码，字符A对应数值65，字符B对应66。"},"concept:数组初始化规则":{"definition":"C17中数组可用初始化列表赋值，未列出的元素补零；变长数组不能初始化。","purpose":"明确数组的初始内容，避免读取未确定的值。","example":"声明int a[5]={7,8}，其余三个元素都初始化为0。"},"concept:数组元素访问":{"definition":"C中a[i]等价于*(a+i)，通过下标定位并访问元素，访问必须在有效范围内。","purpose":"按位置直接读取或修改数组中的指定元素。","example":"int a[3]={6,8,9};执行a[1]=5后，第二个元素变为5。"},"concept:边界索引":{"definition":"标识有效访问范围两端的下标；长度为n的数组元素下标为0至n−1。","purpose":"约束循环和元素访问，防止越界未定义行为。","example":"长度为6的数组可访问a[5]，读取a[6]属于未定义行为。"},"concept:元素类型与步长":{"definition":"数组元素类型决定单个元素大小，相邻元素地址间隔为sizeof该类型字节。","purpose":"正确理解指针移动及数组地址计算。","example":"若double占8字节，指向数组元素的指针加1就前进8字节。"},"concept:指针指向关系":{"definition":"指针值表示它指向哪个对象或位置，复制指针不会复制所指对象。","purpose":"分析共享引用、链式连接和对象的访问路径。","example":"p和q都指向同一整数时，通过*p赋值也会改变*q读到的值。"},"concept:函数接口":{"definition":"函数向调用者公开的名称、参数、返回类型，以及使用条件和结果约定。","purpose":"让调用者按约定使用功能，减少对内部实现的依赖。","example":"查找接口接收数组、长度和目标值，并约定返回匹配下标。"},"concept:返回值约定":{"definition":"接口对返回结果含义的规定，包括正常结果、失败标记和有效范围。","purpose":"帮助调用者正确判断结果并处理失败情况。","example":"查找函数约定返回非负下标表示找到，返回−1表示不存在。"},"concept:参数传递语义":{"definition":"C函数按值传递参数；传入指针时复制地址，可通过它修改所指对象。","purpose":"判断函数能改变哪些数据，设计输出参数。","example":"void set(int *p){*p=9;}调用set(&x)可把x改为9。"},"concept:函数调用过程":{"definition":"计算实参并传给形参，执行函数体后返回调用处；实参求值顺序未指定。","purpose":"理解执行流转移、递归状态及返回后的继续位置。","example":"计算y=square(3)+1时，先取得函数返回值，再完成加法。"},"concept:成员选择语义":{"definition":"C中用点访问结构体或联合体成员，用箭头通过有效指针访问成员。","purpose":"准确读取或修改结点等复合对象中的字段。","example":"若p有效指向结构体s，则p->value与(*p).value访问同一成员。"},"concept:线性扫描":{"definition":"按某个次序逐项检查数据，最坏情况下需要检查全部n个元素。","purpose":"用于查找、计数或筛选，不要求数据预先有序。","example":"逐个检查一列温度并统计负数，最坏要查看每个数。"},"concept:原地更新":{"definition":"直接修改原有数据结构保存结果，通常只使用常数规模的额外辅助空间。","purpose":"减少复制和额外存储，但会改变原始数据。","example":"交换数组两端元素并向中间推进，可在原数组内完成逆序。"},"concept:特殊值约定":{"definition":"人为指定某个值表示空、失败或结束，必须明确其含义并避免与正常值冲突。","purpose":"统一表示特殊状态，让程序能够识别并处理。","example":"当合法下标均非负时，可约定−1表示尚未选中任何元素。"},"concept:汉诺塔":{"definition":"在柱之间搬移叠放圆盘的问题：一次只移最上一个，大盘不能压在小盘上。","purpose":"练习把整体任务分成规模更小、规则相同的子任务。","example":"搬动底部大盘前，必须先把它上面的盘移到其他位置。"},"concept:递归基例":{"definition":"规模已经足够小、可以直接处理而无需继续调用自身的情形。","purpose":"让递归能够停下，并为较大的子问题提供起点。","example":"求阶乘时可直接约定0的阶乘为1，避免继续向下调用。"},"concept:活动记录":{"definition":"一次尚未结束的函数调用需要保存的一组状态，通常含参数、局部值和返回位置。","purpose":"区分累计调用过多少次，与某一时刻同时保留多少层调用。","example":"甲调用乙时，甲还没结束；乙返回后甲要靠保存的状态继续。"},"concept:递归调用树":{"definition":"把每次递归调用画成一个结点，从调用者连到它发起的子调用所形成的树。","purpose":"分别观察总调用数量和一条尚未返回的调用链深度。","example":"某次调用先后发起两次子调用，图上有两个分支，但不代表两者同时执行。"},"concept:行编辑缓冲区":{"definition":"保存当前正在编辑的一行字符的空间；编辑命令会改变内容，而不一定作为正文保留。","purpose":"跟踪追加、删除行尾和整行清空后的实际文本。","example":"先输入ab，再删除末字符，缓冲区剩a。"},"concept:退格命令":{"definition":"在行尾编辑的约定下，删除当前最后一个字符的命令；具体符号与空行行为由题目规定。","purpose":"利用最后加入的字符先被删除这一栈式关系。","example":"若当前文本为cat，执行一次末尾退格后变成ca。"},"concept:操作序列":{"definition":"按时间先后列出的插入、删除等操作，以及每次操作所作用的一端或位置。","purpose":"核对给定输出能否由合法操作产生，而不只比较最终有哪些元素。","example":"先尾部加入甲，再头部取出甲，是两步不同的队列操作。"},"concept:环形回绕":{"definition":"数组下标到达末端后，按约定回到起点继续使用的循环寻址方式。","purpose":"复用前部已腾出的格子，同时保持队列的逻辑先后。","example":"四个格子编号0到3，索引从3再前进一步可回到0。"},"concept:假溢出":{"definition":"顺序队列的尾下标到达数组末端而拒绝入队，但前部实际上仍有空闲格子的情况。","purpose":"说明不回绕的顺序队列可能未充分复用已腾出的空间。","example":"队首元素已被取走，队尾却仍只能向数组后方增长。"},"concept:动态扩容":{"definition":"现有存储不足时取得更大的空间，并保留原有效数据、更新容量及相关位置。","purpose":"区分实际可用空间与仅被改大的容量数字。","example":"把一盒有效资料移入更大的盒子，不能只把旧盒标签写大。"},"concept:回溯":{"definition":"沿一个选择深入尝试，无路可走或分支处理完成时撤销相应状态，退回再尝试其他选择。","purpose":"用栈或递归保存尝试路径；首次找到的解不自动保证最短。","example":"迷宫遇到死路时退到上一个分叉口，换另一条路继续。"},"concept:同类项":{"definition":"变量及其指数部分相同的多项式项，系数可以不同。","purpose":"相加时把同类项的系数合并，避免把不同指数混在一起。","example":"3t²与5t²是同类项，而3t²与5t不是。"},"concept:零系数项":{"definition":"系数等于零的多项式项，对多项式的值没有贡献。","purpose":"采用只保存非零项的表示时，可省去这种项。","example":"某项合并后的系数变为零，就不必继续存储这一项。"},"concept:集合成员关系":{"definition":"判断某个值是否属于一组元素，关注存在与否，不直接规定重复次数或保存次序。","purpose":"把值是否满足条件，与结果序列怎样保留重复和顺序分开处理。","example":"在颜色集合{红,蓝}中，红属于该集合，绿不属于。"},"concept:共享对象":{"definition":"同一个对象被多个容器或引用共同持有，它们持有的是同一份对象，而非彼此独立的副本。","purpose":"修改或释放对象前，要考虑其他持有者是否仍在使用它。","example":"两份列表指向同一份文档时，从其中一份列表移除引用，不代表另一份也不再使用它。"},"concept:前缀函数":{"definition":"字符串前缀函数通常记作π：对每个位置，记录截至该位置的前缀所具有的最长相等真前缀、真后缀长度。这里的“真”表示不能取当前所考察的整个串。","purpose":"保存可复用的首尾匹配信息；这里的函数是字符串上的数学定义。","example":"在串cabca的最后位置，对应前缀的相等真首尾可取ca，最长长度为2。"},"concept:散列表容量":{"definition":"散列表中可供寻址的槽位总数，常记为m；它与当前已存记录数是不同的量。","purpose":"确定地址的有效范围，以及开放定址探测越过表尾时的回绕规则。","example":"容量为11、地址从0编号的散列表有槽0至10，即使只存四条记录，容量仍是11。"}},"digital":{"concept:二进制":{"definition":"只用0和1表示数的记数方法，整数部分每向左一位，位权扩大两倍。","purpose":"适合用电路的两种稳定状态表示和处理数据。","example":"二进制110表示一个四、一个二和零个一，即十进制六。"},"concept:八进制":{"definition":"只用0到7八个数字记数，逢八进一，每一位的位权都是八的整数次幂。","purpose":"可将二进制每三位一组，缩短数字的写法。","example":"八进制24表示两个八加四，等于十进制二十。"},"concept:十六进制":{"definition":"用0到9及A到F记数，字母依次代表十到十五，逢十六进一。","purpose":"便于紧凑地书写二进制数据，每位对应四位二进制。","example":"十六进制2C表示两个十六加十二，即十进制四十四。"},"concept:十进制":{"definition":"用0到9十个数字记数，逢十进一，相邻两位的位权相差十倍。","purpose":"便于日常读数、计算，以及解释电路处理的数值。","example":"十进制306表示三个百、零个十和六个一。"},"concept:位权":{"definition":"记数系统中某个位置所代表的单位大小，由基数和相对小数点的位置决定。","purpose":"将各位数字乘以位权再相加，可求出实际数值。","example":"二进制小数0.01中，末位的位权是四分之一。"},"concept:数制转换":{"definition":"把同一个数改用另一种进位制表示，改变的是写法，实际数值保持不变。","purpose":"连接日常十进制计算与电路中的二进制表示。","example":"十进制十四可转换为二进制1110或十六进制E。"},"concept:原码":{"definition":"一种有符号数编码，最高位表示正负，其余位按普通二进制表示绝对值。","purpose":"便于直观看出数的符号和大小，但加减处理较复杂。","example":"五位原码10110表示负六，其中1为符号，0110为大小。"},"concept:反码":{"definition":"可指逐位取反的码；作为有符号数编码时，正数同原码，负数将原码数值位取反。","purpose":"用于表示取反后的信号，也是一种有符号数表示法。","example":"码字0101逐位取反后为1010，每一位的0和1互换。"},"concept:补码":{"definition":"固定宽度的有符号编码：正数和零照常写，负数用绝对值的二进制逐位取反再加1，超宽进位丢弃。","purpose":"让加减共用加法器，零只有一种编码。","example":"5位中，3写作00011，取反加1得11101，表示-3。"},"concept:符号位":{"definition":"有符号数编码中用于指示正负的位，通常位于最高位，具体含义依编码规则确定。","purpose":"帮助判断数的正负，并参与有符号运算判断。","example":"六位补码100010的最高位为1，说明它表示负数。"},"concept:数值位":{"definition":"有符号数中除符号位外的位；其含义依编码而定，不一定直接表示绝对值。","purpose":"与符号位结合，按指定编码确定数的具体数值。","example":"五位原码00101的后四位0101直接表示大小五。"},"concept:无符号数":{"definition":"所有位都用于表示非负数值的二进制数，没有单独的符号位。","purpose":"用于表示数量、地址等不需要负数的数据。","example":"五位无符号数10000表示十六，最高位仍是普通数值位。"},"concept:有符号数":{"definition":"按约定编码表示正数、负数和零的数，常见编码包括原码、反码与补码。","purpose":"用于处理温差、位移等可能出现负值的数据。","example":"五位补码11000表示负八；解释位串前需明确采用的编码。"},"concept:溢出":{"definition":"运算的数学结果超出所用位数和编码能够表示的范围，截断结果不能代表真值。","purpose":"提示运算结果不可直接使用，需要扩位或作异常处理。","example":"三位无符号数七加二得到九，超出零到七的范围。"},"concept:BCD码":{"definition":"BCD全称二进制编码的十进制数，逐个编码十进制数字，常用四位表示一位。","purpose":"便于十进制数的显示与处理，避免整数字段转换。","example":"采用8421型BCD码时，十进制24写为0010 0100。"},"concept:8421码":{"definition":"一种有权BCD码，四位的权依次为8、4、2、1，用0000至1001表示十进制数字。","purpose":"按位权读取十进制数字，常用于计数器和数字显示。","example":"码字0101的位权和为四加一，因此表示十进制数字五。"},"concept:余三码":{"definition":"一种十进制数字编码，将每个十进制数字加三，再写成四位二进制，属于无权码。","purpose":"可简化某些十进制运算，其逐位取反具有补数关系。","example":"十进制数字二先加三得到五，所以余三码为0101。"},"concept:格雷码":{"definition":"按规定顺序排列时，相邻码字只有一位不同的编码，常见形式是标准反射格雷码。","purpose":"减少位置变化时多位同时翻转造成的读数歧义。","example":"两位反射格雷码顺序为00、01、11、10，相邻仅变一位。"},"concept:奇偶校验":{"definition":"添加校验位，使整个码字中1的个数保持为奇数或偶数，以检查传输或存储错误。","purpose":"检测奇数个位翻转；不能保证发现偶数位错或纠错。","example":"数据101含两个1，采用偶校验时可添加校验位0。"},"concept:逻辑电平":{"definition":"数字电路把规定的电压范围解释为高或低两种状态，范围由器件电气规范确定。","purpose":"将实际电压与逻辑状态对应，支持门电路传递信号。","example":"某输入端规定不低于2.2伏为高，则2.5伏可判为高电平。"},"concept:电压阈值":{"definition":"用于划分电平或触发状态变化的电压界限；保证识别的上下界之间可能有不确定区。","purpose":"判断信号能否可靠识别，并检查器件连接是否兼容。","example":"若低电平保证上限为0.7伏、高电平下限为1.8伏，1.2伏不保证。"},"concept:高电平":{"definition":"符合器件规定较高电压范围的物理状态；对应逻辑0还是1由正、负逻辑约定决定。","purpose":"描述信号的物理电压类别，与信号是否有效分开判断。","example":"某器件要求输入至少2.4伏为高，输入3.0伏符合高电平条件。"},"concept:低电平":{"definition":"符合器件规定较低电压范围的物理状态；对应逻辑0还是1由正、负逻辑约定决定。","purpose":"描述物理电压类别；具体有效作用还要看控制信号的约定。","example":"某器件允许输入不高于0.6伏为低，输入0.2伏符合低电平条件。"},"concept:逻辑函数":{"definition":"以逻辑变量为输入、以逻辑值为输出的确定关系，可用表达式或真值表描述。","purpose":"描述和设计电路的逻辑行为，并支持化简与实现。","example":"函数F＝AB表示与逻辑，只有A、B都为1时，F才为1。"},"concept:与运算":{"definition":"只有所有输入都为1时，输出才为1的逻辑运算，常用乘号或省略乘号表示。","purpose":"表示多个条件必须同时满足的控制关系。","example":"设备仅在电源正常且防护门关好时允许运行。"},"concept:或运算":{"definition":"只要至少一个输入为1，输出就为1；所有输入为0时输出才为0。","purpose":"表示任一条件满足即可触发的控制关系。","example":"烟感或温感任一个报警，都可启动警报灯。"},"concept:非运算":{"definition":"把一个逻辑值取反：输入为0时输出为1，输入为1时输出为0。","purpose":"产生相反逻辑信号，转换控制条件的极性。","example":"用非门将高电平故障信号变成低电平报警信号。"},"concept:异或":{"definition":"两个输入不同时输出1，相同时输出0的逻辑运算，符号为⊕。","purpose":"检测两位是否不同，也用于加法和奇偶校验。","example":"两位输入分别为0和1时，异或门输出为1。"},"concept:同或":{"definition":"两个输入相同时输出1，不同时输出0的逻辑运算，是异或结果取反。","purpose":"判断两位是否相同，用于构成相等比较电路。","example":"两位输入都为0时，同或门仍然输出1。"},"concept:与非":{"definition":"先对输入做与运算，再将结果取反；只有所有输入为1时输出才为0。","purpose":"实现条件否定，也可组合构成各种逻辑电路。","example":"二输入与非门接入1和0时，输出为1。"},"concept:或非":{"definition":"先对输入做或运算，再将结果取反；只有所有输入为0时输出才为1。","purpose":"检测所有条件均未成立，也可构成存储电路。","example":"两个故障信号均为0时，或非门输出正常指示。"},"concept:与或式":{"definition":"将若干与项通过或运算连接的逻辑表达式，与项由变量或其反变量相与组成。","purpose":"描述多种条件组合中任一种成立的逻辑。","example":"P′Q＋RS表示两组与条件的结果再相或。"},"concept:或与式":{"definition":"将若干或项通过与运算连接的逻辑表达式，或项由变量或其反变量相或组成。","purpose":"描述多组选择条件必须同时满足的逻辑。","example":"(P＋Q′)(R＋S)是两个或项相与的表达式。"},"concept:标准与或式":{"definition":"由最小项相或组成，每个最小项都包含全部变量，且每个变量恰好出现一次。","purpose":"把真值表中输出为1的情况统一写成表达式。","example":"二变量函数中的P′Q＋PQ是标准与或式。"},"concept:最小项":{"definition":"包含全部变量且各出现一次的与项，每个变量取原变量或反变量，仅对应一组输入为1。","purpose":"标记单个输入组合，建立标准与或表达式。","example":"与项P′QR只在PQR为011时取值为1。"},"concept:最大项":{"definition":"包含全部变量且各出现一次的或项，每个变量取原变量或反变量，仅对应一组输入为0。","purpose":"标记单个零值组合，建立标准或与表达式。","example":"或项P＋Q′＋R只在PQR为010时为0。"},"concept:卡诺图":{"definition":"按格雷码排列输入组合的逻辑图，相邻格只差一个变量，边界也可相邻。","purpose":"通过合并相邻格消去变量，直观化简逻辑。","example":"二变量图中，P′Q与PQ对应格可合并为Q。"},"concept:相邻项":{"definition":"同一组变量的两个最小项中，只有一个变量互为反变量，其余变量完全相同。","purpose":"识别可合并项，通过合并消去变化的变量。","example":"PQR与PQ′R相邻，二者相或可化为PR。"},"concept:反演规则":{"definition":"将式中与、或互换，0、1互换，各变量取反，并保持原有运算次序，可得反函数。","purpose":"从原表达式系统地写出输出取反后的表达式。","example":"G＝P＋QR，反演得到G′＝P′(Q′＋R′)。"},"concept:对偶规则":{"definition":"将逻辑式中的与、或互换，0、1互换，变量不取反，并保持原有运算次序。","purpose":"由已成立的逻辑恒等式得到对应的对偶恒等式。","example":"P＋0＝P的对偶式为P·1＝P。"},"concept:吸收律":{"definition":"一个逻辑项能吸收被其覆盖的附加项，如P＋PQ＝P及P(P＋Q)＝P。","purpose":"删除不会改变结果的部分，简化逻辑表达式。","example":"使能＋使能·请求可直接简化为使能。"},"concept:分配律":{"definition":"逻辑运算中，与可对或分配，或也可对与分配，展开时须保持对应关系。","purpose":"展开或提取表达式，便于化简及变换电路结构。","example":"P＋QR可展开为(P＋Q)(P＋R)。"},"concept:德摩根律":{"definition":"多个量相与后取反，等于各量取反后相或；相或后取反，等于各量取反后相与。","purpose":"转换取反表达式，便于使用与非门或或非门。","example":"(P＋Q＋R)′等于P′Q′R′。"},"concept:反函数":{"definition":"本课程中指逻辑函数逐组输入取反所得的函数，同一输入下输出总与原函数相反。","purpose":"表示互补输出，并帮助进行逻辑变换与设计。","example":"若某输入下G为0，则该输入下G′必为1。"},"concept:冗余项":{"definition":"加入或删除后不改变逻辑函数真值表的项，但可能影响实际电路的延迟和冒险。","purpose":"可用于简化表达式，或覆盖切换过程以抑制冒险。","example":"P＋PQ中的PQ是冗余项，删去后仍等于P。"},"concept:逻辑等价":{"definition":"两个逻辑表达式在所有输入组合下输出都相同，但实际电路的延迟可能不同。","purpose":"在保持逻辑功能的前提下，替换或简化电路。","example":"P⊕Q与P′Q＋PQ′具有相同的真值表。"},"concept:二极管":{"definition":"具有阳极和阴极的半导体器件，通常正向容易导通，反向在未击穿时基本截止。","purpose":"利用单向导电性实现整流、隔离或电流导向。","example":"在直流支路串联二极管，可阻断反方向电流。"},"concept:三极管":{"definition":"通常指双极型晶体管，具有基极、集电极和发射极，可工作于截止、放大或饱和区。","purpose":"用于放大信号，或通过截止和饱和实现开关控制。","example":"用NPN型三极管作低端开关，控制小灯亮灭。"},"concept:MOS管":{"definition":"MOS管全称金属氧化物半导体场效应晶体管，用栅源电压控制导电。","purpose":"在数字电路中充当开关，组成各种逻辑门。","example":"存储单元可用MOS管控制数据线与内部节点的连接。"},"concept:NMOS":{"definition":"NMOS是N沟道金属氧化物半导体场效应晶体管，增强型在栅源电压足够高时导通。","purpose":"常用于逻辑电路的下拉通路，把节点拉低。","example":"源极接地的增强型NMOS，可由高电平控制点亮指示灯。"},"concept:PMOS":{"definition":"PMOS是P沟道金属氧化物半导体场效应晶体管，增强型在栅极比源极足够低时导通。","purpose":"常用于逻辑电路的上拉通路，把节点拉高。","example":"源极接电源的增强型PMOS，可用较低栅压接通负载。"},"concept:CMOS":{"definition":"CMOS全称互补金属氧化物半导体，利用N沟道与P沟道MOS管配合实现逻辑。","purpose":"构建静态功耗较低、集成度较高的数字电路。","example":"手机处理器中的大量逻辑门采用CMOS工艺制造。"},"concept:TTL":{"definition":"TTL全称晶体管—晶体管逻辑，主要用双极型晶体管完成逻辑运算和输出驱动。","purpose":"构成数字逻辑门，用于控制与接口电路。","example":"标准TTL系列中的7400芯片提供四个二输入与非门。"},"concept:高阻态":{"definition":"高阻态是输出驱动近似断开的状态，节点电平由外部电路决定，并非逻辑高或低。","purpose":"释放共享线路，让其他器件接管信号。","example":"存储器未被选中时，数据输出可呈高阻态，避免争用。"},"concept:三态门":{"definition":"三态门带有使能控制，输出除正常的高、低电平外，还能进入高阻态。","purpose":"控制器件何时驱动线路，方便共享总线。","example":"两个数据源分时使用同一总线，各自通过三态门接入。"},"concept:开漏":{"definition":"开漏是漏极作为输出、内部只能主动拉低的结构，关断时不主动提供高电平。","purpose":"配合上拉实现共享信号线及合适的电平接口。","example":"多个传感器可用开漏报警脚共线，任一个都能拉低线路。"},"concept:开集电极":{"definition":"开集电极是集电极作为输出、内部只能主动拉低的结构，高电平通常靠外接上拉。","purpose":"便于连接外部负载，或组合多个低有效信号。","example":"开集电极比较器输出接上拉电阻后，可供逻辑输入读取。"},"concept:线与":{"definition":"线与指多个开漏或开集电极输出共线上拉，在正逻辑下形成与关系，任一拉低则为低。","purpose":"合并多个器件的状态，节省逻辑门和连线。","example":"多个就绪输出共线上拉，全部释放线路时才表示均已就绪。"},"concept:扇入":{"definition":"扇入是一个逻辑门具有的输入端数量，描述该门一次可接收多少路逻辑信号。","purpose":"衡量门的输入规模，帮助选择逻辑器件。","example":"一个三输入或门的扇入为三，可接收三路条件信号。"},"concept:扇出":{"definition":"扇出是输出在规定电平与时序条件下，能可靠驱动的指定类型负载输入数量。","purpose":"判断驱动能力，决定是否需要增加缓冲器。","example":"一根控制线要连接许多芯片时，需核对电流和电容负载。"},"concept:噪声容限":{"definition":"噪声容限是输出保证电平与接收判定界限之间的余量，分高、低电平两种。","purpose":"衡量信号允许叠加多大干扰仍能可靠识别。","example":"低态输出最高为0.3伏、接收低态上限为0.8伏，余量为0.5伏。"},"concept:灌电流":{"definition":"灌电流是从外部流入器件输出端的常规电流，常见于输出拉低并向地导通时。","purpose":"衡量低电平输出承受外部电流的能力。","example":"发光二极管经限流电阻接电源，输出拉低时吸收其电流。"},"concept:拉电流":{"definition":"拉电流是由器件输出端向外部负载提供的常规电流，常见于输出驱动高电平时。","purpose":"衡量高电平输出向负载供电流的能力。","example":"输出高电平经限流电阻驱动接地的发光二极管时提供拉电流。"},"concept:负载电容":{"definition":"负载电容是输出端所见的总等效电容，通常包含接收端输入、连线和寄生电容。","purpose":"用于估计信号边沿速度、延迟与动态功耗。","example":"同一输出接入更多芯片输入，通常会增加总负载电容。"},"concept:传输延迟":{"definition":"传输延迟是输入变化到相应输出变化之间的时间，通常按指定电压参考点测量。","purpose":"计算信号经过逻辑电路的时间，检查时序。","example":"脉冲经过三级缓冲器，各级延迟共同影响最终输出时刻。"},"concept:上升时间":{"definition":"上升时间是信号从规定低电压升到规定高电压所需时间，常按幅度的10%至90%测量。","purpose":"评价上升边沿快慢，检查接口时序要求。","example":"开漏线路保持电阻不变而增大电容时，上升过程通常变慢。"},"concept:下降时间":{"definition":"下降时间是信号从规定高电压降到规定低电压所需时间，常按幅度的90%至10%测量。","purpose":"评价下降边沿快慢，判断信号质量与时序。","example":"驱动器下拉能力不足时，较大的负载电容会拖慢下降边沿。"},"concept:动态冒险":{"definition":"动态冒险是输出本应只翻转一次，却因不同路径延迟而在稳定前多次翻转的现象。","purpose":"帮助识别瞬态错误，避免毛刺触发后级。","example":"输出应从低变高，却短暂经历低、高、低、高的变化。"},"concept:上拉电阻":{"definition":"上拉电阻把信号节点经电阻连接到正电源，在没有主动拉低时使其趋向高电平。","purpose":"设定默认高电平，并限制拉低时的电流。","example":"按键输入用电阻接电源、按键接地，松开时读到高电平。"},"concept:下拉电阻":{"definition":"下拉电阻把信号节点经电阻连接到地，在没有主动拉高时使其趋向低电平。","purpose":"设定默认低电平，减少输入悬空造成的不确定。","example":"按键输入用电阻接地、按键接电源，松开时读到低电平。"},"concept:编码器":{"definition":"编码器把有效输入的位置转换为较少位的代码，多输入同时有效时须有明确处理规则。","purpose":"压缩输入位置信息，便于传输和后续处理。","example":"四个按键接四线—二线编码器，单键有效时输出对应编号。"},"concept:译码器":{"definition":"译码器将输入代码转换为对应输出的有效状态，具体结果取决于使能和有效电平约定。","purpose":"把二进制地址转换为选择信号，控制目标器件。","example":"二线—四线译码器可按两位地址选通四个存储模块之一。"},"concept:优先编码":{"definition":"多个输入同时有效时，只把优先级最高的一路转换成对应编码。","purpose":"解决多个请求并存时的编码选择问题。","example":"报警器同时收到两路报警，先编码等级较高的一路。"},"concept:数据选择器":{"definition":"按选择地址，从多路数据中选一路送到输出的组合电路。","purpose":"让多路信号共用一个数据出口。","example":"四路传感器接入四选一器件，地址指定当前读取哪路。"},"concept:多路选择器":{"definition":"数据选择器的另一名称，用选择信号控制哪路输入接到输出。","purpose":"切换数据来源，也可实现逻辑函数。","example":"两选一器件按控制位，在正常数据和测试数据之间切换。"},"concept:数据分配器":{"definition":"把一路输入数据送到选中的某一路输出，英文常写DEMUX；未选输出的行为由器件约定。","purpose":"把一路数据送往指定目的通道，与多路选一路的选择器区分。","example":"分配器可依选择码，把一条数据线送到不同接收通道。"},"concept:半加器":{"definition":"把两个一位二进制数相加，输出和位与进位，不接收低位进位。","purpose":"实现不带输入进位的一位加法。","example":"两位输入分别为零和一时，和位为一，进位为零。"},"concept:全加器":{"definition":"把两个一位二进制数及低位进位相加，输出本位和与高位进位。","purpose":"作为多位二进制加法器的基本单元。","example":"三个输入全为一时，本位和为一，并向高位进一。"},"concept:串行进位":{"definition":"多位加法中，各位进位依次传给相邻高位的进位组织方式。","purpose":"用简单连接实现多位二进制加法。","example":"八位加法器中，低位产生的进位可能逐级传到最高位。"},"concept:超前进位":{"definition":"根据各位产生和传递进位的条件，直接计算多个进位的方式。","purpose":"减少逐级等待进位造成的加法延迟。","example":"四位一组的电路并行算出组内进位，再供各位求和。"},"concept:比较器":{"definition":"比较两个数字大小，给出大于、等于或小于关系的组合电路。","purpose":"为排序、判断和数据选择提供条件。","example":"无符号数比较器比较三与五，小于关系输出有效。"},"concept:加法器":{"definition":"完成二进制加法的电路，按设计输出指定位数的和及进位。","purpose":"用于算术运算、计数和地址计算。","example":"三位加法器计算二加三，和输出为二进制一零一。"},"concept:减法器":{"definition":"完成二进制减法的电路，可输出差，并按接口给出借位。","purpose":"用于求差、距离计算和算术运算。","example":"三位无符号减法器计算六减二，差输出为一零零。"},"concept:七段显示":{"definition":"用七条可独立点亮的发光段，组合显示数字及部分字符。","purpose":"以较少显示单元直观呈现数字。","example":"电子钟点亮适当的发光段，组成当前小时和分钟。"},"concept:译码输出":{"definition":"译码器根据输入编码产生的输出，常以某一路有效表示对应码。","purpose":"将编码转换成选通或控制信号。","example":"二线四线译码器收到零一码，使对应的一号输出有效。"},"concept:使能端":{"definition":"控制器件是否执行正常功能的输入端，有效电平由器件规定。","purpose":"控制模块工作，并便于组合扩展。","example":"低有效使能端接低电平后，译码器才按输入码选通输出。"},"concept:级联":{"definition":"把前级电路输出连接到后级输入，使多个模块协同工作。","purpose":"扩展处理位数、规模或功能。","example":"两个四位比较器级联，可比较两个八位数的大小。"},"concept:进位":{"definition":"二进制某位相加达到二时，向相邻高位传递的数值一。","purpose":"把本位容纳不下的数值计入高位。","example":"二进制一零加一零，个位无进位，十位向更高位进一。"},"concept:借位":{"definition":"二进制某位减法不够减时，从相邻高位借一，折合本位的二。","purpose":"使低位不足时仍能完成多位减法。","example":"二进制一零零减零零一，借位逐级传递，得到零一一。"},"concept:锁存器":{"definition":"能保存一位状态的电路，受控型通常在有效电平期间允许更新。","purpose":"暂存数据，并在保持条件下维持状态。","example":"控制信号关闭后，锁存器继续保存此前接收的一位数据。"},"concept:SR锁存器":{"definition":"置位—复位锁存器，由置位端S和复位端R控制，禁用组合依结构而定。","purpose":"保存可分别置一、清零的一位状态。","example":"报警信号置位后，即使信号消失，仍保持报警直到复位。"},"concept:D锁存器":{"definition":"数据锁存器，使能有效期间输出跟随数据端D，无效时保持原值。","purpose":"在指定电平窗口接收并保存数据。","example":"低电平透明型号在使能变高后，保持关闭前的数据。"},"concept:D触发器":{"definition":"数据触发器，满足时序要求时，在有效时钟沿采样D并保存。","purpose":"构成同步寄存器，按时钟更新数据。","example":"下降沿型号在下降沿采到一后，保持一至下一次更新。"},"concept:JK触发器":{"definition":"J、K为控制端：零零保持、一零置位、零一复位、一一翻转。","purpose":"用于构成计数器及状态控制电路。","example":"边沿型器件的J、K都接一时，每个有效时钟沿翻转一次。"},"concept:T触发器":{"definition":"翻转触发器，T为翻转控制端；有效触发时T为一则翻转，为零则保持。","purpose":"用于二进制计数及频率分频。","example":"边沿型器件的T恒为一时，输出频率为时钟频率的一半。"},"concept:主从触发器":{"definition":"由主、从两级存储单元组成，两级在不同的时钟电平阶段交替工作。","purpose":"分开接收和输出更新，限制状态传递。","example":"一种结构在高电平阶段由主级接收，转低后从级接收主级状态。"},"concept:边沿触发":{"definition":"只在指定时钟跳变沿采样输入并更新存储状态的触发方式。","purpose":"让状态按统一时刻更新，便于设计同步电路。","example":"下降沿触发的寄存器可在每次时钟下降时装入数据。"},"concept:电平敏感":{"definition":"在控制信号处于指定电平期间，电路持续响应输入的工作方式。","purpose":"允许锁存器在有效期间传递并保存数据。","example":"低电平透明锁存器在使能为低时，输出随数据变化。"},"concept:特性方程":{"definition":"描述某类触发器的次态与现态、输入之间关系的逻辑表达式。","purpose":"计算触发器在有效触发条件下的新状态。","example":"T触发器满足时序要求时，次态等于现态与T异或。"},"concept:激励方程":{"definition":"表示触发器各输入端信号如何由电路现态和外部输入产生的方程。","purpose":"确定驱动逻辑，并用于推导电路次态。","example":"某计数电路把低位输出接到高位T端，写作T₁＝Q₀。"},"concept:特性表":{"definition":"列出触发器各种输入、现态所对应次态的表，须注明触发条件。","purpose":"查明触发器在不同输入下如何更新状态。","example":"T触发器的表中，T为0对应保持，T为1对应取反。"},"concept:激励表":{"definition":"按现态与目标次态，列出触发器所需输入及可任选输入值的表。","purpose":"从期望状态变化反推触发器输入条件。","example":"要求T触发器从1变成0时，可由激励表查出T应为1。"},"concept:建立时间":{"definition":"为可靠采样，数据在有效时钟沿到来前必须连续稳定的最短时间。","purpose":"为采样留出准备时间，降低采样出错风险。","example":"若建立时间为2纳秒，数据应至少提前2纳秒稳定。"},"concept:保持时间":{"definition":"为可靠采样，数据在有效时钟沿到来后必须继续稳定的最短时间。","purpose":"避免数据过早改变，干扰正在进行的采样。","example":"若保持时间为1纳秒，采样沿后这1纳秒内数据不能变。"},"concept:异步复位":{"definition":"复位信号有效时，无须等待有效时钟沿就能使存储状态复位。","purpose":"在没有时钟时也能把电路置于规定初态。","example":"低有效复位端被拉低后，寄存器经传播延迟清零。"},"concept:同步复位":{"definition":"复位信号满足时序要求时，在有效时钟沿才使存储状态复位。","purpose":"把复位操作纳入统一时钟，便于时序设计。","example":"计数器的复位信号持续有效，到下个有效沿才归零。"},"concept:时钟边沿":{"definition":"时钟信号在低、高电平之间跳变的时刻，分为上升沿和下降沿。","purpose":"为触发器采样和状态更新提供时间基准。","example":"一个完整时钟周期通常包含一次上升沿和一次下降沿。"},"concept:上升沿":{"definition":"数字信号由较低电平向较高电平变化的边沿，数据、控制或时钟信号都可以有上升沿；计时点以规定的电平交点为准。","purpose":"识别信号的变化方向和测量事件；是否触发采样或状态更新，还要看电路规定。","example":"使能信号从0变到1也有上升沿，即使这根线并不是时钟。"},"concept:下降沿":{"definition":"数字信号由较高电平向较低电平变化的边沿，数据、控制或时钟信号都可以有下降沿；计时点以规定的电平交点为准。","purpose":"识别由高变低的过程与测量事件；不能仅因出现下降沿，就认定电路会触发或采样。","example":"低有效复位线由1拉到0时出现下降沿；这首先说明复位输入发生了变化。"},"concept:翻转":{"definition":"一位逻辑状态由0变1或由1变0，即更新为原状态的反值。","purpose":"实现二进制计数、分频和交替控制。","example":"某状态位初始为1，连续翻转两次后又回到1。"},"concept:现态":{"definition":"分析某次状态更新时，电路在该次更新之前已有的存储状态。","purpose":"与当前输入一起确定后续状态及相关输出。","example":"计数器本次更新前为011，分析此次更新时它就是现态。"},"concept:次态":{"definition":"根据现态、输入和更新规则，电路在下一次状态更新后进入的状态。","purpose":"描述未来状态，指导时序电路逻辑设计。","example":"模五计数器现态为3，正常加一时的次态为4。"},"concept:状态方程":{"definition":"用现态变量和外部输入表示整个时序电路各状态变量次态的方程。","purpose":"分析电路演变规律，确定下一步存储内容。","example":"两位循环计数器可用两个次态方程共同描述计数顺序。"},"concept:状态转换":{"definition":"电路在规定输入和触发条件作用下，从一个状态进入另一个状态。","purpose":"描述控制流程如何随事件或时钟推进。","example":"售货控制器收到足额付款后，从等待状态进入出货状态。"},"concept:状态表":{"definition":"按现态和输入列出次态，并按电路类型列出相应输出的表格。","purpose":"完整整理状态行为，便于分析与逻辑实现。","example":"门禁状态表可列出锁定状态收到正确密码后的状态和输出。"},"concept:状态图":{"definition":"用节点表示状态、带方向的连线表示转换，并标注条件和有关输出。","purpose":"直观看清控制流程、分支条件和循环关系。","example":"交通灯状态图可用三个节点表示红灯、绿灯和黄灯阶段。"},"concept:状态编码":{"definition":"给每个抽象状态分配不同的二进制码，使其能由存储元件表示。","purpose":"把控制流程转换成可实现的硬件逻辑。","example":"三个工作状态可分别编码为00、01、10，剩余码另作处理。"},"concept:状态化简":{"definition":"在保持规定输入下输出行为不变的前提下，合并等价状态的过程。","purpose":"减少状态数量，可能降低存储和逻辑开销。","example":"两个等待状态若对所有后续输入表现相同，就可合并。"},"concept:等价状态":{"definition":"从两个状态出发，对任意允许的后续输入序列都产生相同输出序列。","purpose":"判断状态能否合并，是状态化简的依据。","example":"两个状态遇到0都输出0并回自身，遇到1都输出1并进入同一状态。"},"concept:可达状态":{"definition":"从规定初始状态出发，经过某个允许输入序列和状态更新能够到达的状态。","purpose":"识别实际可能出现的状态，辅助验证与优化。","example":"复位到00且只在00与01间交替的电路中，01是可达状态。"},"concept:不可达状态":{"definition":"从指定初态出发，在所有允许输入下都无法到达的状态。","purpose":"帮助分析状态范围，简化状态机及其逻辑。","example":"某电路复位后只在00与01间切换，10便不可达。"},"concept:初态":{"definition":"分析开始时电路各存储位的取值，不一定都是零。","purpose":"确定后续状态变化的起点，避免推演歧义。","example":"两位寄存器开始存有10，则本次分析的初态为10。"},"concept:非法状态":{"definition":"设计规定不应作为正常工作状态的编码，可能因干扰进入。","purpose":"识别异常状态，设计恢复路径或故障提示。","example":"十进制计数器用四位编码时，1100属于非法状态。"},"concept:输出方程":{"definition":"用逻辑表达式描述输出与当前状态、输入之间的关系。","purpose":"确定各条件下的输出，并据此实现输出电路。","example":"令状态位为A、输入为B，输出方程可写作Y=A与B。"},"concept:Mealy":{"definition":"米利型状态机，输出由当前状态和当前输入共同决定。","purpose":"让输出直接响应输入变化，可减少所需状态。","example":"售货机根据已收金额和本次投币信号决定是否出货。"},"concept:Moore":{"definition":"摩尔型状态机，输出只由当前状态决定，不直接依赖输入。","purpose":"将输出绑定状态，便于安排控制过程。","example":"交通灯控制器处于绿灯状态时，绿灯输出保持有效。"},"concept:同步计数器":{"definition":"所有计数触发器共用同一时钟，并在同一有效沿更新。","purpose":"减少逐级时钟传播造成的累计延迟。","example":"三位同步加法计数器用低位状态决定高位是否翻转。"},"concept:异步计数器":{"definition":"计数触发器不全由同一时钟沿驱动，常由前级输出触发后级。","purpose":"用较简单的连接实现计数和逐级分频。","example":"三级二进制脉动计数器中，后一级时钟来自前一级输出。"},"concept:模计数器":{"definition":"按固定顺序循环经过M个不同状态的计数器，模数就是M。","purpose":"实现每M次输入脉冲重复一次的计数循环。","example":"计数状态按0、1、2、0循环，构成模3计数器。"},"concept:自启动":{"definition":"无需额外复位，从任意可能初态都能在有限步内进入合法循环。","purpose":"避免电路因上电落入未用状态而停止正常工作。","example":"某计数器的全部未用状态下一拍均转入正常计数环。"},"concept:自恢复":{"definition":"电路因干扰进入异常状态后，能自行返回正常工作状态集合。","purpose":"提高抗干扰能力，减少人工复位的需要。","example":"控制器检测到未分配编码后，下一拍自动进入待机态。"},"concept:分频器":{"definition":"将周期输入信号变成较低频率输出信号的电路。","purpose":"从较快时钟获得计时或控制所需的较慢节拍。","example":"输入时钟为12千赫，三分频后输出频率为4千赫。"},"concept:寄存器":{"definition":"由若干存储位组成，按控制条件保存或更新一组二进制数据。","purpose":"暂存数据，使数据能在不同操作阶段之间传递。","example":"八位寄存器装入一个字节后，可保持它供后续运算。"},"concept:移位寄存器":{"definition":"在控制信号作用下，每次有效时钟将各位数据移动一个位置。","purpose":"实现数据移位、串并转换和一定拍数的延迟。","example":"三位右移寄存器原为101，左端补0后变为010。"},"concept:环形计数器":{"definition":"把末级输出接回首级输入，通过循环移位形成状态循环的计数器。","purpose":"产生依次有效的节拍，便于顺序控制。","example":"四位一位有效环形计数器可依次输出四路轮流选通信号。"},"concept:扭环计数器":{"definition":"又称约翰逊计数器，将末级反相输出反馈到首级输入。","purpose":"用较少触发器产生多个易于译码的顺序状态。","example":"三位扭环计数器从全零初始化后，正常循环包含六个状态。"},"concept:串行输入":{"definition":"通过一条数据通路，按规定时序逐位送入一组二进制数据。","purpose":"减少数据连线，配合寄存器完成逐位接收。","example":"发送端连续四拍送出1、1、0、1，接收端每拍取一位。"},"concept:并行输出":{"definition":"通过多条输出线同时提供一组数据，各条线对应不同数据位。","purpose":"让后级一次读取多位数据，方便并行处理。","example":"四位寄存器用四个输出端，同时给出所存数据1011。"},"concept:反馈":{"definition":"将电路输出或内部状态送回输入侧，影响后续电路行为。","purpose":"构成存储、计数或状态控制所需的闭合逻辑。","example":"把寄存器某两位异或后送回串行端，可生成特定序列。"},"concept:序列检测":{"definition":"逐位检查输入数据流，判断是否出现预先指定的比特排列。","purpose":"识别数据标记或控制码，并产生检测信号。","example":"检测器连续收到110三位时，产生一次匹配提示。"},"concept:重叠检测":{"definition":"允许相邻两次匹配共用部分输入位的序列检测方式。","purpose":"保留可继续匹配的信息，避免漏掉紧接的目标串。","example":"目标为101时，输入10101中的两次匹配共用中间的1。"},"concept:占空比":{"definition":"周期脉冲中，高电平持续时间占整个周期的比例。","purpose":"描述脉冲宽窄，用于评估控制和驱动效果。","example":"周期10毫秒、高电平3毫秒的脉冲，占空比为30%。"},"concept:频率":{"definition":"周期信号每秒重复的周期数，单位赫兹，与周期互为倒数。","purpose":"衡量信号重复快慢，计算时钟和计数节拍。","example":"某信号每隔1毫秒重复一次，其频率就是1千赫。"},"concept:单稳态":{"definition":"只有一个稳定状态，触发后暂入另一状态，随后自动返回。","purpose":"将触发事件转换为一定宽度的脉冲。","example":"按键触发单稳态电路后，指示灯亮约一秒再自动熄灭。"},"concept:多谐振荡":{"definition":"电路依靠内部反馈和延时反复翻转，自行产生周期脉冲，没有可永久保持的稳定状态。","purpose":"提供时钟、闪烁控制或周期性触发信号。","example":"两只晶体管交替导通，让两盏小灯轮流闪亮。"},"concept:施密特触发":{"definition":"输入上升和下降时采用不同翻转阈值，两阈值之间的输出保留先前状态。","purpose":"抑制噪声引起的反复翻转，整形成清晰边沿。","example":"缓慢变化的传感器电压经它转换成干净方波。"},"concept:555":{"definition":"555是一类定时器芯片的型号，内部含比较器、锁存器和放电开关，并非英文缩写。","purpose":"配合电阻、电容实现延时或产生脉冲。","example":"按下按钮后，小灯亮一小段时间再自动熄灭。"},"concept:阈值电压":{"definition":"用于判断输入或触发状态变化的电压界限，具体数值由器件和工作条件决定。","purpose":"确定信号何时被识别或使电路翻转。","example":"温控电路在传感电压越过设定界限时启动风扇。"},"concept:充电":{"definition":"电荷经电流逐渐积累到电容上的过程，电容电压变化取决于电流方向和大小。","purpose":"建立电压变化过程，实现延时和波形控制。","example":"电容通过电阻接直流电源，电压逐渐接近电源电压。"},"concept:放电":{"definition":"电容通过外部通路释放储存电荷的过程，其电压通常逐渐接近通路的最终电压。","purpose":"释放储能、复位定时过程或改变信号电平。","example":"断开电源后，电容通过泄放电阻逐渐失去储能。"},"concept:时间常数":{"definition":"描述一阶电路变化快慢的参数，电阻电容电路中等于电容所见等效电阻乘电容。","purpose":"估计充放电速度、延时和信号边沿快慢。","example":"电容不变而等效电阻加倍，时间常数也加倍。"},"concept:积分电路":{"definition":"输出近似对应输入随时间累积的电路；简单电阻电容电路只在适当条件下近似积分。","purpose":"平滑快速变化的信号，或形成缓慢变化的波形。","example":"短脉冲串经积分电路后，可形成较平滑的电压。"},"concept:微分电路":{"definition":"输出近似反映输入变化快慢的电路；简单电阻电容电路只在适当条件下近似微分。","purpose":"突出信号边沿，产生短促的触发脉冲。","example":"矩形信号经微分电路，在上升沿和下降沿形成反向尖脉冲。"},"concept:二值抽象":{"definition":"把符合规定电压范围的实际信号归为逻辑零或一，忽略范围内的具体电压差别。","purpose":"用两种逻辑值分析复杂电路的功能。","example":"两次测得的电压虽不同，落在同一合法区间便记作同一逻辑值。"},"concept:电压区间判定":{"definition":"依据器件规定的高低电平输入范围判断逻辑值，中间未保证区不能随意判为零或一。","purpose":"检查输入是否满足器件的电平要求。","example":"某输入落在高低电平保证范围之间，便不能保证识别结果。"},"concept:逻辑极性":{"definition":"正、负逻辑约定物理高低电平如何记为0和1；有效极性另规定哪种电平表示信号起作用，两者需分别说明。","purpose":"先解释逻辑值，再按信号用途判断有效含义，避免混淆编码与作用。","example":"控制端低电平时执行复位，说明它低有效，不能单凭此认定整套电路采用负逻辑。"},"concept:进位规则":{"definition":"某一数位累计达到该进制的基数时，向相邻高位进一，本位保留除后的余数。","purpose":"完成不同进制数的计数与算术运算。","example":"八进制最低位原为七，再加一便向高位进一。"},"concept:定宽表示":{"definition":"用预先规定长度的位串表示数据，可固定整段或其中一个字段；数值解释还须约定符号、小数点位置等规则。","purpose":"明确实际保留的位数，以及哪些数值能在该字段中表示。","example":"用六位无符号整数表示五时可写为000101，前面补零。"},"concept:编码约束":{"definition":"给对象分配代码时必须满足的条件，如位数固定、代码互异或相邻代码只变一位。","purpose":"保证对象可区分，并满足电路实现要求。","example":"四种互斥模式可分别约定为00、01、10、11。"},"concept:布尔代数":{"definition":"研究取零或一的逻辑变量及其运算规律的代数，常用运算包括与、或、非。","purpose":"描述、推导和化简数字电路的逻辑功能。","example":"用吸收律可把“甲或甲与乙”化简成“甲”。"},"concept:输入组合":{"definition":"在同一时刻给各个逻辑输入分别指定零或一所形成的一组取值，须明确变量顺序。","purpose":"逐项检查真值表和电路的各种输入情况。","example":"三个开关依次取开、关、开，可记录为组合101。"},"concept:逻辑化简":{"definition":"在规定输入范围内保持逻辑功能等价，减少表达式中的项、变量或实现成本。","purpose":"降低电路复杂度，并可能改善面积和延迟。","example":"提取共同条件，可将两条重复的控制支路合并。"},"concept:覆盖关系":{"definition":"一个逻辑项覆盖某输入组合，是指该组合使该项为一；多个项可共同覆盖函数的一值情况。","purpose":"检查化简是否遗漏所需情况或包含错误情况。","example":"逻辑项A与B覆盖所有A、B均为一的组合，与其他变量无关。"},"concept:稳态与瞬态":{"definition":"稳态是输入稳定且传播影响消退后的状态；瞬态是输入变化后电路尚在响应的过程。","purpose":"区分最终逻辑结果和变化期间的短暂现象。","example":"译码器切换地址时，输出可能短暂波动，随后稳定。"},"concept:信号传播路径":{"definition":"信号从输入出发，经连线和各级器件到达目标端的路线，每段都会引入传播延迟。","purpose":"分析响应时间、时序限制及毛刺形成原因。","example":"同一信号经一级门和三级门到达两处，抵达时间可能不同。"},"concept:驱动与负载":{"definition":"驱动端提供或吸收电流，负载则提出电流和电容需求，两者须满足电平与时序要求。","purpose":"判断输出能否可靠带动所连接的电路。","example":"一个门连接更多输入端后，负载增大，边沿可能变慢。"},"concept:开关状态":{"definition":"晶体管在数字电路中常近似看作导通或截止的开关，实际切换还存在过渡过程。","purpose":"理解逻辑门如何建立或切断电流通路。","example":"反相器输入改变时，上拉和下拉晶体管交替承担导通作用。"},"concept:电荷充放电":{"definition":"电容通过电流获得或释放电荷，使节点电压随时间变化；速度受电容和驱动能力影响。","purpose":"解释数字信号边沿、传播延迟和动态功耗。","example":"同样的驱动电流给更大的电容升高相同电压，需要更久。"},"concept:使能控制":{"definition":"用控制信号决定器件是否执行功能；有效电平由器件规定。","purpose":"控制数据通路何时工作，协调共享资源。","example":"存储器仅在片选有效时响应读写请求。"},"concept:组合逻辑映射":{"definition":"在稳态下，输出仅由当前输入组合决定，不依赖历史状态。","purpose":"把规定的输入输出对应关系实现为电路。","example":"温度报警电路将两个超温信号取或后输出。"},"concept:信息编码与选择":{"definition":"编码用码字表示信息，选择则按控制码接通指定的数据通路。","purpose":"便于信息表示、传送和多路数据调度。","example":"四路数据选择器按两位选择码接通一路输入。"},"concept:算术逻辑关系":{"definition":"用布尔运算描述二进制算术中各输入位与结果位的关系。","purpose":"据此设计加法、减法和数值比较电路。","example":"一位全加器把两个加数位与进位共同相加。"},"concept:存储功能":{"definition":"电路能够保存先前写入的信息，并在规定条件下更新或清除。","purpose":"记录数据或历史状态，供后续操作使用。","example":"寄存器在有效时钟沿装入数据，随后保持。"},"concept:反馈与保持":{"definition":"将输出送回输入形成反馈，合适结构可维持稳定的逻辑状态。","purpose":"构成能在无新写入时保留数据的电路。","example":"两个反相器首尾相接，可形成两种稳定状态。"},"concept:采样时刻":{"definition":"存储器件按控制信号接收输入的时机，可为有效电平区间或边沿。","purpose":"判断输入变化何时能够影响存储结果。","example":"下降沿触发器在时钟由高变低时接收数据。"},"concept:输入激励":{"definition":"为使时序电路从当前状态转到目标状态，需要施加的输入条件。","purpose":"根据所需状态变化确定触发器输入。","example":"要让D触发器下一拍置零，可令其D端为零。"},"concept:状态演化":{"definition":"时序电路的内部状态随输入和有效时钟事件逐步变化的过程。","purpose":"分析电路运行轨迹及各时刻的行为。","example":"控制器收到启动信号后，由等待转入执行状态。"},"concept:状态转移条件":{"definition":"促使电路由当前状态进入某个下一状态的输入与时序条件。","purpose":"明确状态图中各条转移路径何时发生。","example":"售货机在累计金额足够且确认有效时进入出货态。"},"concept:状态可区分性":{"definition":"若存在相同的后续输入序列，使两个状态产生不同输出，则可区分。","purpose":"判断状态能否合并，帮助简化状态机。","example":"两状态在下一次输入零时分别输出零和一。"},"concept:状态编码位宽":{"definition":"表示状态码所用的二进制位数，取决于状态数量及编码方式。","purpose":"确定状态寄存器所需的存储位数量。","example":"八个状态采用紧凑二进制编码时需要三位。"},"concept:输出与状态关系":{"definition":"时序电路的输出可仅取决于当前状态，也可同时取决于当前输入。","purpose":"确定输出逻辑，分析输出的变化时机。","example":"控制器处于报警态时，持续输出有效报警信号。"},"concept:计数循环":{"definition":"计数器按规定次序更新状态，到循环末态后重新回到起始状态。","purpose":"实现周期计数、定时及循环步骤控制。","example":"模六计数器依次经过零至五，再回到零。"},"concept:复位后状态":{"definition":"复位操作使存储单元或状态机进入的预定状态，不一定全为零。","purpose":"建立确定起点，避免启动时状态不明。","example":"控制器复位后进入等待态，暂不执行任务。"},"concept:非法状态恢复":{"definition":"电路进入设计规定之外的状态后，按预设逻辑返回合法状态。","purpose":"避免异常状态导致停滞或错误循环。","example":"交通灯控制器检测到非法码后转入全红态。"},"concept:分频关系":{"definition":"输出周期与输入周期的比例；整数分频使输出频率按整数倍降低。","purpose":"从较快时钟产生较慢的周期信号。","example":"十分频电路把一千赫兹时钟变成一百赫兹。"},"concept:串行数据历史":{"definition":"按时间先后采入的数据序列，电路可保存其全部或相关特征。","purpose":"依据过去输入完成检测、校验和控制。","example":"三位移位寄存器保存最近采入的三个数据位。"},"concept:重叠匹配":{"definition":"在卡诺图分组中，同一个有效格可同时属于多个合法的圈组。","purpose":"帮助组成更大的圈组，减少表达式项或变量。","example":"一个值为一的格子可同时被横组和竖组覆盖。"},"concept:脉冲时间参数":{"definition":"描述脉冲时间特征的量，包括宽度、周期以及上升和下降时间。","purpose":"检查信号能否满足器件的时序要求。","example":"器件要求高电平至少持续十纳秒，脉冲须满足。"},"concept:振荡条件":{"definition":"电路能够自行启动并持续周期变化所需的反馈、增益和延时等条件。","purpose":"判断电路能否产生稳定的周期信号。","example":"奇数级反相器连接成环，可利用传播延迟振荡。"},"concept:阈值切换":{"definition":"输入跨过规定阈值时，电路改变逻辑状态；双阈值器件还取决于历史。","purpose":"将变化的输入转换为明确的逻辑信号。","example":"施密特触发器在输入上升越过上阈值时翻转。"},"concept:逻辑赋值":{"definition":"给逻辑变量指定零或一，并按逻辑运算规则确定表达式的值。","purpose":"检查逻辑函数在特定输入下的行为。","example":"与门两个输入均赋为一时，输出也为一。"},"concept:对偶原理":{"definition":"布尔恒等式中互换与、或及常量零、一，所得恒等式仍成立。","purpose":"从已有布尔定律推得对应的另一条定律。","example":"由A加零等于A，可得到A与一等于A。"},"concept:兼容状态":{"definition":"不完全指定状态表中，输出不冲突且对应后继也相同或兼容的一对状态。","purpose":"判断哪些状态可以合并，减少电路需要的状态数。","example":"两个状态的已定输出相同，且各列后继一致，可判为兼容。"},"concept:闭合覆盖":{"definition":"覆盖全部原状态的一组兼容状态集，且各集在每个输入下的已定后继都包含于某个所选集中。","purpose":"保证合并后状态齐全，且后续转移有明确去处。","example":"选集包含甲乙，若其后继为丙丁，还须有某个选集包含丙丁。"},"concept:复位逻辑":{"definition":"按规定的控制条件，把存储元件或时序电路送回指定初始状态的逻辑。","purpose":"让电路从已知状态启动，或在异常后重新初始化。","example":"某寄存器采用同步复位，复位有效后到下一时钟沿才归零。"},"concept:可重触发":{"definition":"电路已启动且尚未结束时，仍能接受新的有效触发，并按规则更新运行过程。","purpose":"让连续到来的事件延长定时，或重新启动计时。","example":"可重触发单稳态原定输出十毫秒，途中再触发可延后结束。"},"concept:恢复时间":{"definition":"异步置位或复位撤销后，到下一个有效时钟沿之间必须保留的最短时间。","purpose":"让触发器恢复正常采样，降低状态不确定的风险。","example":"若恢复时间要求三纳秒，复位撤销后应至少隔三纳秒再来有效沿。"},"concept:脉冲宽度":{"definition":"一次脉冲从进入有效电平到退出该电平的持续时间，通常按规定阈值测量。","purpose":"判断脉冲能否被器件识别，并检查定时是否合格。","example":"一个高脉冲在二纳秒上升、七纳秒下降，其宽度为五纳秒。"},"concept:时序可靠性":{"definition":"电路在规定延迟、时钟和输入变化条件下，仍能正确采样并按预期工作的能力。","purpose":"避免逻辑关系正确，却因时间安排不当而出错。","example":"寄存器输入在采样沿前后保持足够稳定，有助于可靠存入数据。"},"concept:反馈回路":{"definition":"把电路输出经直接连接或中间逻辑送回输入，使输出反过来影响自身的通路。","purpose":"构成存储、状态保持或振荡等具有时间特性的电路。","example":"两个或非门交叉连接形成反馈，可在控制输入撤销后保存一位状态。"},"concept:时钟门控":{"definition":"用使能条件控制时钟是否送到部分电路，可靠实现须避免产生额外边沿或窄脉冲。","purpose":"让暂时不用的寄存器停止翻转，降低动态功耗。","example":"寄存器组空闲时，门控单元关闭其时钟；需要更新时再放行。"},"concept:流水线":{"definition":"把处理过程分成若干级，级间用寄存器隔开，让不同数据同时处于不同处理阶段。","purpose":"提高连续数据的处理吞吐量，但不保证单项延迟缩短。","example":"将运算分为取数、计算、写回三级，可同时处理三项不同数据。"},"concept:流水线启动开销":{"definition":"流水线从空状态开始，到首项结果出现所需的填充时间及其带来的额外等待。","purpose":"评估短任务的实际耗时，避免只按稳定吞吐率估算。","example":"四级流水线每级一拍，首项结果需四拍，随后理想情况下每拍一项。"},"concept:流水线加速比":{"definition":"完成同一批任务时，非流水实现耗时与流水实现耗时的比值，比较条件须明确。","purpose":"衡量流水化节省多少总时间，并考虑填充和停顿影响。","example":"同批计算原需一百纳秒，流水实现需四十纳秒，加速比为二点五。"},"concept:输入悬空":{"definition":"输入引脚未连接到确定的信号或电平，其实际电位取决于器件内部结构和外界干扰。","purpose":"识别不确定输入，并按器件要求设置可靠的默认电平。","example":"未使用的互补金属氧化物半导体逻辑输入，可按手册要求接至固定电平。"},"concept:逻辑恒等":{"definition":"两个逻辑表达式在所有输入组合下结果相同，就称它们逻辑恒等。","purpose":"用于等价变换和化简电路，保持逻辑功能不变。","example":"P+0与P在P取0或1时输出都相同，因此可作等价替换。"},"concept:标准项编码":{"definition":"按约定变量顺序，把标准项对应的输入组合看作二进制数并编号。","purpose":"用于在真值表与最小项、最大项表达式间转换。","example":"例如变量顺序为XY时，输入10对应编号2。"},"concept:逻辑文字":{"definition":"逻辑变量的原变量或反变量都叫文字，一次出现算一个文字。","purpose":"用于描述逻辑项的组成，并衡量表达式复杂程度。","example":"例如乘积项X′YZ含三个文字，其中X′是反变量。"},"concept:最简形式评价":{"definition":"在指定表达形式和评价标准下，比较项数及文字数来判断是否最简。","purpose":"用于减少实现逻辑所需的门和输入连接。","example":"例如评价与或式时，可先比较乘积项数，再比较文字总数。"},"concept:逻辑单调性":{"definition":"其他输入不变时，任一输入由0变1，输出都不会由1变0，称单调递增。","purpose":"用于判断函数能否只由不含反变量的与、或运算表示。","example":"例如F＝XY中，把X从0改成1，输出不会下降。"},"concept:数制基数":{"definition":"位置计数制中可用数码的个数叫基数，相邻高位的位权是低位的基数倍。","purpose":"用于确定各位权值，并完成不同数制间的换算。","example":"例如八进制基数为8，数码17表示一个八加七。"},"concept:偶校验":{"definition":"在数据外附加校验位，使整个码字中数值为1的位数成为偶数。","purpose":"用于检出奇数个位翻转，不能保证检出偶数个位翻转。","example":"例如数据1100配校验位0，整个码字共有两个1。"},"concept:校验位":{"definition":"按约定规则由数据计算出的附加位，用于检查接收内容是否符合编码规则。","purpose":"为检错或纠错提供冗余，能力取决于具体编码。","example":"例如奇校验中，数据00可附加一位1，使总1数为奇数。"},"concept:检错与纠错":{"definition":"检错是发现码字可能出错，纠错是依据编码冗余恢复原码字。","purpose":"提高数据存储和传输的可靠性，能力取决于编码。","example":"例如三次重复发送一位数据，接收后可用多数表决纠正一位错误。"},"concept:高低有效电平":{"definition":"控制信号在高电平时起作用叫高有效，在低电平时起作用叫低有效。","purpose":"用于正确连接使能、复位等控制端，避免极性接反。","example":"例如低有效复位端接低电平时复位，接高电平时解除复位。"},"concept:直流噪声容限":{"definition":"输出保证电平与输入识别边界之间，可容许的稳态噪声电压余量。","purpose":"用于判断门电路连接后抵抗电平干扰的能力。","example":"例如高电平输出至少2.8伏、输入要求至少2伏，余量为0.8伏。"},"concept:输入输出电气兼容":{"definition":"前级输出的电压、电流等指标满足后级输入要求，才算电气兼容。","purpose":"保证器件互连后能可靠识别信号且不过载。","example":"例如把5伏输出接到只耐3.3伏的输入前，须核对是否允许。"},"concept:电流驱动能力":{"definition":"输出端在满足规定电平时，能够向负载提供或从负载吸收的电流能力。","purpose":"用于确定可带负载数量，并选择缓冲或驱动器件。","example":"例如发光二极管所需电流超过门输出能力时，可另加驱动管。"},"concept:推挽输出":{"definition":"由上拉和下拉器件配合，分别主动驱动输出高电平与低电平的结构。","purpose":"用于主动充放负载电容，提高输出驱动和切换能力。","example":"例如输出变高时上拉导通、下拉关闭，为负载电容充电。"},"concept:总线争用":{"definition":"多个输出同时驱动同一总线且要求的电平冲突，形成总线争用。","purpose":"用于分析共享总线的冲突，设计互斥使能控制。","example":"例如两片存储器同时使能，一片输出高、另一片输出低。"},"concept:器件容差":{"definition":"器件实际参数相对标称值允许存在的偏差范围，通常在指定条件下规定。","purpose":"用于估计电路性能范围，避免只按标称值设计。","example":"例如10千欧、容差为±5%的电阻，阻值允许相差500欧。"},"concept:脉宽与延迟":{"definition":"脉宽是脉冲持续的时间，传播延迟是输入变化到相应输出变化的时间。","purpose":"用于核对脉冲能否被识别，以及信号何时到达。","example":"例如某输入要求高脉宽至少10纳秒，6纳秒脉冲便不满足要求。"},"concept:级联延迟":{"definition":"信号依次经过多级电路时，各级传播延迟沿实际路径累积形成总延迟。","purpose":"用于估算输出稳定时间，并限制电路工作速度。","example":"例如两级门的延迟各为3纳秒，该路径延迟约为6纳秒。"},"concept:选择输入":{"definition":"数据选择器中用于指定哪一路数据传到输出端的控制输入。","purpose":"通过地址编码控制多路数据共用一个输出通道。","example":"例如四选一器件可用两位选择码，选通四路中的一路。"},"concept:二进制比较":{"definition":"按数值解释规则，判断两个二进制数的大于、等于或小于关系。","purpose":"用于范围检测、排序和控制条件判断。","example":"例如按无符号数解释时，三位数110大于三位数101。"},"concept:高位优先":{"definition":"比较等位宽无符号数时，从最高位查起，首个不同位决定大小。","purpose":"用于组织比较器逻辑，避免低位影响已确定的结果。","example":"例如比较1100与1011，最高位相同，再由次高位判定大小。"},"concept:信号毛刺":{"definition":"电路切换过程中，因路径延迟或输入到达时间不同而出现的短暂异常脉冲。","purpose":"用于分析误触发风险，并改进逻辑或采样时序。","example":"例如计数器多位变化时，译码输出可能短暂选中其他编号。"},"concept:汉明距离":{"definition":"两个等长二进制码字在相同位置上，取值不同的位数叫汉明距离。","purpose":"用于衡量码字差异，并分析编码的检错纠错能力。","example":"例如码字0000与1010有两位不同，汉明距离为2。"},"concept:基本模式":{"definition":"异步时序电路的一种输入约束：内部稳定后，一次只允许一个输入变量变化。","purpose":"用于约束输入变化，便于分析电路的稳定状态转换。","example":"例如先改变请求信号，等电路稳定后，再改变另一个控制信号。"},"concept:输入约束":{"definition":"限制哪些输入取值可以同时出现的条件；受约束的变量不一定能独立取遍所有组合。","purpose":"区分全部理论输入组合与实际允许的组合。","example":"两个开关被机械联动成始终相反，就不能把同开当成可用输入。"},"concept:变量代换":{"definition":"用另一变量或表达式统一替换原变量，分析时保留它们之间的关系与允许取值。","purpose":"在更换符号、取反或固定连线后保持逻辑函数含义一致。","example":"把同一根输入线从P改名为U时，所有引用它的位置要一致更新。"},"concept:全减器":{"definition":"处理两个本位输入及一个来自低位的借位输入，产生差位和向高位借位输出的组合电路。","purpose":"把逐位减法连成多位减法，分清差输出与借位输出。","example":"相较半减器，全减器还接收一位低位借位输入，便于级联。"},"concept:二进制小数":{"definition":"用二进制各小数位表示数值；小数点右边第一位权为二分之一，之后各位依次减半。","purpose":"按位权读数，并判断限定小数位数后哪些值可以准确表示。","example":"二进制0.11表示二分之一加四分之一，即十进制0.75。"},"concept:就近舍入":{"definition":"在可表示值中选择距离原数最近的一个；恰在中点、距离相同时，按题目约定的规则选择。","purpose":"将有限精度表示与直接截断区分，先判断距离再处理中点。","example":"保留一位十进制小数时，1.24比起1.3更接近1.2，因此取1.2。"},"concept:格雷码译码":{"definition":"对标准反射格雷码，最高二进制位等于最高码位；其后逐位用已还原的上一二进制位与当前码位异或。","purpose":"把该编码还原成普通二进制编号，不能把码字的表面数值直接当作编号。","example":"四位码字1100先还原最高位1，再用1与下一码位1异或，得到次高二进制位0。"},"concept:正逻辑":{"definition":"约定物理高电平记为逻辑1、低电平记为逻辑0的表示方式，电压范围仍由器件规定。","purpose":"只确定电平的逻辑编号；报警、使能等信号含义还要另行约定。","example":"采用正逻辑时，一条已经判为物理低电平的线记作逻辑0。"},"concept:负逻辑":{"definition":"约定物理高电平记为逻辑0、低电平记为逻辑1的表示方式，并不要求实际电压一定为负。","purpose":"先按约定解释逻辑值，再按应用规则判断是否有效或报警。","example":"采用负逻辑时，一条已经判为物理低电平的线记作逻辑1。"}},"programming":{"concept:标识符":{"definition":"程序中给变量、函数等起的名字，由字母、数字等组成，不能以数字开头。","purpose":"用于区分和引用程序中的不同实体，且区分大小写。","example":"把计数变量命名为item_count，后续可用这个名字读取计数。"},"concept:关键字":{"definition":"此处指排序关键字，即记录中用于比较先后次序的字段或字段组合。","purpose":"确定排序依据，使记录按指定规则排列。","example":"学生记录包含姓名和成绩，按成绩排序时，成绩就是关键字。"},"concept:源程序":{"definition":"程序员用某种程序设计语言写出的程序文本，尚不等同于机器可执行文件。","purpose":"表达处理步骤，供阅读、修改和后续翻译。","example":"在hello.c中编写main函数及输出语句，就得到一份C源程序。"},"concept:目标程序":{"definition":"源程序经过翻译得到的目标代码，通常包含机器指令，可能仍需链接。","purpose":"作为构建中间结果，与其他目标代码组合。","example":"把math.c编译成math.o后，可再与其他目标文件一起构建程序。"},"concept:编译":{"definition":"将源程序翻译成目标代码的过程，同时检查语法和部分语义约束。","purpose":"把语言描述转换为后续工具可以处理的代码。","example":"编译calc.c时发现括号缺失，编译器会给出相应诊断信息。"},"concept:链接":{"definition":"把目标文件和所需库代码组合起来，并处理符号引用及地址安排的过程。","purpose":"连接分散编写的代码，形成可用构建结果。","example":"主文件调用另一文件定义的show函数，链接时关联调用与定义。"},"concept:解释执行":{"definition":"由解释器读取程序并实施其操作的执行方式，也可能先转换为中间形式。","purpose":"让程序通过解释器运行，便于交互和调试。","example":"在解释器中输入一段求和代码，由解释器处理并显示计算结果。"},"concept:机器语言":{"definition":"由特定指令体系规定的指令编码，处理器能按这些编码执行操作。","purpose":"直接表达处理器支持的运算和控制操作。","example":"某处理器的一段指令编码表示加法，另一体系未必采用相同编码。"},"concept:高级语言":{"definition":"使用较接近问题描述的语法和抽象表达程序，较少直接涉及机器指令。","purpose":"提高编写和维护效率，减少对具体机器的依赖。","example":"用C语言的循环累加数组元素，不必逐条书写处理器指令。"},"concept:有限性":{"definition":"算法对每个合法输入都应在有限步骤后结束，而不是永远执行下去。","purpose":"保证计算能够结束，并最终交付处理结果。","example":"检查一张有限名单时，每次处理一人，全部检查后停止。"},"concept:确定性":{"definition":"算法每一步的含义和执行规则都必须明确，不能依赖含糊的理解。","purpose":"使执行者能按明确规则完成每一步操作。","example":"写明“若温度低于零则报警”，比“天气很冷时处理”更确定。"},"concept:可行性":{"definition":"算法中的每项基本操作，都应能通过有限次可实际实施的动作完成。","purpose":"保证步骤能够落实，而非只有抽象愿望。","example":"用逐项比较找到列表最大值可执行，“立即猜中最大值”不算步骤。"},"concept:输入输出":{"definition":"输入是交给处理过程的数据，输出是处理结果，不限于键盘和屏幕。","purpose":"明确处理所需信息，以及完成后交付的结果。","example":"计算矩形面积的函数接收长和宽，并把面积作为返回值交出。"},"concept:顺序结构":{"definition":"各操作按规定先后依次执行，结构本身不包含条件选择或重复控制。","purpose":"组织必须按先后关系完成的一组处理步骤。","example":"先读取圆的半径，再计算面积，最后显示计算所得的面积。"},"concept:分支结构":{"definition":"根据条件选择执行路径的控制结构，C语言可用if或switch等表达。","purpose":"使程序针对不同情况采取相应处理方式。","example":"判断库存是否充足，充足时接受订单，否则显示缺货提示。"},"concept:循环结构":{"definition":"按控制条件重复执行一段操作的结构，可执行零次、一次或多次。","purpose":"处理重复任务，避免把相同操作反复书写。","example":"用循环依次访问七天的温度记录，并累计这些温度值。"},"concept:整型":{"definition":"表示整数值的一类类型，包括不同宽度及符号属性，范围由类型和实现决定。","purpose":"保存数量、下标等整数数据，参与整数运算。","example":"用int count = 12;记录人数，不能用它直接保留半个人的小数。"},"concept:字符型":{"definition":"包括char、signed char和unsigned char；普通char的符号性由实现定义。","purpose":"存储字符编码或小整数，其中sizeof(char)为1。","example":"声明char grade = 'B';，可保存等级字母对应的执行字符编码。"},"concept:浮点型":{"definition":"用于表示具有一定范围和精度的数值，C包含float、double和long double。","purpose":"处理小数和较大范围数值，但可能存在舍入误差。","example":"用double保存测量长度2.75，连续计算时仍需考虑表示精度。"},"concept:枚举类型":{"definition":"用enum声明、以一组具名整数常量描述取值的类型；C17枚举常量为int型。","purpose":"给状态或类别起清楚的名字，提高代码可读性。","example":"声明enum Color { RED, BLUE };后，可用RED表示一种颜色。"},"concept:有符号数":{"definition":"由有符号整数类型表示的整数，可表示负值；普通整型运算溢出属未定义行为。","purpose":"表达温差、收支等需要区分正负方向的数据。","example":"用int balance = -20;表示欠款；计算时须避免超出该类型范围。"},"concept:无符号数":{"definition":"由无符号整数类型表示的非负整数，其类型内的运算按最大值加一取模。","purpose":"表示非负计数或位模式，使用时注意整数提升。","example":"unsigned int n = UINT_MAX;之后执行n += 2;，结果按模规则回绕。"},"concept:取值范围":{"definition":"某类型能表示的最小值到最大值；整型具体界限应以当前实现提供的值为准。","purpose":"判断数据能否保存，避免运算越界或转换损失。","example":"读取limits.h中的SHRT_MIN和SHRT_MAX，可了解short的取值界限。"},"concept:数据表示":{"definition":"数值、字符等信息在存储中采用的位编码方式，具体细节取决于类型和实现。","purpose":"帮助理解精度、存储、位运算及跨平台数据交换。","example":"同一个整数在不同机器上的字节顺序可能不同，传输时应约定格式。"},"concept:常量":{"definition":"表示固定值。C代码里有42、字符常量等写法；算法里的常量空间则指用量不随输入规模增长。","purpose":"分清固定数值、变量以及随规模变化的资源。","example":"42和'A'是常量；算法只用三个计数变量时，额外空间可以是常量。"},"concept:字面量":{"definition":"直接写在源码中的值，如数字、字符或字符串；字符串字面量不可修改。","purpose":"在程序中直接提供初始值、比较值或输出文字。","example":"double rate=0.25;中的0.25是浮点字面量。"},"concept:转义序列":{"definition":"字符或字符串中以反斜杠开头、表示特定字符的一组写法。","purpose":"书写换行、引号等不便直接写出的字符。","example":"printf(\"甲\\n乙\");用\\n让甲、乙分两行显示。"},"concept:字符编码":{"definition":"规定字符与数值编码的对应关系；C17不要求执行字符集采用ASCII。","purpose":"让程序能够存储、比较和传输字符。","example":"在ASCII编码中，字符'A'对应数值65。"},"concept:ASCII":{"definition":"美国信息交换标准代码，是用七个二进制位表示128个字符的编码。","purpose":"统一基本英文字母、数字、符号和控制字符的表示。","example":"ASCII中空格编码为32，小写字母'a'编码为97。"},"concept:二进制":{"definition":"以二为基数，只用0和1表示数，各位权重依次是二的整数次幂。","purpose":"描述整数的位结构，进行掩码和位运算。","example":"二进制110对应十进制6；C17没有标准0b整数写法。"},"concept:八进制":{"definition":"以八为基数，只用0至7表示数；C17整数常量以前导0标识八进制。","purpose":"紧凑表示二进制位组，也用于某些权限数值。","example":"整数常量023表示十进制19，每个八进制位对应三位二进制。"},"concept:十六进制":{"definition":"以十六为基数，用0至9及A至F表示数字；C整数常量用0x或0X开头。","purpose":"简洁表示位模式、字节数据和地址数值。","example":"0x2D表示十进制45，其中D代表十进制13。"},"concept:整除":{"definition":"整数a除以非零整数b，若余数为零，就称a能被b整除。","purpose":"判断整数倍关系，处理分组、周期和数论问题。","example":"21能被7整除，因此21个物品可每7个分成一组。"},"concept:取余":{"definition":"用%求整数除法余数；非零余数与被除数同号，除法须有定义。","purpose":"判断倍数、提取末位或让编号循环变化。","example":"17%5为2；除数为零，或对应整数商不可表示时，行为未定义。"},"concept:隐式转换":{"definition":"无需写转换运算符，由赋值、运算或参数传递等规则自动进行的类型转换。","purpose":"让不同类型的数据参与运算或传递数值。","example":"double x=6;会把整数6自动转换成double类型。"},"concept:显式转换":{"definition":"用“(类型)表达式”主动要求类型转换；写出转换不保证数值无损。","purpose":"明确指定转换类型，调整运算方式或接口类型。","example":"(double)5/2先转换再相除，结果为2.5。"},"concept:整数提升":{"definition":"较低等级整数类型通常先转为int；若int不能表示其全部值，则转为unsigned int。","purpose":"统一较小整数参与运算时使用的类型。","example":"两个unsigned char相加前会提升，结果类型未必仍是unsigned char。"},"concept:算术转换":{"definition":"通常算术转换是许多二元运算为两侧操作数确定公共类型的规则。","purpose":"明确混合类型运算采用的类型及数值转换。","example":"2+0.75中整数2转换为double，再按double进行加法。"},"concept:浮点舍入":{"definition":"精确结果无法用目标浮点类型表示时，按适用规则选取可表示值的过程。","purpose":"将有限精度运算结果保存下来，并分析误差。","example":"采用二进制浮点时，0.1通常只能保存近似值；C17不统一保证舍入到最近值。"},"concept:精度":{"definition":"数值精度指能保留多少有效数字；输出格式中的精度控制显示位数或长度，要看具体转换说明。","purpose":"区分数值保存的信息量与输出时的显示规则。","example":"%.2f显示两位小数，但不会把原来的double变量改成只能保存两位小数。"},"concept:有效位":{"definition":"从首个非零数字起体现数值精细程度的数字；浮点类型能保留的位数有限。","purpose":"描述数值保留的信息量，判断细小差异能否保存。","example":"0.00456有三位有效数字，前面的零只用于定位小数点。"},"concept:截断":{"definition":"整数除法舍去商的小数部分并趋向零；有限浮点数转整数也如此，但须检查范围。","purpose":"取得整数部分，并识别小数信息何时丢失。","example":"-11/4得到-2；浮点截断结果超出目标整数类型范围时，行为未定义。"},"concept:优先级":{"definition":"在C表达式中，它规定不同运算符怎样与操作数结合，不决定实际求值顺序；任务排序题中的含义按题设比较规则。","purpose":"读懂表达式的分组，避免把分组规则当成执行先后。","example":"2+3*4按2+(3*4)理解；涉及函数调用时，其先后还要看求值规则。"},"concept:结合性":{"definition":"规定同一优先级运算符如何分组，分为左结合和右结合，不规定执行先后。","purpose":"明确无括号表达式的结构，避免误解运算对象。","example":"a-b-c按(a-b)-c分组，因为减法运算符左结合。"},"concept:求值顺序":{"definition":"表达式各部分计算和副作用发生的先后关系；许多操作数之间没有规定先后。","purpose":"判断结果是否可靠，避免依赖未保证的执行次序。","example":"f()+g()不保证先调用谁；若两者无相互影响，两种顺序均可合法。"},"concept:短路求值":{"definition":"逻辑与和逻辑或先算左侧，仅在左侧不足以确定真假时才计算右侧。","purpose":"避免不必要的运算，并先检查后续操作的条件。","example":"p!=NULL && *p>3在p为空指针时不会求值*p>3。"},"concept:序列点":{"definition":"执行中的先后分界；此前求值的副作用已完成，此后求值的副作用尚未发生。","purpose":"分析副作用之间的先后关系，排查未定义行为。","example":"i++; j=i;中，前一完整表达式结束有序列点，后句读到更新后的i。"},"concept:副作用":{"definition":"求值除产生数值外，还改变对象、访问易变对象或执行输入输出等行为。","purpose":"识别表达式对程序状态的影响，避免重复求值出错。","example":"n++产生旧值并修改n；宏若重复展开该实参，可能多次修改n。"},"concept:未指定行为":{"definition":"标准允许多种结果，实现不必说明每次采用哪一种，但仍受标准约束。","purpose":"识别不能依赖固定选择的代码，避免误当未定义行为。","example":"两个实参都只读取变量时，其求值先后可不确定。"},"concept:实现定义":{"definition":"标准允许实现选择某种行为，并要求实现文档说明所采用的规则。","purpose":"判断代码对编译器或平台的依赖，查文档确认规则。","example":"普通char采用有符号还是无符号类型，由实现说明。"},"concept:右值":{"definition":"通常指非左值表达式产生的值；C17并未将右值列为正式表达式类别。","purpose":"区分计算得到的值与能定位对象的表达式。","example":"int x=3;中，表达式x+2得到数值，不能作为赋值目标。"},"concept:可修改左值":{"definition":"定位可被修改对象的左值，须满足非数组、非不完整类型等标准限制。","purpose":"判断表达式能否用作赋值或自增操作的目标。","example":"int x=2;中x可修改；const int y=3;中y不可修改。"},"concept:赋值表达式":{"definition":"用赋值运算符修改左侧对象，同时产生赋值后数值的表达式，结果不是左值。","purpose":"更新变量，也可将赋值所得的值用于后续计算。","example":"int a,b;执行a=b=6;后，两个变量的值均为6。"},"concept:条件表达式":{"definition":"使用条件?表达式一:表达式二，按条件是否非零，仅求值其中一个分支。","purpose":"根据条件选择一个结果，结果类型受两分支共同约束。","example":"int n=-3;表达式n<0?-n:n得到3，用于取绝对值。"},"concept:逗号表达式":{"definition":"用逗号运算符依次求值多个表达式，左侧先完成，整体取最右侧的值和类型。","purpose":"在一个表达式位置顺序安排多项操作。","example":"int x=0;执行int y=(x=3,x+4);后，y为7。"},"concept:自增":{"definition":"用++使可修改的算术或指针对象增加一步，前置取新值，后置取原值。","purpose":"推进计数或指针；须避免有符号溢出和指针越界。","example":"int n=4;执行int old=n++;后，old为4，n为5。"},"concept:自减":{"definition":"用--使可修改的算术或指针对象减少一步，前置取新值，后置取原值。","purpose":"递减计数或后退指针，操作仍须满足类型边界。","example":"int n=4;执行int now=--n;后，now和n均为3。"},"concept:复合赋值":{"definition":"用+=、*=等运算符合并运算与赋值，左侧定位表达式只求值一次。","purpose":"简写对原值的更新，避免重复计算左侧位置。","example":"int total=8;执行total+=5;后，total变为13。"},"concept:逻辑非":{"definition":"一元运算符!把标量的零值变为1，非零值变为0，结果类型为int。","purpose":"反转真假判断，也可检查数值是否为零。","example":"int count=0;表达式!count的结果为1，表示计数为零。"},"concept:逻辑与":{"definition":"运算符&&在两侧均非零时得到1，否则得到0；左侧为零便不求值右侧。","purpose":"组合必须同时满足的条件，并利用短路保护后续操作。","example":"p!=NULL && *p==7会先检查指针，再决定是否解引用。"},"concept:逻辑或":{"definition":"运算符||在任一侧非零时得到1，否则得到0；左侧非零便不求值右侧。","purpose":"表达满足任一条件即可的判断，并支持短路求值。","example":"age<6 || age>=65可判断年龄是否落入两个优惠范围。"},"concept:位与":{"definition":"整数运算符&对转换后的对应二进制位运算，仅两位均为1时结果位为1。","purpose":"提取或检查指定二进制位，不提供逻辑短路。","example":"12u & 10u得到8，对应1100与1010逐位取交集。"},"concept:位或":{"definition":"整数运算符|对转换后的对应二进制位运算，任一位为1时结果位便为1。","purpose":"合并多个位标志，或将指定二进制位置为1。","example":"8u | 2u得到10，相当于同时保留这两个位置的1。"},"concept:位异或":{"definition":"整数运算符^对转换后的对应二进制位运算，两位不同时结果位为1。","purpose":"翻转选定位，或比较两个整数哪些二进制位不同。","example":"10u ^ 3u得到9，即1010与0011逐位比较所得。"},"concept:位取反":{"definition":"整数一元运算符~先执行整数提升，再把所得类型的每个二进制位翻转。","purpose":"构造反向掩码，常用于清除选定的二进制位。","example":"unsigned x=7u;执行x &= ~2u;后，x变为5。"},"concept:左移":{"definition":"此处指数组元素向较小下标搬移，与整数的按位左移运算不同。","purpose":"压紧数组或调整元素位置，保持所需的排列顺序。","example":"把下标2、3处的丙、丁依次搬到下标1、2处。"},"concept:右移":{"definition":"此处指数组元素向较大下标搬移，目标位置须在数组合法存储范围内。","purpose":"为新元素腾出位置，重叠搬移时需避免覆盖未读数据。","example":"数组有空位时，可先把下标3的丁搬到下标4处。"},"concept:掩码":{"definition":"按用途选定二进制位的一组位模式，常用1标记需要检查或修改的位置。","purpose":"配合位运算提取、设置、清除或翻转指定位置。","example":"用掩码4u与无符号数做位与，可检查从零数第2位。"},"concept:关系运算":{"definition":"使用<、<=、>、>=比较操作数的大小关系，成立得到int值1，否则为0。","purpose":"表达大小或范围条件，控制分支与循环执行。","example":"int score=75;表达式score>=60得到1，表示达到及格线。"},"concept:比较运算":{"definition":"通常统称大小关系及相等性比较，包括<、>、<=、>=、==和!=。","purpose":"判断两个值的关系，为条件选择提供真假结果。","example":"int a=3,b=5;表达式a!=b得到1，表示两值不相等。"},"concept:复合语句":{"definition":"用一对花括号包住声明和语句形成的块，在语法上可以作为一条语句。","purpose":"组织多步操作，并为块内声明的名字建立作用域。","example":"if(ok){int t=2;sum+=t;}把声明与累加放在同一块中。"},"concept:空语句":{"definition":"只有一个分号、没有表达式的语句，执行时不产生任何操作。","purpose":"在语法要求语句但无需操作的位置占位。","example":"for(int i=0;i<3;i++);的循环体为空，计数仍会推进。"},"concept:break":{"definition":"break语句立即结束最内层的循环或switch语句。","purpose":"在已找到目标或无需继续时提前退出。","example":"逐个检查温度，发现超限值便用break结束检查。"},"concept:continue":{"definition":"continue跳过最近包围它的循环的本轮剩余语句。它即使写在循环内的switch里，仍作用于该循环。for先执行更新表达式，其他循环检查条件。","purpose":"略过不需处理的数据，继续下一轮。","example":"遍历成绩时，遇到负数记录便用continue跳过统计。"},"concept:switch":{"definition":"switch按整数表达式的值跳到匹配标签，分支不会自动结束。","purpose":"集中处理一个整数或枚举值的多种情况。","example":"根据菜单编号选择操作，各操作结束时可写break。"},"concept:case":{"definition":"case是switch中的分支标签，其整数常量表达式的值须互不重复。","purpose":"指定控制表达式取某个值时的执行入口。","example":"菜单处理中写case 5:，作为编号五对应操作的入口。"},"concept:default":{"definition":"default是switch中没有case匹配时的入口，每个switch至多一个。","purpose":"为未单独列出的取值提供统一处理。","example":"菜单编号不在支持范围时，default分支提示重新输入。"},"concept:if":{"definition":"if检查标量表达式，与零不相等时执行所控制的语句。","purpose":"根据条件决定是否执行某项操作。","example":"若库存少于五件，就执行补货提醒，否则直接继续。"},"concept:else":{"definition":"else提供if条件为零时的分支，配对最近未匹配的if。","purpose":"明确条件不成立时应该执行的操作。","example":"余额足够时扣款，else分支则显示余额不足。"},"concept:for":{"definition":"for依次安排初始化、条件检查、循环体和更新；条件可省略。","purpose":"把循环控制集中书写，便于计数和遍历。","example":"让下标从零逐次增加，遍历一个含八个元素的数组。"},"concept:while":{"definition":"while每轮先检查标量条件，条件非零才执行循环体，可能一次也不执行。","purpose":"适合重复次数未知、由条件控制的任务。","example":"只要输入仍有效，就继续读取并处理下一条记录。"},"concept:do while":{"definition":"do while先执行循环体，再检查条件，条件非零则重复，至少执行一次。","purpose":"适合必须先做一次操作再判断的流程。","example":"先显示菜单并读取选择，再判断是否继续显示菜单。"},"concept:循环不变量":{"definition":"循环不变量是在选定检查位置，每轮都成立的性质。","purpose":"帮助证明循环正确，并发现更新逻辑错误。","example":"求数组最小值时，每轮开始保存值是已检查部分的最小值。"},"concept:边界条件":{"definition":"边界条件是范围端点、空输入等临界情况所对应的限制。","purpose":"帮助确定合法范围，避免越界和漏处理。","example":"长度为六的数组，合法下标为零到五，应检查两端访问。"},"concept:循环次数":{"definition":"循环次数通常指循环体实际执行的次数，不等于条件检查次数。","purpose":"用于分析工作量、运行效率和终止情况。","example":"i从零开始，每轮加一，条件为i小于七，循环体执行七次。"},"concept:嵌套循环":{"definition":"嵌套循环是在一个循环体内包含另一个循环，可有多层。","purpose":"处理表格、成对比较等多层重复任务。","example":"外层遍历三行，内层遍历每行两列，共处理六个位置。"},"concept:函数原型":{"definition":"函数原型是注明返回类型及各参数类型的函数声明。","purpose":"让编译器检查函数调用时的类型是否合适。","example":"声明double area(double r);，说明接收并返回double值。"},"concept:函数定义":{"definition":"函数定义给出函数头和函数体，规定调用时实际执行的操作。","purpose":"实现可重复调用的功能，组织程序逻辑。","example":"定义int cube(int x){return x*x*x;}，供小整数求立方。"},"concept:函数声明":{"definition":"函数声明向编译器介绍函数名称和类型，不一定提供函数体。","purpose":"让其他代码能够依据一致的接口调用函数。","example":"在调用前写void reset(void);，说明函数无参数且无返回值。"},"concept:形参":{"definition":"形参是函数接收实参值的参数；数组形式的形参会调整为指针类型。","purpose":"为函数内部使用传入数据提供名称。","example":"int twice(int n)中的n是形参，函数可返回n的两倍。"},"concept:实参":{"definition":"实参是函数调用时给出的表达式，其求得的值用于传给形参。","purpose":"向一次具体的函数调用提供所需数据。","example":"调用twice(k+1)时，k+1是实参，先计算其值再传入。"},"concept:值传递":{"definition":"C的参数按值传递，形参接收副本；传指针时复制的也是指针值。","purpose":"理解修改形参与修改所指对象的区别。","example":"函数内给普通int形参赋零，不会改变调用者的原变量。"},"concept:返回值":{"definition":"返回值是函数调用向调用处提供的结果，可用于表达式或被丢弃。","purpose":"把计算结果交给调用者继续使用。","example":"函数返回一个长度，调用者可把它存入变量再计算面积。"},"concept:返回类型":{"definition":"返回类型规定函数结果的类型；void表示函数不返回值。","purpose":"约定调用结果的使用方式及所需类型转换。","example":"double mean(int a,int b)声明结果为double，可返回小数均值。"},"concept:递归":{"definition":"递归是函数直接或通过其他函数再次调用自身的过程。","purpose":"把问题分解为同类的较小问题来处理。","example":"求链表长度时，非空节点的长度等于后续链表长度加一。"},"concept:递归终止条件":{"definition":"递归终止条件是停止继续递归并直接完成当前调用的判断。","purpose":"配合向终止情况推进的步骤，使递归结束。","example":"递归遍历目录时，遇到没有子目录的目录就不再向下调用。"},"concept:空指针":{"definition":"不指向任何对象或函数的特殊指针值，不保证其表示是全零位。","purpose":"表示没有目标，访问目标前可先判断。","example":"int *p=NULL; 表示p当前不指向整数对象。"},"concept:野指针":{"definition":"非标准术语，通常指未初始化或因目标寿命结束而失效的指针。","purpose":"提醒排查无效访问；解引用会导致未定义行为。","example":"局部指针int *p未初始化就执行*p=2，行为未定义。"},"concept:指针数组":{"definition":"元素都是指针的数组，每个元素可以分别指向类型匹配的目标。","purpose":"集中管理多个地址，便于逐个访问目标。","example":"int *a[3]; 声明含三个整数指针的数组。"},"concept:数组指针":{"definition":"指向整个数组的指针，其类型包含所指数组的元素类型和长度。","purpose":"按整行访问二维数组，保留每行的长度信息。","example":"int a[2][4]; int (*p)[4]=a; 使p指向首行。"},"concept:二级指针":{"definition":"指向指针对象的指针，通过两次间接访问可到达最终对象。","purpose":"让函数修改调用者的指针，或访问指针元素。","example":"int x=5,*p=&x,**q=&p; 此时**q为5。"},"concept:函数指针":{"definition":"指向函数的指针，类型由函数返回类型及参数类型等共同确定。","purpose":"在运行时选择并调用类型匹配的函数。","example":"int neg(int x){return -x;} 可由函数指针调用。"},"concept:回调函数":{"definition":"把函数通过指针交给其他代码，由其他代码在约定时机调用。","purpose":"把具体处理规则交给调用者灵活提供。","example":"排序函数接收比较函数指针，用它决定元素先后。"},"concept:const":{"definition":"类型限定符，禁止通过相应左值修改对象，不一定表示编译期常量。","purpose":"表达只读约束，减少意外修改数据。","example":"const int limit=8; 随后给limit赋值违反约束。"},"concept:指向常量的指针":{"definition":"指向带const限定类型的指针，不能通过它修改目标，指针本身可变。","purpose":"提供只读访问，同时允许改指其他对象。","example":"int x=3; const int *p=&x; 可读取*p，不能给*p赋值。"},"concept:常量指针":{"definition":"指针对象本身带const限定，初始化后不能改变其保存的地址。","purpose":"固定访问目标；目标是否可改由目标类型决定。","example":"int x=3; int *const p=&x; 可执行*p=4。"},"concept:动态内存":{"definition":"运行时申请、具有分配存储期的空间，其寿命不随函数返回自动结束。","purpose":"容纳运行时才能确定数量或寿命的数据。","example":"读入人数后申请对应大小的成绩数组，用完再释放。"},"concept:内存分配":{"definition":"取得供对象使用的存储空间；动态分配通过标准库函数申请。","purpose":"为程序运行中新增的数据提供存储位置。","example":"申请十个double所需空间，成功后再写入测量值。"},"concept:内存释放":{"definition":"结束一块动态分配空间的使用，使其可供后续分配再次利用。","purpose":"归还不再需要的空间，避免持续占用。","example":"动态数组处理完后释放；原有别名也不能继续访问它。"},"concept:内存泄漏":{"definition":"动态分配的空间不再需要却未释放，常因丢失其地址而无法回收。","purpose":"识别并修复空间长期占用，维持程序稳定。","example":"未释放旧空间便用新地址覆盖唯一指针，会造成泄漏。"},"concept:malloc":{"definition":"按指定字节数申请动态内存，内容没有被初始化。","purpose":"申请运行时需要的空间，失败返回空指针。","example":"申请一个int的空间后，先检查是否成功，再给它赋值和读取。"},"concept:calloc":{"definition":"为给定个数和大小的元素申请空间，并把所有位清零。","purpose":"批量申请并清零；不保证各类对象都得到数值零。","example":"为6个int申请空间成功后，各元素为0；浮点或指针类型不能照搬此结论。"},"concept:realloc":{"definition":"调整已有动态空间大小，可能搬迁，并保留新旧大小较小范围内的内容。","purpose":"扩缩缓冲区；正大小申请失败时旧空间仍有效。","example":"用临时指针接收扩容结果，成功后再更新原指针。"},"concept:free":{"definition":"释放分配函数所得且尚未释放的空间，传入空指针则不做任何事。","purpose":"归还动态空间，不会自动清空调用者的指针。","example":"free(NULL)合法；重复释放同一块空间是未定义行为。"},"concept:sizeof":{"definition":"求对象或完整对象类型所占字节数的运算符，结果类型为size_t；函数和void不适用。","purpose":"计算存储需求；通常不执行操作数，变长数组可能例外。","example":"char text[7]的sizeof text为7；数组作为函数形参时按指针处理。"},"concept:strlen":{"definition":"string length的缩写，统计字符串终止空字符之前的字节数。","purpose":"获取字符串长度；输入必须能访问到终止空字符。","example":"strlen(\"hello\")返回5，不把结尾的空字符计入。"},"concept:strcpy":{"definition":"string copy的缩写，把源字符串连同终止空字符复制到目标空间。","purpose":"复制字符串；目标须足够大，源目标不得重叠。","example":"char dst[8]; strcpy(dst,\"sun\"); 复制后得到字符串sun。"},"concept:strcmp":{"definition":"string compare的缩写，按首个不同字符的unsigned char值比较字符串。","purpose":"判断内容相等或先后，返回负数、零或正数。","example":"strcmp(\"red\",\"red\")返回0，表示两串内容相同。"},"concept:strcat":{"definition":"string concatenate的缩写，把源字符串接到目标末尾并补终止空字符。","purpose":"拼接字符串；目标容量须足够，两片区域不得重叠。","example":"char s[10]=\"ab\"; strcat(s,\"cd\"); 得到字符串abcd。"},"concept:strchr":{"definition":"string character的缩写，查找字符在字符串中的首次位置，包含终止空字符。","purpose":"定位字符，返回其指针；未找到时返回空指针。","example":"strchr(\"mango\",'g')返回指向其中字符g的指针。"},"concept:栈帧":{"definition":"常见实现中，一次函数调用保存局部数据和返回信息的区域；C17不强制采用。","purpose":"帮助理解函数调用、递归和调试信息。","example":"递归计算阶乘时，各次调用通常各有栈帧。"},"concept:作用域":{"definition":"程序中某个标识符的声明能够起作用的文本范围，受声明位置和嵌套影响。","purpose":"判断某处名字对应哪个声明。","example":"循环内声明的计数变量，通常不能在循环外使用。"},"concept:可见性":{"definition":"某处能否通过一个名字引用相应声明；同名的内层声明可能遮蔽外层声明。","purpose":"解释嵌套代码中同名变量的选择。","example":"内层块声明同名变量后，外层变量仍存在但被遮蔽。"},"concept:生存期":{"definition":"对象在程序执行中存在、拥有存储且可合法访问的时间段，与名字作用域不同。","purpose":"判断指针指向的对象是否仍有效。","example":"动态申请的整数对象，从成功分配到释放之间存在。"},"concept:自动存储期":{"definition":"普通非静态块内对象通常具有的存储期；非变长数组对象随所属块的执行存在。","purpose":"理解局部对象何时创建和失效。","example":"函数内普通整数变量，每次递归调用都有独立对象。"},"concept:静态存储期":{"definition":"对象的存储贯穿整个程序执行过程，只在程序启动前初始化一次。","purpose":"让数据跨函数调用持续保留。","example":"函数中的静态计数器，可累计该函数被调用的次数。"},"concept:外部链接":{"definition":"标识符具有的链接属性，使不同翻译单元中的相应声明可指向同一对象或函数。","purpose":"支持多个源文件共享对象或函数。","example":"某文件定义总数，另一文件用extern声明后引用它。"},"concept:内部链接":{"definition":"标识符具有的链接属性，使其在同一翻译单元内的相应声明指向同一实体。","purpose":"将名字限制在本翻译单元内共享。","example":"文件中用static定义辅助函数，其他文件不能靠该名字链接它。"},"concept:局部变量":{"definition":"通常指在函数体或内部块中声明的变量，名字受块作用域限制，也可具有静态存储期。","purpose":"保存某段代码使用的数据，减少名字冲突。","example":"求平均值的函数可用局部变量sum保存累计值。"},"concept:全局变量":{"definition":"通常指在函数外声明的文件作用域变量，具有静态存储期，不一定具有外部链接。","purpose":"保存多个函数需要访问的共享状态。","example":"文件顶部定义运行标志，本文件多个函数可访问它。"},"concept:数组边界":{"definition":"数组可访问元素的下标范围；长度为n时，下标从零到n减一，尾后位置不是元素。","purpose":"确定循环和下标访问的合法范围。","example":"长度为六的数组，其最后一个元素使用下标五。"},"concept:越界访问":{"definition":"通过越出数组有效元素范围的位置读写数据，在C17中属于未定义行为。","purpose":"识别可能导致错误或内存破坏的操作。","example":"对长度为三的数组写入下标四的位置，就发生越界。"},"concept:数组初始化":{"definition":"定义数组时指定初始内容；非变长数组可用列表，未显式列出的元素按规则补零。","purpose":"让数组从确定的数据状态开始使用。","example":"定义int v[4]={7};，首项为七，其余项为零。"},"concept:初始化列表":{"definition":"定义对象时，用花括号包围并以逗号分隔的一组初始化项，可嵌套或指定成员。","purpose":"为数组元素或结构体成员设置初值。","example":"结构体含坐标x、y时，可用{.y=8,.x=3}初始化。"},"concept:零初始化":{"definition":"按类型赋予零初值：整数为零、浮点数为零值、指针为空指针，不保证所有位全零。","purpose":"建立确定的默认值，避免使用不定值。","example":"定义double d[3]={0};，三个元素都为浮点零。"},"concept:字符数组":{"definition":"元素类型为字符类型的数组；可以保存字符序列，但不一定包含字符串结束符。","purpose":"存放文本、字符集合或原始字节。","example":"char marks[3]={'A','B','C'}可保存三个等级标记。"},"concept:字符串":{"definition":"由连续字符组成，并以首个空字符终止的序列；结束符占空间但不计入字符串长度。","purpose":"按约定保存文本并供字符串函数处理。","example":"字符数组保存\"sun\"时，需要容纳三个字母和结束符。"},"concept:字符串结束符":{"definition":"值为零的空字符，写作'\\0'，标记字符串结束，与数字字符'0'不同。","purpose":"让字符串函数判断文本在哪里结束。","example":"在字符数组第二个位置写入'\\0'，字符串便在此终止。"},"concept:二维数组":{"definition":"元素本身是一维数组的数组，各行元素数相同；C语言中各行依次连续存储。","purpose":"用行列下标组织表格或矩阵数据。","example":"int grid[2][5]可表示两行五列的整数表格。"},"concept:行优先":{"definition":"多维数组的一种存储顺序：先连续存完一行，再存下一行；C数组采用此顺序。","purpose":"理解元素地址关系并安排遍历顺序。","example":"两行三列的数组，首行三个元素之后紧接第二行。"},"concept:解引用":{"definition":"用一元星号经指针指示其所指对象或函数；读取对象须保证指针有效且对象仍存在。","purpose":"通过指针访问对象，或间接调用函数。","example":"int n=6; int *p=&n;，执行*p=9会修改n。"},"concept:取地址":{"definition":"通常用一元&取得对象或函数的地址；位域以及声明为register的对象不能这样取址。","purpose":"构造指针，向函数提供对象位置。","example":"int score=80;，表达式&score可取得该变量的地址。"},"concept:指针运算":{"definition":"指针加减整数按元素大小移动，结果须在同一数组内或尾后；尾后位置不能解引用。","purpose":"遍历数组，定位相隔若干元素的位置。","example":"指针指向数组首项时，加二可指向第三个元素。"},"concept:指针差":{"definition":"同一数组内或尾后的两个指针相减，得到元素间隔；结果须能由ptrdiff_t类型表示。","purpose":"计算数组中两个位置相距多少个元素。","example":"长度为八的数组中，尾后指针减首指针得到八。"},"concept:二进制文件":{"definition":"以二进制模式打开的文件，按字节读写，避免文本模式的字符转换。","purpose":"保存图片、音频或明确编码的数据。","example":"把四个像素的颜色字节写入图片数据文件。"},"concept:标准输入":{"definition":"程序启动时预先打开的输入流stdin，通常连接键盘，也能重定向。","purpose":"为程序提供统一的默认输入来源。","example":"运行时将数字文件重定向给程序，作为输入。"},"concept:标准输出":{"definition":"程序启动时预先打开的输出流stdout，通常连接终端，也能重定向。","purpose":"统一输出程序结果，方便显示或保存。","example":"将程序打印的统计报告重定向到文本文件。"},"concept:文件结束符":{"definition":"EOF全称End Of File，是负整数宏，表示部分输入函数的结束或失败。","purpose":"提示检查流状态，并非文件中的固定字符。","example":"逐字符读取文章时，用int变量接收并判断EOF。"},"concept:fopen":{"definition":"按指定模式打开文件，成功返回流指针，失败返回空指针。","purpose":"建立程序与文件之间的读写通道。","example":"用只读模式打开日记文件，检查成功后再读取。"},"concept:fclose":{"definition":"关闭有效文件流，刷新待写数据；成功返回零，失败返回EOF。","purpose":"释放文件资源，并检查关闭时的错误。","example":"保存日志后检查关闭结果，确认未报告写入失败。"},"concept:fscanf":{"definition":"从指定流按格式读取并转换，返回成功赋值项数；首次转换完成前发生输入失败才返回EOF。","purpose":"从文本文件提取数字等结构化内容，并检查转换是否成功。","example":"读取学号和成绩后，检查返回值是否为2，再使用这两项数据。"},"concept:fprintf":{"definition":"按格式向指定流输出文本，成功返回字符数，出错返回负数。","purpose":"把数值和文字组织成可读的文件内容。","example":"向报表文件写入商品名称及保留两位小数的价格。"},"concept:fread":{"definition":"从流读取指定数量和大小的数据项，返回完整读入的数据项数。","purpose":"成块读取字节数据，减少逐字符操作。","example":"读取一段图像字节，再检查实际读入数量。"},"concept:fwrite":{"definition":"把内存中指定数量和大小的数据项写入流，返回完整写入的项数。","purpose":"成块保存数据，返回值用于检查写入情况。","example":"把一组传感器原始字节写入数据文件。"},"concept:fseek":{"definition":"按基准和偏移调整文件位置；文本流定位受限，成功返回零。","purpose":"跳转到指定位置，支持文件随机访问。","example":"在支持定位的二进制文件中跳过头部再读取。"},"concept:ftell":{"definition":"取得流当前位置，失败返回负一；文本流返回值不能当作字节偏移。","purpose":"记录位置，方便之后返回继续处理。","example":"读取文本前保存位置值，稍后用fseek返回。"},"concept:rewind":{"definition":"将流定位到文件开头，并清除错误和文件结束标志，不返回结果。","purpose":"让已读取的文件可以从头再次处理。","example":"统计完文章字符后，回到开头重新读取正文。"},"concept:feof":{"definition":"检查流的文件结束标志，已置位返回非零；它不预测下一次读取。","purpose":"在读取失败后判断是否已经到达末尾。","example":"读取字符失败后，检查结束标志决定是否正常收尾。"},"concept:ferror":{"definition":"检查指定流的错误标志，有错误返回非零，检查本身不清除标志。","purpose":"判断读写失败是否由流错误引起。","example":"读取配置失败后，检查错误标志并报告读取异常。"},"concept:fgets":{"definition":"从流最多读取容量减一的字符，保留读到的换行，成功后补空字符。","purpose":"限制读取长度，安全接收一段文本。","example":"用容量为四十的数组读取一行简短留言。"},"concept:fputs":{"definition":"把字符串写入指定流，不写结尾空字符，也不自动添加换行。","purpose":"直接输出已有文本，无须格式转换。","example":"将欢迎语写入日志，再单独写入换行符。"},"concept:getchar":{"definition":"从标准输入读取一个字符，以unsigned char转为int返回，失败返回EOF。","purpose":"逐字符处理输入，包括空格和换行。","example":"用int变量读取用户输入的一个标点并检查结果。"},"concept:putchar":{"definition":"将参数转为unsigned char后写入标准输出，成功返回该字符，失败返回EOF。","purpose":"逐个输出字符，适合简单字符处理。","example":"遍历一段文字，逐字符输出并在末尾补换行。"},"concept:scanf":{"definition":"从标准输入按格式转换并赋值，返回成功赋值项数，输入失败可返回EOF。","purpose":"读取指定类型的数据，需检查转换结果。","example":"读入年龄时检查赋值项数，遇到文字则提示重输。"},"concept:printf":{"definition":"按格式向标准输出写文本，成功返回字符数，输出错误返回负数。","purpose":"把变量转换成便于阅读的显示结果。","example":"将测得的温度按保留一位小数的形式显示。"},"concept:格式控制":{"definition":"格式串中规定转换类型、宽度等规则的写法，须与实参类型匹配。","purpose":"控制数据怎样被读取或转换成文本。","example":"用%.2f输出价格，使小数部分保留两位。"},"concept:字段宽度":{"definition":"一项占用或允许读取的长度。printf里是最小输出宽度，scanf里是最大读取宽度；文件字段按格式约定。","purpose":"对齐输出、限制输入长度，或按给定长度拆分记录。","example":"%5d不足5位时补空格，超过不截短；%4s的缓冲区至少要5字节。"},"concept:输入缓冲":{"definition":"输入流暂存已获取但尚未被程序消费的数据的区域，具体方式依环境而定。","purpose":"减少底层读取次数，让后续读取继续取数。","example":"读完一个数字后，余下的换行仍可能供下次读取。"},"concept:strstr":{"definition":"strstr是字符串子串查找函数，返回首次匹配处的指针，未找到返回空指针。","purpose":"用于在以空字符结尾的字符串中寻找连续文本。","example":"在\"red apple\"中查找\"apple\"，得到指向字母a的指针。"},"concept:memcpy":{"definition":"memcpy是内存复制函数，按指定字节数复制数据，源区与目标区不得重叠。","purpose":"用于复制数组或对象的字节表示，不检查字符串结尾。","example":"把一个整数数组复制到容量足够的另一数组，重叠则行为未定义。"},"concept:memmove":{"definition":"memmove是允许源区与目标区重叠的内存复制函数，效果如同借助临时数组。","purpose":"用于在同一缓冲区内安全移动连续字节。","example":"将字符数组前四个字节移到下一字节处，可用它处理重叠。"},"concept:宏替换":{"definition":"宏替换是在预处理时，按宏定义替换匹配的标识符记号，不是任意子串替换。","purpose":"用于统一常量或生成重复代码片段。","example":"定义SIZE为12后，数组声明中的SIZE可被替换为12。"},"concept:函数式宏":{"definition":"函数式宏是接受实参的宏，按预处理记号替换形参，不进行函数参数类型检查。","purpose":"用于生成带参数的代码片段，需防范实参重复求值。","example":"定义DOUBLE(x)为((x)+(x))，传入自增表达式可能产生未定义行为。"},"concept:条件编译":{"definition":"条件编译是预处理时按条件选择保留哪些源代码，被排除的分支不参与后续编译。","purpose":"用于切换调试功能或适配不同编译环境。","example":"用#if DEBUG包围日志代码，可按DEBUG的值决定是否保留。"},"concept:头文件":{"definition":"头文件是供源文件包含的接口材料，通常放函数声明、类型定义和宏定义。","purpose":"让多个源文件共享一致的接口声明。","example":"把学生结构体的定义放进student.h，供多个源文件包含。"},"concept:include":{"definition":"#include是包含指令，在预处理阶段将指定头文件或源文件的内容纳入处理。","purpose":"用于引入标准库声明或项目公共接口。","example":"写#include <string.h>，可获得标准字符串处理函数的声明。"},"concept:define":{"definition":"#define是定义宏的预处理指令，可建立对象式宏或带形参的函数式宏。","purpose":"用于集中表示常量或可重复展开的代码。","example":"用#define LIMIT 20定义上限，之后可写int a[LIMIT]。"},"concept:undef":{"definition":"#undef是取消指定宏当前定义的预处理指令；宏未定义时使用也合法。","purpose":"用于结束宏的作用或为重新定义做准备。","example":"先定义TRACE，再用#undef TRACE，后续该名字不再按原宏展开。"},"concept:ifdef":{"definition":"#ifdef按指定名字是否已定义为宏选择代码分支，不检查宏替换内容的数值。","purpose":"用于根据功能标记决定是否保留代码。","example":"定义LOGGING为空宏后，#ifdef LOGGING控制的代码仍会被保留。"},"concept:ifndef":{"definition":"#ifndef在指定名字尚未定义为宏时保留对应分支，本身不会定义该宏。","purpose":"常用于头文件保护，避免内容被重复包含。","example":"头文件先检查STUDENT_H是否未定义，再定义它并放入声明。"},"concept:结构体成员":{"definition":"结构体成员是结构体类型中声明的组成项，可以有不同类型，也可以是数组。","purpose":"用于把同一事物的相关数据组织在一起。","example":"学生结构体可包含姓名字符数组和整数年龄两个成员。"},"concept:结构体指针":{"definition":"结构体指针是指向某种结构体对象的指针，其类型决定可访问哪些成员。","purpose":"用于传递对象地址，或连接动态分配的数据节点。","example":"让struct Point *p指向点对象后，可用p->x访问横坐标。"},"concept:成员访问":{"definition":"成员访问用点号访问结构体对象的成员，用箭头访问有效结构体指针所指对象的成员。","purpose":"用于读取或修改结构体中的指定数据。","example":"若p指向对象s，则s.age和p->age访问的是同一成员。"},"concept:结构体赋值":{"definition":"结构体赋值将一个结构体的成员值复制给兼容类型的对象，指针成员只复制指针值。","purpose":"用于整体复制记录，避免逐个成员赋值。","example":"执行b=a后，数组成员也被复制，但指针指向的数据不会另建副本。"},"concept:内存对齐":{"definition":"内存对齐是对象地址必须满足其类型的对齐要求，具体要求取决于实现。","purpose":"用于满足目标机器的数据访问要求，并影响对象布局。","example":"某实现要求int按四字节对齐，结构体可能为此插入空隙。"},"concept:填充字节":{"definition":"填充字节是对象表示中不承载成员值的额外字节，结构体成员之间或末尾可能存在。","purpose":"用于满足对齐等布局要求，不宜拿来判断成员相等。","example":"含char和int的结构体，大小可能超过两个成员大小之和。"},"concept:自引用结构体":{"definition":"自引用结构体通过指针成员指向自身类型的对象，不能直接包含自身类型的成员。","purpose":"用于构造链表、树等彼此连接的数据结构。","example":"链表节点含整数data和struct Node *next，后者指向下一节点。"},"concept:位域":{"definition":"位域是按位数声明的结构体或联合体成员，布局由实现规定，不能对其取地址。","purpose":"用于紧凑保存标志或小范围整数，但需注意可移植性。","example":"unsigned int ready:1可保存零或一；位的排列顺序是实现定义的。"},"concept:文件指针":{"definition":"文件指针是FILE类型对象的指针，用来标识和操作流，不是文件全部内容的地址。","purpose":"用于通过标准输入输出函数读写或关闭流。","example":"fopen成功后返回FILE *，可传给fgetc读取一个字符。"},"concept:文件位置":{"definition":"文件位置是流所维护的读写位置状态，文本流中的位置不一定等于物理字节偏移。","purpose":"用于确定后续读写位置，并支持记录后返回。","example":"先用fgetpos保存当前位置，读取一段后可用fsetpos恢复。"},"concept:文件定位":{"definition":"文件定位是通过fseek、fsetpos等改变流的位置，允许的定位方式受流类型限制。","purpose":"用于返回已知位置，或跳过部分内容再读写。","example":"文本流可将ftell返回的有效位置值配合SEEK_SET交给fseek恢复。"},"concept:文本文件":{"definition":"文本文件通常按字符和行组织内容；C以文本流访问时，外部表示可能发生转换。","purpose":"用于保存便于人阅读和编辑的文字资料。","example":"用文本模式写入换行符，某些实现会将它转换为回车加换行。"},"concept:截断模式":{"definition":"用w或w+模式打开文件时，已有文件成功打开即清空，不存在则创建。","purpose":"用于生成全新内容，避免保留旧文件尾部。","example":"用wb打开旧图片文件后，其原有字节被清除。"},"concept:追加模式":{"definition":"用a或a+模式打开文件，每次写入都放在当时的文件末尾。","purpose":"用于保留旧记录并持续添加新内容。","example":"用a打开日记文件，新写的一段接在旧内容后面。"},"concept:更新模式":{"definition":"模式串带+表示同一文件流可读也可写，创建和清空规则由主模式决定。","purpose":"用于通过同一文件流读取并修改内容。","example":"用r+打开已有文件，可以读取后定位修改其中内容。"},"concept:读写转换":{"definition":"更新流写后读须刷新或定位；读后写须定位，读遇文件尾时例外。","purpose":"用于满足更新流切换方向的标准要求。","example":"在r+流写入后调用fflush，再读取后续内容。"},"concept:移植性":{"definition":"程序在不同编译器和系统上仍能按预期工作的能力，取决于所用特性。","purpose":"用于减少对特定平台和实现细节的依赖。","example":"不假定int恰为四字节，而用sizeof取得实际大小。"},"concept:资源释放":{"definition":"资源使用结束后，通过对应操作归还，例如关闭文件或释放动态内存。","purpose":"用于避免资源泄漏，并及时发现关闭错误。","example":"malloc取得的内存用完后交给free释放一次。"},"concept:行号":{"definition":"行号标识二维数组中的某一行；C数组的有效行下标从零开始。","purpose":"用于定位一整行，并组织逐行处理过程。","example":"数组grid有四行时，grid[2]表示第三行。"},"concept:大端字节序":{"definition":"多字节数值的一种排列方式，将较高有效位对应的字节放在前面。","purpose":"用于按约定解析文件或传输中的数值。","example":"十六进制数0x1234按大端排列为0x12、0x34。"},"concept:首差异位置":{"definition":"按指定顺序比较两个序列时，第一个内容不同或仅一方已结束的位置。","purpose":"用于定位两个文件或序列最早出现的差别。","example":"从零计数比较cat与car，首差异位置为2。"},"concept:字符推回":{"definition":"ungetc把字符推回输入流，供后续读取；成功时清除文件尾指示。","purpose":"用于读过一个字符后，将它留给后续处理。","example":"读到分隔符后将它推回，下次读取先得到该字符。"},"concept:文件重命名":{"definition":"rename改变文件名称；目标名已存在时的行为由实现定义。","purpose":"用于调整文件名称，并通过返回值检查成功与否。","example":"目标名不存在时，可将note.txt改名为memo.txt。"},"concept:对象表示":{"definition":"一个对象占据的全部字节所构成的表示，其中可能包含填充位。","purpose":"用于理解存储大小、字节复制与二进制数据。","example":"sizeof(double)给出一个double对象占用的字节数。"},"concept:算术表达式类型":{"definition":"算术表达式的类型由操作数类型及适用的整数提升、通常算术转换确定。","purpose":"用于判断计算精度、取值范围和后续转换。","example":"表达式2+0.5的类型为double，结果为2.5。"},"concept:除法与结果类型":{"definition":"两操作数均为整数时作整数除法，小数部分向零截去；否则作浮点除法。","purpose":"用于避免整数相除时意外丢失小数部分。","example":"9/4得到2，9.0/4得到2.25；除数不能为零。"},"concept:值与存储位置":{"definition":"值是数据内容，存储位置是保存对象的地方；某些表达式可指定对象。","purpose":"用于区分读取内容、修改对象与取得地址。","example":"执行x=8改变x的值，&x则取得该对象的地址。"},"concept:表达式求值":{"definition":"按运算规则取得表达式的值并发生相应副作用，求值顺序不总是固定。","purpose":"用于分析计算结果，以及自增和赋值等变化。","example":"x初值为4时，y=x++使y为4，随后x为5。"},"concept:运算符语义":{"definition":"运算符规定对操作数做什么，其具体行为还受操作数类型等条件影响。","purpose":"用于准确理解计算、比较、赋值和逻辑操作。","example":"x==3判断是否相等，x=3则把3存入x。"},"concept:布尔上下文":{"definition":"在条件判断等场合，标量值与零比较：等于零为假，不等于零为真。","purpose":"用于理解分支、循环和逻辑运算如何判真。","example":"if(-2)的条件为真，执行!(-2)则得到整数0。"},"concept:分支可达性":{"definition":"某条分支是否可能在给定输入、已有状态和控制条件下实际执行。","purpose":"用于排查遗漏路径、无效判断和测试缺口。","example":"已知x大于10时，随后x小于0的分支无法进入。"},"concept:循环控制流":{"definition":"循环中判断、执行循环体和更新状态的先后路径，也受跳转语句影响。","purpose":"用于追踪重复执行及continue、break的作用。","example":"for循环执行continue后，先执行更新式再判断条件。"},"concept:终止条件":{"definition":"使循环停止继续迭代的条件，例如控制表达式为假或执行break。","purpose":"用于保证循环适时结束，避免遗漏边界。","example":"while(k>0)每轮将k减一，到零时停止进入循环。"},"concept:迭代状态":{"definition":"循环某一轮进行时，各相关变量和数据对象的当前内容。","purpose":"用于推演下一轮变化，检查累计量是否正确。","example":"遍历链表时，当前节点指针和已计数目共同构成状态。"},"concept:顺序执行":{"definition":"没有分支或跳转改变路径时，各完整表达式及其副作用按语句顺序完成。","purpose":"用于依据前一步结果推算后续语句的行为。","example":"先执行x=6，再执行y=x+2，后一句使用更新后的x。"},"concept:初始化与赋值":{"definition":"初始化在对象创建时给初值；赋值在对象存在后向可修改对象写入新值。","purpose":"用于区分对象初始状态与后续内容更新。","example":"int n=7是初始化，随后n=9是赋值。"},"concept:数组元素访问":{"definition":"通过数组名和下标读写指定元素，下标从零开始，访问必须在有效范围内。","purpose":"用于按位置读取、修改或遍历数组数据。","example":"int v[3]={7,8,9}; v[1]=6; 修改第二项。"},"concept:边界索引":{"definition":"长度为n的数组可访问下标为0至n−1，尾后一位指针不可解引用。","purpose":"用于确定循环范围，避免越界导致未定义行为。","example":"char t[4]; 可写t[3]，不可写t[4]。"},"concept:元素类型与步长":{"definition":"数组元素类型决定每项大小，元素指针加一跨过一个该类型的元素。","purpose":"用于理解连续存储、下标定位和指针运算。","example":"double d[3]; d+1指向第二项，跨过sizeof(double)字节。"},"concept:指针指向关系":{"definition":"指针值可指向对象或其尾后一位，也可为空；解引用必须满足有效访问条件。","purpose":"用于间接访问对象，在函数间共享数据。","example":"int k=5; int *p=&k; *p=9; 随后k为9。"},"concept:对象有效期":{"definition":"对象从生命周期开始到结束期间存在；结束后不能再通过旧指针访问它。","purpose":"用于判断地址何时可用，避免访问失效对象。","example":"块内局部变量的地址被保存后，离开该块也不能继续解引用。"},"concept:声明与定义":{"definition":"声明介绍名称和类型；对象定义还提供存储，函数定义还给出函数体。","purpose":"用于组织接口、实现和跨源文件引用。","example":"extern int count;仅声明；int count=1;同时定义。"},"concept:类型与操作约束":{"definition":"类型规定数据的解释方式和可用操作，运算符及参数必须满足对应约束。","purpose":"用于检查表达式是否合法，选择合适的数据表示。","example":"整数可用取余运算；double变量不能直接作为%的操作数。"},"concept:函数接口":{"definition":"函数接口说明返回类型、参数及调用条件，使调用者知道怎样使用函数。","purpose":"用于约定输入输出，连接不同功能模块。","example":"int square(int x); 表示接收一个int并返回int。"},"concept:返回值约定":{"definition":"返回值约定规定各种结果的含义，包括成功、失败或未找到时的表示。","purpose":"让调用者能正确识别结果并选择后续处理。","example":"查找字符的函数约定成功返回位置，失败返回−1，调用者先检查。"},"concept:参数传递语义":{"definition":"C函数按值传参，形参得到实参值的副本；指针参数复制的也是地址值。","purpose":"用于判断函数能否影响调用者的数据。","example":"void clear(int *p){*p=0;} 可通过传入地址清零对象。"},"concept:函数调用过程":{"definition":"调用时求出实参并传给形参，执行函数体，再将控制权和可能的结果交回。","purpose":"用于追踪执行流程以及数据在函数间的流动。","example":"执行y=abs(-4);时先调用abs，再把返回值赋给y。"},"concept:递归调用链":{"definition":"函数直接或间接再次调用自己形成递归，每次调用有各自的参数和自动局部对象。","purpose":"用于逐步缩小问题，并在终止条件处返回。","example":"求阶乘可让f(n)调用f(n−1)，到n为零时结束递归。"},"concept:预处理阶段":{"definition":"预处理在正式语法翻译前处理指令，完成头文件包含、宏展开及条件编译。","purpose":"用于复用声明、配置代码和定义宏。","example":"#include <limits.h>让后续代码能使用INT_MAX等定义。"},"concept:文本替换边界":{"definition":"宏按预处理记号展开，通常匹配完整标识符，不替换字符串内部或名称片段。","purpose":"用于判断宏会在哪里生效，避免误解替换范围。","example":"定义宏SIZE后，标识符SIZE可展开，字符串\"SIZE\"保持原样。"},"concept:成员选择语义":{"definition":"结构体或联合体对象用点号选成员，指向它们的指针用箭头选成员。","purpose":"用于访问组合数据中的具体字段。","example":"若p指向结构体对象，p->age与(*p).age选择同一成员。"},"concept:结构布局":{"definition":"结构体成员按声明顺序存放，成员之间和末尾可能有填充，首成员前没有。","purpose":"用于理解对象大小、对齐和二进制存储。","example":"含char和int的结构体，其sizeof可能大于两成员大小之和。"},"concept:位表示与掩码":{"definition":"掩码用特定位模式配合按位与、或、异或等操作，选择或改变整数中的位。","purpose":"用于管理标志位、提取字段和设置位值。","example":"对unsigned int变量flags执行flags|=4u，可置位编号2的位。"},"concept:输入转换匹配":{"definition":"格式化输入按转换说明解释字符，目标指针类型须匹配，并应检查成功赋值数。","purpose":"用于把输入文本正确存入对应类型对象。","example":"读取double变量x使用scanf(\"%lf\",&x)，返回1才表示赋值成功。"},"concept:输出格式化":{"definition":"格式化输出按格式串组织文字，各转换说明必须与提升后的实参类型匹配。","purpose":"用于控制数据的显示形式、宽度和精度。","example":"printf(\"%.2f\",1.25); 将浮点数按小数点后两位输出。"},"concept:缓冲与刷新":{"definition":"流可先把数据暂存在缓冲区；fflush对输出流刷新，不能用于刷新标准输入。","purpose":"用于及时显示提示或提交尚未写出的输出。","example":"输出无换行提示后调用fflush(stdout)，并检查返回值是否为EOF。"},"concept:文件位置状态":{"definition":"文件流的位置指示器记录当前读写位置，读写和合法的定位操作会改变它。","purpose":"用于顺序处理文件或重新访问指定位置。","example":"对可定位的流调用rewind(fp)，可回到开头并清除错误指示。"},"concept:读写结果判断":{"definition":"输入输出函数通过返回值报告完成数量或失败，文件结束与读写错误应区分。","purpose":"用于确认数据是否处理成功，避免使用无效结果。","example":"fread要求读十项却返回六项时，应再用feof和ferror判断原因。"},"concept:字符与字符串边界":{"definition":"字符是单个字符值；C字符串是以空字符结尾的字符序列，存储须容纳终止符。","purpose":"用于计算容量，避免扫描或写入越界。","example":"char word[]=\"cat\"; 包含三个可见字符及一个结尾空字符。"},"concept:内存重叠":{"definition":"两个内存区域共享至少一个字节就是重叠，复制时必须满足所用函数的要求。","purpose":"用于选择安全的复制方法，防止未定义行为。","example":"数组内部移动相邻一段数据可能重叠，应使用memmove而非memcpy。"},"concept:选择排序":{"definition":"一种排序方法，每趟从未排序部分选出最小项，放到该部分开头。","purpose":"逐步排好数据，便于后续查找和处理。","example":"将数组6、2、5升序排列，首趟交换6与2。"},"concept:循环不变式":{"definition":"在循环每次条件判断时都成立、且由循环体保持的性质。","purpose":"连接初始状态与结束结果，帮助证明循环正确。","example":"累加数组时，每轮开始的总和等于此前已处理各项之和。"},"concept:块注释":{"definition":"C语言中以/*开始、以*/结束的注释，可跨行但不能嵌套。","purpose":"解释代码含义，注释内容不参与程序执行。","example":"在变量声明前写/* 单价，单位为元 */说明其含义。"},"concept:词法规则":{"definition":"规定源代码如何识别为关键字、标识符、常量等记号的规则。","purpose":"让编译器正确分辨代码中的基本组成单位。","example":"total2可作变量名，2total因数字开头而不合法。"},"concept:线性扫描":{"definition":"按顺序逐个检查一组数据，通常从首项走到末项，每项处理一次。","purpose":"用于查找、计数或汇总，避免漏项。","example":"依次查看七天温度，统计超过三十度的天数。"},"concept:局部极值":{"definition":"元素与附近元素比较得到的极大或极小值，邻域及是否严格须先约定。","purpose":"用于寻找序列中的峰谷和转折位置。","example":"序列1、6、3中，中间项严格大于左右相邻项。"},"concept:连续段":{"definition":"在指定顺序中位置相邻、没有跳项的一段元素，不要求数值连续。","purpose":"用于描述区间、批量处理及存储布局。","example":"数组下标二至五构成连续段，下标二和四单独不算。"},"concept:原地更新":{"definition":"直接修改原有存储中的数据，通常只借助少量额外空间完成操作。","purpose":"用于减少额外存储和数据复制开销。","example":"交换数组首尾元素，仅用一个临时变量保存中间值。"},"concept:稳定筛选":{"definition":"按条件保留部分元素，并使保留元素的相对先后顺序与原来一致。","purpose":"用于提取目标数据并保留原有次序。","example":"从5、2、7、4中筛出奇数，依次得到5、7。"},"concept:累积量":{"definition":"遍历过程中保存阶段结果、随着新数据不断更新的变量，如总和或计数。","purpose":"用于逐步汇总数据，得到整体结果。","example":"统计购物数量时，每读入一件商品就把计数加一。"},"concept:特殊值约定":{"definition":"事先指定某个值表达未找到、失败等状态，须避免与正常结果混淆。","purpose":"用于让调用者识别结果之外的状态。","example":"查询合法编号为正数的商品时，约定零表示不存在。"},"concept:逻辑行":{"definition":"预处理所使用的源代码行及其编号，可由#line指令调整对应关系。","purpose":"用于诊断定位及生成代码的来源映射。","example":"设置#line 200后，下一行的__LINE__展开为200。"},"concept:字节偏移":{"definition":"某位置相对指定起点相隔的字节数，必须明确起点及采用的字节单位。","purpose":"用于定位二进制数据和建立位置索引。","example":"二进制文件中，首字节偏移为零，第六字节偏移为五。"},"concept:定长记录":{"definition":"每条记录占用相同字节数的数据组织方式，字段含义由格式另行规定。","purpose":"用于按编号直接计算记录存储位置。","example":"每条记录八字节，则下标二的记录从偏移十六处开始。"},"concept:稳定归并":{"definition":"合并已有序的序列，保持排序，并按约定保留相等关键字的先后关系。","purpose":"用于合并有序数据并保留同值次序。","example":"按分数归并名单，同分时先取左侧，保留各侧原顺序。"},"concept:分块读写":{"definition":"利用缓冲区分批读取和写出数据，每批处理实际读到的数量。","purpose":"用于限制内存占用并减少读写调用。","example":"用百字节缓冲区复制文件，最后只读到七字节就写七字节。"},"concept:换行规范化":{"definition":"按明确规则把不同换行表示转换为统一形式，同时保留其他数据。","purpose":"用于统一文本格式，方便后续处理。","example":"整理日志时，把约定识别的不同换行都转换成单个换行符。"},"concept:游程编码":{"definition":"把连续重复的数据表示为重复次数和数据值，记录布局由编码格式规定。","purpose":"用于压缩连续重复较多的数据。","example":"连续五个字母A可记作次数五和值A，解码时还原。"},"concept:格式匹配失败":{"definition":"格式化输入时，输入内容不符合当前转换要求，无法完成该次转换。","purpose":"用于识别输入格式错误并安排后续处理。","example":"scanf用%d读取字母q会匹配失败，该字母仍留在输入流中。"},"concept:浮点常量":{"definition":"源码中表示浮点数的记号；十进制形式须有小数点或指数，默认类型为double。","purpose":"用于在表达式中直接写出浮点数值。","example":"常量0.75f带有f后缀，因此类型为float。"},"concept:科学计数法":{"definition":"用尾数乘以基数的整数次幂表示数；C的十进制写法用e或E引出指数。","purpose":"用于紧凑表示很大或很小的数值。","example":"常量2.5e-3表示二点五乘十的负三次方。"},"concept:测试用例":{"definition":"为检查程序而准备的一组输入、运行条件和依据规格确定的预期结果。","purpose":"用于核对实际行为是否满足要求。","example":"测试绝对值函数，输入负七，预期返回正七。"},"concept:反例":{"definition":"满足讨论前提、却使某个普遍断言不成立的具体实例，一个就足以否定断言。","purpose":"用于推翻错误判断并暴露遗漏条件。","example":"声称所有整数的平方都为正，整数零就是反例。"},"concept:边界值测试":{"definition":"重点检查合法范围端点、临界位置及其附近取值的测试方法。","purpose":"用于发现越界、漏项和临界判断错误。","example":"容量十的容器，检查装入零件、九件和十件时的行为。"},"concept:规格说明":{"definition":"明确规定程序的输入、输出、处理规则和约束，作为实现与验收依据。","purpose":"用于统一需求理解并判断结果对错。","example":"规定排序函数按升序输出，并保留相同元素的原有次序。"},"concept:算法设计":{"definition":"在需求明确后，安排解决问题的有限步骤，并选择相应的数据组织方式。","purpose":"用于形成可实现、可分析的求解方案。","example":"查找有序名单时，设计每次比较中间项并缩小范围的步骤。"},"concept:数据依赖":{"definition":"某次计算需要另一次计算产生的数据，因此两者执行顺序受到约束。","purpose":"用于分析计算顺序及能否并行执行。","example":"先计算总价，再按总价计算折扣，折扣计算依赖总价。"},"concept:可复现性":{"definition":"保留明确的输入、程序版本和环境条件，使他人能够重复观察到相同现象。","purpose":"用于核验结果并帮助定位程序问题。","example":"报告崩溃时附上触发输入、编译选项、版本和实际报错。"},"concept:输入空白字符":{"definition":"输入中的空格、换行、制表等字符。scanf的多数数值转换会先跳过它们，%c等转换则有不同规则。","purpose":"区分输入流实际含有哪些字符，与转换会读取或跳过哪些字符。","example":"读取整数前有一个制表符时，%d通常会先越过它再尝试读数。"},"concept:scanf空白指令":{"definition":"scanf格式串中的空白字符是匹配指令，会读取并跳过连续输入空白，直到首个非空白字符或输入结束。","purpose":"它不等于只读一个空格，也不会把遇到的首个非空白字符一起吞掉。","example":"格式中的制表符与普通空格都可表示跳过输入中的连续空白。"},"concept:有符号算术溢出":{"definition":"有符号整数算术的数学结果超出该运算结果类型可表示的范围。C中这通常属于未定义行为。","purpose":"比较或计算前检查取值范围，不能默认按固定二进制回绕得到可靠结果。","example":"两个各自合法的较大正整数相加，其数学结果仍可能超出int的上界。"}}};
